    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Open-bins pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over wasting it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: fresh bin only attractive when the
    // item is large or existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        let need_new = (item_size as f64 > mean_residual + 15.0)
            || (open_bins_count == 0)
            || (fragmentation > 30.0 && post_residual > 20.0);
        if need_new {
            score -= 35.0 + 20.0 * progress;
        } else {
            score += 45.0; // keep filling existing bins when reasonable
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is big and this bin cannot host it anyway, slight penalty
    // for burning a versatile large residual on a small item.
