pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a superlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted space
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement (perfect pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Time horizon: early in the stream, be conservative with new bins
    // (long horizon means wasted space compounds); late in stream, allow
    // tighter packing preferences to dominate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.7 + 0.6 * progress;

    // Global state: many open bins with high mean residual -> prefer
    // filling existing bins to consolidate.
    if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
        score -= 15.0;
    }

    // New-bin candidate penalty: only open a new bin when the item is large
    // relative to residual and existing fits are poor. Empty-bin call has
    // post_residual == capacity - item_size; discourage unless item is big.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        // new bin attractive only for large items or when item leaves
        // a residual that likely fits the next item
        let mut new_bin_bonus = 0.0;
        if size_frac > 0.7 { new_bin_bonus -= 20.0; }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_bonus -= 8.0;
        }
        // penalize new bins mid-stream when consolidation is possible
        new_bin_bonus += open_bins_count as f64 * 2.0 * (1.0 - progress);
        score -= new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0;
    }
    // Mid-range dead space (10..=20) is also often unusable.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward tight fits (near-zero residual) proportionally to fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Open-bin pressure: prefer consolidating into few bins, but a new bin
    // (residual == capacity) should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly so it loses to decent fits,
        // but keep competitive against bins with large dead space.
        score += 15.0 + open_bins_count as f64 * 0.5;
    } else {
        score += open_bins_count as f64 * 1.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would be blocked by this residual, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Late-stream consolidation: as stream progresses, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // Slight preference for bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fit is extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item can fit into this bin's post-residual,
    // reward the pairing; otherwise penalize creating a bad residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 10.0;
        }
        // Perfect two-item chain: item + next exactly fill the bin.
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // New-bin candidate handling: empty bins are only attractive when
    // existing fits are poor or many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 25.0;
        // Early in the stream, prefer packing into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        // If many bins are open, spreading is less costly.
        score -= 2.0 * (open_bins_count.min(50) as f64);
        // If the item leaves a large residual in a fresh bin and the next
        // item is small, a new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Global state coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mild penalty when many bins compete for the item (favor any fit is fine,
    // but keep ordering stable via residual dominance).
    score += 0.5 * (fitting_bins_count.min(20) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: superlinear waste for small leftovers that few future items can use.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 30.0 * (10.0 - dead); // tiny leftovers are nearly worthless
        }
    }

    // Reward tight fits (exact or near-exact fill).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, this placement chains well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to gap
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer using it
    // over opening a new bin (avoids wasting an almost-full bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the item is large
    // relative to capacity (poor fit anywhere else) or many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins for small items; relax penalty for large items late in the stream.
        let new_bin_penalty = 60.0 * (1.0 - fill_ratio) * (1.0 - 0.3 * progress);
        score += new_bin_penalty;
        // Fragmentation pressure: many open bins with high mean residual -> opening fresh bin
        // can be fine, but if mean residual is low, reuse is cheap; discourage new bin slightly.
        score += 0.1 * mean_residual - 0.5 * open_bins_count as f64;
    } else {
        // Reusing an existing bin: reward keeping the spread of residuals tight around mean.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        // Slight preference for filling fuller bins first (best-fit bias beyond raw post_residual).
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

