    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 0.6 * open_bins_count as f64;

    // Penalize bins far below mean residual (fragmented bins) mildly.
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit the post_residual and post_residual is small, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

