    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75 + 0.3 * open_bins_count as f64;
        if post_residual < 10 {
            score += 0.0; // post_residual == capacity here, no dead space yet
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to fit any
    // plausible future item (min item size 1, but practically small gaps
    // under ~10 are dead weight) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium unusable gaps: dead space if next item cannot use them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small waste relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item would leave a large, useful residual or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // More attractive when many bins are open (pressure to distribute).
        score -= open_bins_count as f64 * 0.5;
        // Attractive if placing in existing bins would create tiny dead gaps
        // (proxy: item almost exactly matches nothing).
        if post_residual >= 10 {
            score -= 8.0;
        }
    }

    // Lookahead: if this placement leaves room for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Late in the stream, consolidate: tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size are pure waste — penalize them hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Small but potentially usable gaps: mild penalty scaled by waste ratio.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward very tight fits (best-fit sharpening).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // a reasonable fit exists elsewhere.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.6;
        // Prefer bins with below-average residual (keep large gaps free).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // New-bin candidate: only attractive when current bin would leave a
    // terrible gap or the next item pairs well with a fresh bin.
    if bin_residual == bin_capacity {
        score = 45.0;
        if post_residual >= 10 && fitting_bins_count > 0 {
            score += 40.0; // opening new bins when fits exist is costly
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let pair_waste = (bin_capacity as f64) - (item_size as f64 + next_item_size as f64).min(bin_capacity as f64);
            score += pair_waste * 0.5;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

