pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes mod 10.
    let r = post_residual;
    let class = r % 10;

    // Perfect fits (residual 0) are ideal.
    if r == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space that nothing (min size 1) can be lost on... but small
    // residuals (1..=9) are "harmonically dead" classes if next item can't use them.
    if r > 0 && r <= 9 {
        score += 40.0;
        // If lookahead item exactly matches the dead class, reward instead.
        if next_item_size == r {
            score -= 120.0;
        }
    }

    // Harmonic division thresholds: post_residual in "good" classes divisible by
    // common item sizes (10, 20, 25, 50) keep bins reusable.
    if r % 10 == 0 && r > 0 {
        score -= 15.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 10.0;
    }
    if r % 50 == 0 && r > 0 {
        score -= 10.0;
    }

    // Integer-division threshold: bins whose residual stays above half capacity
    // remain flexible; below quarter capacity they are near-dead.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if r >= half {
        score -= 20.0;
    } else if r < quarter {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == r {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= r {
        // Next item fits but leaves another residual: mild reward scaled by fit quality.
        let next_post = r - next_item_size;
        score -= 10.0 + (next_post as f64) * 0.2;
        if next_post % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > r {
        // Lookahead cannot use this bin's leftover: penalize dead class.
        score += 20.0 + (r as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer filling it rather than leaving it stranded.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Many fitting bins: keep tightest fit preference (post_residual already does this),
    // but add slight tie-break pressure proportional to bin count.
    if fitting_bins_count > 3 {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // and no bin leaves a harmonically useful residual.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 30.0 + 40.0 * (frac - 0.5);
        }
        // Avoid hoarding new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * (1.0 - progress);
        // Opening a new bin wastes the mean residual of existing bins.
        score += mean_residual * 0.3;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's an
    // outlier worth consolidating.
    let diff = mean_residual - r as f64;
    if diff > 15.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

