    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += (pr / cap).powi(2) * 30.0 * (0.5 + 0.5 * p2);
    score -= (pr / cap).powi(3) * 20.0 * (1.0 - p3);

    // Penalize dead space that nothing can use later.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.5 + 2.0 * p2);
        } else {
            score -= (pr - nxt) * 0.5;
        }
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 10.0;

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: discourage unless residuals are large/wasted.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + mean_residual * 0.1;
    }

    // Mild penalty for spreading across many bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are "clean"
    // because items come in multiples of 10 in classic streams; reward them.
    let clean = post_residual % 10 == 0;
    if clean {
        score -= 8.0;
    } else {
        score += (10 - post_residual % 10) as f64 * 0.6;
    }

    // Harmonic class of item_size relative to capacity quarters.
    let quarter = bin_capacity / 4;
    if item_size % quarter == 0 {
        score -= 3.0; // item aligns with capacity grid
    }

    // Integer-division thresholds on post_residual: small dead space is bad.
    let dead_class = post_residual / 10; // 0..10
    if dead_class <= 2 && post_residual > 0 {
        score += (3 - dead_class) as f64 * 5.0; // tiny unusable slivers penalized
    }

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does next item fit harmonically in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward if next item leaves a clean residual too (chained packing)
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 6.0;
            }
            // Reward if next item exactly fills
            if next_post == 0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; slight penalty for wasting capacity
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only prefer it when this bin's fit is poor.
    if bin_residual == bin_capacity {
        // Base new-bin score near mean residual of open bins.
        score = mean_residual * 0.8 + 10.0;
        if post_residual == 0 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Stream progression: late in stream, be greedier about filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, favor tight bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.3;
    }

    // Prefer bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

