                // next item can't use this residual; residual becomes dead space
                score += 8.0;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 60.0;
        } else if fitting_bins_count > 1 {
            // With multiple options, prefer tighter bins — score already scales
            // with post_residual, but add mild tie-break pressure.
            score -= 2.0 * (fitting_bins_count.min(5) as f64);
        }

        // New-bin candidate handling: an empty bin has residual == capacity.
        if bin_residual == bin_capacity {
            // Prefer new bin only late in stream or when many bins open already
            // (keep it slightly worse than a decent fit, better than terrible fit).
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 45.0 - 20.0 * progress;
            if open_bins_count == 0 {
                score -= 100.0; // must open first bin
            }
        }

        // Prefer bins below mean residual (tighter packing) mildly.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1..~30)
    // can use are pure waste. Penalize small post_residuals superlinearly.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr <= 20.0 {
            // tiny unusable sliver -> heavy penalty
            score += (21.0 - pr) * 3.0;
        } else if pr <= 35.0 {
            // moderately hard to fill
            score += (36.0 - pr) * 1.0;
        } else {
            // large residual is reusable -> mild discount
            score -= 5.0;
        }
    } else {
        // perfect fit
        score -= 25.0;
    }

    // Reward tight fits (post_residual small relative to item size)
    let tightness = pr / (item_size.max(1) as f64);
    score += tightness * 6.0;

    // Open-bin pressure: discourage spreading across many bins unless it saves space
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr && pr - nxt <= 10.0 {
            score -= 18.0;
        } else if nxt > pr {
            // next item can't follow here; slightly penalize blocking
            score += 4.0;
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin offers a good fit (mean residual low
    // or item large relative to mean residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // bias toward new bins early when mean residual is fragmented
        let fragmentation = (mean_residual - pr).abs();
        score -= 10.0 + fragmentation * 0.3 + progress * 5.0;
        // but if a perfectly tight fit exists elsewhere, the -25 above wins
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
