pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold even the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: prefer leaving space useful for the next item
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            // Reward bins whose leftover can host the next item, scaled by how snugly
            let snug = 1.0 - (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64);
            score -= 20.0 * snug;
        } else {
            // Penalize leftovers just below the next item size (wasted sliver)
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 15.0 {
                score += 15.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Perfect closure reward: exactly filling a bin is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins over opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
    score += consolidation * 8.0 * (1.0 - 0.5 * progress);

    // New-bin candidate adjustment: an empty bin is only attractive if no open bin
    // fits well; make the empty-bin option mildly unattractive by default
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
        // But if open bins are fragmented (low mean residual), opening fresh is fine
        if mean_residual < 25.0 {
            score -= 20.0;
        }
    }

    // Late-stream bias: as the stream ends, waste matters less; favor any fit
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Penalize large post-residuals more aggressively late in the stream
    score += (norm_pr * norm_pr) * cap * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = norm_item / (norm_item + norm_pr + 1e-6);
    score -= tightness * cap * 0.6;

    // Last-chance bonus: strongly favor using a bin when it's the only fit
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr >= next {
            score -= 8.0 * (next / cap) * (1.0 - progress);
        } else {
            // Dead space for next item: penalize proportionally to waste
            score += ((next - pr) / cap) * cap * 0.25 * (1.0 + progress);
        }
    }

    // Mild penalty for scattering across many open bins
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // New-bin candidate handling: make empty bin moderately attractive only
    // when residuals elsewhere are large or stream is early
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - pr) / cap;
        score -= 12.0 * (1.0 - progress) * (1.0 + mean_gap.max(0.0));
        score += 6.0 * progress * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction left

    // Perfect fit reward: strong subtraction for tiny leftovers.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Harmonic residue classes on post_residual: leftovers that are "usable" sizes
    // (multiples of common small item sizes) are less dead than odd remainders.
    let class_bonus = match post_residual % 10 {
        0 => 40.0,                 // leftover is a clean decade -> likely reusable
        1 | 9 => 5.0,
        5 => 15.0,                 // half-decade still usable
        _ => 0.0,
    };
    score -= class_bonus;

    // Penalize dead space: leftover too small for the smallest plausible item (size 1..10 band).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: reward, more so if the fit is tight.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 30.0 + 50.0 * tightness;
        } else {
            // Next item won't fit here: mild penalty scaled by how far off we are.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + gap.min(50.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Modulo threshold on bin_residual: bins whose residual is in "large half"
    // (residual % capacity > 50) are worth filling with big items.
    if bin_residual > bin_capacity / 2 && item_size > bin_capacity / 4 {
        score -= 20.0;
    }

    // Integer-division class of item size (harmonic bands: small/medium/large).
    let size_band = item_size / 25; // 0..3
    match size_band {
        3 => score -= 15.0,  // large items: place them eagerly to avoid fragmentation
        2 => score -= 5.0,
        _ => {}
    }

    // Stream progression: late in the stream, prefer tighter fits and avoid
    // opening bins that will hold little.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (frac - 0.5).abs(); // late stream: punish non-tight fits

    // Compare against mean residual: bins already below-mean residual are good targets.
    if (pr as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no
    // open bin offers a decent fit; make the empty bin score high unless the
    // stream is early and residual landscape is poor.
    if bin_residual == bin_capacity {
        let early = progress < 0.3;
        if early && open_bins_count < 3 {
            score -= 25.0; // allow a fresh bin early on
        } else {
            score += 150.0; // generally discourage new bins when open bins exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are tiny (unusable for future items)
    // are heavily penalized beyond their raw size.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += (10.0 - gap) * 6.0; // unusable sliver penalty
    } else if gap == 0.0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward filling bins deeply: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 12.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins is relatively less attractive.
    let pressure = (open_bins_count as f64).ln().max(0.5);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement
    // chains nicely; penalize if post-residual is just barely too small
    // for the next item (near-miss dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if gap >= nxt {
            score -= 8.0;
        } else if gap >= nxt - 3.0 {
            score += 5.0; // agonizing near-miss
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when the item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64;
        // Empty-bin waste baseline: penalize by remaining emptiness, softened
        // by how many bins are already open (spreading load can be good early).
        score += base * 0.9;
        score -= (fitting_bins_count as f64) * 4.0; // if others fit, avoid new bin
        if item_size >= 70 {
            score -= 20.0; // large items are fine in fresh bins
        }
        if open_bins_count == 0 {
            score -= base; // no alternative: must open
        }
    }

    // Mild phase awareness: late in the stream, be slightly more greedy
    // about tight fits since fewer future items remain to use gaps.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 3.0 * (1.0 - fill_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but weight by item size
    score = post_residual as f64 * (1.0 + item_size as f64 / (2.0 * bin_capacity as f64));

    // 2-step lookahead: strong reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: residual consumed by next item
        } else if next_item_size <= post_residual {
            // partial reward scaled by how well next item uses the residual
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * use_ratio;
        } else {
            // next item cannot fit here: penalize leaving residual it can't use
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += 5.0 + 0.15 * waste;
        }
    }

    // Compare post_residual against mean residual: leaving less than average is good
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: only this bin fits the item, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless
    // no open bin gives a reasonable fit (post_residual would be huge waste)
    if bin_residual == bin_capacity {
        // new bin starts with post_residual == capacity - item_size
        // favor it only if it beats typical open-bin residuals
        if post_residual as f64 > mean_residual + 20.0 {
            score += 30.0;
        } else {
            score -= 5.0;
        }
    }

    // Late in stream: prefer closing bins tightly (small residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with non-linear squash
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 12.0;
    }

    // Penalize dead space that nothing typical can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 4.0;
        } else {
            score += 3.0; // next item won't fit here anyway
        }
        // If next item can't fit anywhere else but fits here after this item
        if next_item_size <= post_residual && fitting_bins_count <= 2 {
            score -= 8.0;
        }
    }

    // Last-chance bonus: only one bin fits the item; use it rather than open new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when current fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // cheaper to open new bins early in the stream / when many residuals are small
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 5.0;
        // if mean residual is small (open bins are fragmented), new bin is more attractive
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // if this item leaves terrible residue elsewhere, new bin helps
        if item_size > 60 {
            score -= 6.0;
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // -> prefer filling existing bins more aggressively
    let frag = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    score -= frag * 2.0;

    // Mild preference for larger bins when item is large (avoid splitting big space with big items)
    if item_size >= 50 && bin_residual >= bin_capacity {
        score += 4.0;
    }

    // Time-horizon scaling: late in stream, be greedy about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening over stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Smooth penalty for dead space that is too small to be useful later.
    let min_useful = 10.0;
    if pr < min_useful {
        score += (min_useful - pr) * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Lookahead coupling: reward leaving room for the next item (smooth quadratic).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = pr - nx;
        if slack >= 0.0 {
            score -= 8.0 * (slack / cap) * (1.0 - slack / cap);
        } else {
            score += 4.0 * (-slack / cap);
        }
    }

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic),
    // encouraging balanced residual distribution.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // Mild pressure against opening new bins as stream progresses.
    if bin_residual as f64 == cap {
        score += 20.0 + 30.0 * progress - 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (likely dead space) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Class thresholds via integer division of capacity into octiles
    let octant = pr / (bin_capacity / 8).max(1); // 0..8
    match octant {
        0 => score -= 12.0,          // near-perfect fit, reward strongly
        1 => score -= 6.0,
        2 => score -= 2.0,
        3 => {}                       // neutral mid range
        4 => score += 3.0,
        5 => score += 5.0,
        6 => score += 8.0,
        _ => score += 10.0,          // large leftover: poor packing
    }

    // Modulo-10 harmonic: residuals divisible by 10 pair well with
    // typical item sizes; reward them.
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    } else if pr % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this bin becomes a perfect two-item chain.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size < pr {
            let npr = pr - next_item_size;
            // harmonic class of the doubly-post residual
            let n_oct = npr / (bin_capacity / 8).max(1);
            score -= (3.0_f64).max(0.0) * (3 - n_oct.min(3)) as f64;
            if npr % 10 == 0 { score -= 3.0; }
        } else {
            // next item cannot follow: leftover likely dead
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: penalize so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.15 * open_bins_count as f64;
        // If the next item is huge, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Progress-aware mild pressure: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * progress * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward filling a bin exactly with lookahead compatibility.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover can host the next item: mild reward.
            score -= 8.0;
            if post_residual - next_item_size < 10 {
                score -= 6.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // leftover blocks the next item: dead space penalty.
            score += 12.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive if item fits poorly everywhere
    // (large item relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.3;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item now, next may pair with it in fresh bin
        }
        if item_size > 70 {
            score += 20.0; // huge items: keep fresh bins for them
        }
    }

    // Progress-aware tightening: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * (bin_residual - post_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits — penalize proportionally wasted capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // 2-step lookahead: strong reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item won't fit here: penalize more if leftover is small/dead
            let dead = post_residual as f64;
            score += 0.3 * dead;
            if post_residual < 10 {
                score += 25.0; // unusable dead space
            }
        }
    } else {
        // Last item: minimize leftover only.
        score = post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter";
    // prefer filling tighter bins when fit quality is comparable.
    score -= 0.2 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make empty bins attractive only when the item is large
    // relative to typical residuals or when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        // penalize new bins by default; discount penalty when item is big or many bins open
        score += 45.0 - 25.0 * big_item - 10.0 * crowding;
        // if next item is huge, opening a fresh bin now is reasonable
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 15.0;
        }
    }

    // Slight late-stream conservatism: near the end, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strong bonus for very small post-residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items (items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Exact chain fit: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins: mild penalty to prefer spreading load / keep options.
    if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0);
    }

    // Global state coupling: when mean residual is high, prefer reusing bins
    // with residual below the mean (compact them).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
    }

    // Time horizon: late in the stream, be more conservative about new bins
    // and more aggressive about filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate logic: only attractive when current bin fits poorly
    // (large post-residual relative to item) or item is large.
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.35 && waste_ratio > 0.55;
        if poor_fit {
            score -= 18.0;
        } else {
            // Default: opening a new bin is costly.
            score += 15.0 + 3.0 * open_bins_count as f64;
        }
        // If no open bin fits, new bin is the only option; neutralize penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer small post_residual (tight fit), but penalize unusable slivers.
    let mut score = pr;

    // Non-linear dead-space penalty: quadratic in normalized post_residual.
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward near-perfect fits smoothly (post_residual close to 0).
    score -= 8.0 * (-pr / 6.0).exp() * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (0.3 + 0.7 * progress);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (-gap / 8.0).exp();
    } else if next_item_size > post_residual && !is_new_bin {
        // Post-residual too small for next item: mild penalty scaled by dead space.
        score += 3.0 * norm_pr * (1.0 - progress);
    }

    // New-bin candidate: neutral baseline, slightly discouraged early, encouraged
    // when open bins are fragmented (high mean residual spread).
    if is_new_bin {
        score = cap * 0.75 + 10.0 * (1.0 - progress)
            - (mean_residual / cap).max(0.0) * 8.0 * progress
            - open_bins_count as f64 * 0.05;
    }

    // Mild global pressure to consolidate as stream progresses.
    score += (open_bins_count as f64).ln() * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions (1/8 granularity)
    let item_class = (item_size * 8 + bin_capacity - 1) / bin_capacity; // 1..8
    let next_class = if next_item_size == 0 { 0 } else { (next_item_size * 8 + bin_capacity - 1) / bin_capacity };

    // Reward tight fits: post_residual in low harmonic band
    let tight_band = bin_capacity / 8; // 12-ish units
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < tight_band {
        score -= 30.0; // near-perfect fit, dead space unlikely usable
    } else if post_residual < bin_capacity / 4 {
        score -= 10.0;
    } else if post_residual > bin_capacity / 2 {
        score += 15.0; // large leftover: wasteful placement
    }

    // Modulo arithmetic on post_residual: penalize residuals that no common
    // item class can use (residual < smallest class or in dead zone)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Compatibility: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain bonus scaled by how well it fills (harmonic pairing)
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 + 25.0 * fill;
            if next_class == (item_class % 4) + 1 {
                score -= 8.0; // complementary harmonic class
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // residual can't host next item: penalize proportionally
            score += 12.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current residual is
    // badly fragmented or stream is nearly done
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let mut new_bin_penalty = 25.0 + 20.0 * progress;
        if next_item_size > 0 && next_item_size > mean_residual {
            new_bin_penalty -= 30.0; // nothing open can host next item
        }
        if fragmentation > bin_capacity as f64 / 3.0 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Mild pressure to consolidate: prefer bins with residual below mean
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Integer-division threshold: reward placing big items into mid-size gaps
    if item_class >= 5 && post_residual < bin_capacity / 3 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps after placement are almost unusable
    // (items are >= 1, but small leftovers rarely match future demand).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward using a bin whose residual is nearly exhausted by this item
    // (high fill ratio of the consumed space).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few bins, new bins are cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open,
        // and when the item would leave a large hole anyway.
        score += 10.0 + 4.0 * pressure;
    } else {
        score -= 2.0 + 3.0 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoids wasted residual elsewhere).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward leaving that gap; if next item is large and won't fit anyway,
    // a moderately large post_residual is fine.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += 3.0; // gap will be dead for the next item
        } else {
            score -= 4.0; // next item can still use the gap
        }
    }

    // Mild preference for bins below mean residual (keeps residuals balanced,
    // preserving larger gaps across the fleet).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins that end with minimal dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows super-linearly for small leftovers that
        // likely cannot host future items (sizes 1..=100).
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr);
        }
    }

    // Two-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if n <= pr {
            let gap = pr - n;
            // Exact chain fit is excellent; near fits get graded reward.
            if gap == 0.0 {
                score -= 800.0;
            } else {
                score -= 250.0 * (1.0 - gap / 100.0);
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally.
            score += 120.0 * (n - pr).min(100.0);
        }
    }

    // Compare post_residual against mean residual: keeping bin residuals
    // balanced avoids creating one huge and many tiny leftover spaces.
    score += 0.5 * (pr - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; full residual looks "perfect" so
        // counteract that illusion, then relax cost late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 300.0 - 100.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= bin_capacity as f64 {
            // A fresh bin always chains with the next item; slight discount.
            score -= 50.0;
        }
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Slight preference for tighter bins overall (waste minimization).
    score += 0.3 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Strongly reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize bins that become too small for likely future items (dead space).
    // Items range 1..100; residual below ~10 is nearly dead.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Penalize if post residual is a tease: next item just misses.
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score.
    if bin_residual == bin_capacity {
        // Opening new bins early is fine, but prefer reusing bins with decent fits.
        // Base new-bin score slightly above a good fit, below a bad fit.
        score = bin_capacity as f64 * 0.55;
        // Late in the stream, discourage opening new bins more strongly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If many open bins already, discourage yet another.
        score += 1.5 * open_bins_count as f64;
        // If next item is large and current bins are crowded, new bin is attractive.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        // If this bin is the only fitting option, opening a new bin is not needed
        // (item fits elsewhere), so keep new-bin score moderately high.
    }

    // Global state: when mean residual is high, encourage packing into existing bins.
    if bin_residual != bin_capacity {
        score -= 0.15 * mean_residual;
    }

    // Mild penalty for spreading across many bins: encourage consolidation.
    if bin_residual != bin_capacity {
        score += 0.8 * open_bins_count as f64;
    }

    // Slight time-based preference: early on, allow more exploratory bin opening;
    // later, consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - (pr / cap); // fraction of bin used after placement

    // Base: prefer tight fits via non-linear polynomial in post_residual
    let mut score = pr.powf(1.5) * (1.0 + 0.5 * progress);

    // Smooth quadratic coupling of tightness with stream progress:
    // later in the stream, tight fits are worth more
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Cubic interaction: exact fits (small pr) get amplified reward late
    score -= 30.0 * (1.0 - pr / cap).powi(3) * progress;

    // Penalize dead space relative to mean residual (smooth divergence)
    let dead = (pr - mean_residual).max(0.0);
    score += 0.3 * dead * dead / cap;

    // Lookahead coupling: reward if next item fits the post residual (smooth)
    if next_item_size > 0 {
        let fits_next = (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        score -= 25.0 * (1.0 - fits_next).powi(2);
        // penalize leaving space that neither wastes nor helps next item
        score += 0.1 * fits_next * cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild pressure against proliferating bins late in stream
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: smooth penalty scaled by progress and existing bins
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // "dead space" classes (mod 10 near zero) are valuable; large leftovers
    // divisible into coarse chunks are reusable.
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;

    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else {
        let m = post_residual % 10;
        // Dead-space penalty: leftovers like 1..9 are nearly useless.
        if m > 0 && post_residual < 10 {
            score += 500.0;
        }
        // Harmonic reward: post_residual divisible by common item sizes.
        if post_residual % 20 == 0 {
            score -= 40.0;
        } else if post_residual % 10 == 0 {
            score -= 20.0;
        } else if m == 5 {
            score -= 5.0;
        } else {
            score += (10 - m) as f64 * 2.0; // penalize off-class residuals
        }
        // Fraction-of-capacity classes: quarter / half / three-quarter leftovers
        let frac = post_residual as f64 / cap;
        if (frac - 0.5).abs() < 0.05 {
            score -= 30.0;
        } else if (frac - 0.25).abs() < 0.05 || (frac - 0.75).abs() < 0.05 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if next item fits harmonically into post_residual,
    // reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if ni <= pr {
            let slack = pr - ni;
            if slack == 0 {
                score -= 200.0; // chain perfect fit
            } else if slack < 10 {
                score += 60.0; // next item creates dead space
            } else if slack % 10 == 0 {
                score -= 50.0; // harmonic chain
            }
        } else {
            // next item won't fit here; a small post_residual is fine (bin closes well)
            if post_residual < 10 {
                score -= 80.0;
            } else {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: cost of one extra bin, discounted late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.9 - 40.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Mild pressure toward tighter bins when many are open.
    score -= mean_residual.min(cap) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0,10) is nearly unusable
    // (min item size is 1..100, but small gaps waste capacity). Penalize
    // non-zero small gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit reward: strong bonus for exact packing.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit reward: reward small usable residuals relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize bins whose residual is much larger than the mean (poorly matched).
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when there are many open bins.
    score += 3.0 * open_bins_count as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoids unnecessary bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // If next item would be blocked by the remaining gap, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins fit poorly (large item, tight residuals, many open bins).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64;
        // Discount when item is large and current bins are crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowdedness = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        score -= 60.0 * (item_size as f64 / bin_capacity as f64) * crowdedness;
        score -= 20.0 * progress;
        // If no open bin fits, opening a new bin is necessary/cheap.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chain), penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 40.0; // perfect 2-step chain: fill now, fill next
        } else if diff <= 10.0 {
            score -= 25.0 - 2.5 * diff; // graded near-match reward
        } else {
            // mismatch: dead space risk grows the smaller the leftover
            score += (nxt - diff).abs().min(30.0) * 0.3;
        }
        // If the next item cannot fit in the post-residual, penalize wasted chain
        if (post_residual as u32) < next_item_size {
            score += 8.0;
        }
    }

    // Small unusable leftovers are dead space: penalize sharply
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Relative-to-mean residual: bins with residual far above mean are
    // "loose"; prefer filling them to consolidate.
    let res = post_residual as f64;
    score -= 0.5 * (res - mean_residual);

    // Prefer tight fits overall: reward small post_residual relative to capacity
    score -= (bin_capacity as f64 - res) * 0.1;

    // New-bin candidate: only attractive when open bins are very full
    // (high mean residual) or stream is early and many bins will be needed.
    if bin_residual == bin_capacity {
        score += 12.0; // default penalty for opening a new bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual > 25.0 {
            score -= 0.4 * mean_residual; // existing bins crowded -> new bin ok
        }
        if progress < 0.2 {
            score -= 6.0; // early stream: build capacity ahead
        }
        if next_item_size > 0 && next_item_size as f64 > res * 0.9 {
            score -= 5.0; // next item large: fresh bin helps chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits in the post residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.5 * bin_capacity as f64
            && fitting_bins_count > 0;
        let early = (step_index as f64) / (total_items.max(1) as f64) < 0.3;
        if poor_fit {
            score -= 20.0; // opening a bin is fine when fits are wasteful
        } else {
            score += 40.0; // keep using existing bins for decent fits
        }
        if early {
            score += 10.0; // later on, prefer consolidation
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins below mean residual (balance / spread load).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Late stream: tighten packing, reward fuller bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: penalize large post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Quadratic coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, tighten packing
    score += 20.0 * pr_norm * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits (small post-residual) more strongly as stream progresses
    score -= 15.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Interaction: item size vs residual — penalize wasting space on big items
    score += 10.0 * fit_ratio * pr_norm * (1.0 + progress);

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap) * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * (1.0 - pr_norm);
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    score += 3.0 * (pr - mean_residual) / cap;

    // New-bin candidate: mild penalty so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fraction classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Integer-division thresholds on post_residual: classify dead space
    let cls = post_residual / 10; // 0..=10 harmonic class
    match cls {
        0 => score -= 40.0,                 // near-perfect fit, reward strongly
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score += 5.0,                  // awkward ~30-39 dead space
        4 => score += 10.0,
        5 => score += 14.0,                 // half-full residual worst zone
        6 => score += 10.0,
        7 => score -= 3.0,
        8 => score -= 8.0,
        9 => score -= 15.0,
        _ => score -= 25.0,                 // mostly empty bin
    }

    // Modulo arithmetic: post_residual divisible classes
    if post_residual % 10 == 0 {
        score -= 6.0; // round residual tends to be reusable
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0; // chain placement possible
            // exact harmonic match bonus
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3; // dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using it before opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual + 1.0);
        score = cap - pr + 20.0 + pressure * 3.0;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Stream progression: tighten packing toward the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * frac;

    // Deviation from mean residual: prefer bins below mean (denser)
    score += (mean_residual - pr) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..=10)
    // can usefully fill are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 4.0 * post_residual as f64; // worst for tiny unusable gaps
    }
    // Medium dead zones (11..30) are partially wasteful too.
    if post_residual > 10 && post_residual <= 30 {
        score += 8.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual && post_residual - next_item_size <= 5 {
            score -= 20.0;
        }
        // If next item cannot fit here and residual becomes dead space, penalize.
        if next_item_size > post_residual && post_residual <= 10 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless the fit is excellent.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large relative to capacity
        // or when existing residuals are large (poor fits elsewhere).
        score += 20.0 + pressure;
        if item_size >= 60 {
            score -= 15.0;
        }
        if mean_residual > 40.0 {
            score += 10.0;
        }
    } else {
        score -= pressure * 0.5;
    }

    // Slight preference for balancing residuals toward the mean early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual).abs() * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: penalize wasted space quadratically (dead space is unusable).
    let mut score = post_residual as f64 * post_residual as f64;

    // Aggressive 2-step lookahead: perfect match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight 2-step matches heavily.
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)).min(1.0).max(0.0);
        // Exact chain: next item exactly fills the bin -> huge reward.
        if next_item_size == post_residual {
            score -= 120.0;
        }
        // Slightly larger next item than post_residual means future bin may absorb it;
        // mild penalty for leaving a gap just under next_item_size.
        if gap > 0.0 && (post_residual as i64 - next_item_size as i64) < 0 {
            score += 8.0;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins whose post_residual deviates
    // favorably (below mean) to consolidate small leftovers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // give poor fits. Penalize opening a new bin mildly, scaled by stream
    // progress and how well the item would fit there.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // New bin's post_residual is large -> base already penalizes it.
        // Add extra penalty early (consolidate first), relax late.
        score += 25.0 * (1.0 - 0.5 * progress);
        // If item nearly fills a fresh bin, opening is actually good.
        if post_residual as f64 <= 0.15 * bin_capacity as f64 {
            score -= 45.0;
        }
    }

    // Mild reward for using fuller bins (tighter packing).
    score -= 0.2 * (bin_residual as f64 / bin_capacity as f64) * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space), with non-linear penalty.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize very small post-residuals only if the leftover is unusable
    // relative to the lookahead item; otherwise reward perfect closure.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover can host the next item: reward mildly
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // dead space relative to lookahead: penalize quadratically
            let waste = (next_item_size - post_residual) as f64;
            score += 0.08 * waste * waste;
        }
    } else {
        // last item: minimize leftover as much as possible
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    // Time horizon: early in stream, prefer keeping residuals flexible
    // (penalize near-empty placements); late, greedily fill.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let flexibility = (post_residual as f64 / bin_capacity as f64 - 0.5).abs();
    score += 10.0 * (1.0 - progress) * flexibility;

    // Compare against mean residual: bins far below mean residual are
    // already tight; using them is efficient.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 4.0 * (1.0 - rel);
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced when current bins are
        // fragmented or the item is large relative to typical residual.
        let fragmentation = (mean_residual / bin_capacity as f64).min(1.0);
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 35.0 - 20.0 * fragmentation - 10.0 * large_item;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can also host the big next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual in [0,1]
    let x = post / cap;

    // Base: reward small post-residual (tight fits), with non-linear shaping
    let mut score = x * x * (3.0 - 2.0 * x); // smoothstep: penalizes mid-range residual more

    // Polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (large residual OK); late, demand tight packing
    let tightness = 1.0 - progress;
    score += 40.0 * x * x * tightness;      // early: extra penalty for small leftover
    score -= 30.0 * x * x * x * progress;   // late: reward tight fits more strongly

    // Coupling with mean residual: prefer bins below mean residual (tighter than average)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev - 8.0 * dev;

    // Dead-space avoidance: post-residual too small for typical next items is wasted
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let waste = (post - nx) / cap;
        if waste < 0.0 {
            score += 6.0 * (-waste) * (-waste); // next item can't fit here
        } else {
            score -= 4.0 * waste * (1.0 - waste); // next item fits well: bonus
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mild penalty for proliferating bins early
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it neutral-to-slightly-poor unless open bins are bad fits
    if bin_residual == bin_capacity {
        score += 12.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual modulo capacity fractions.
    // Residuals in (0, 10] are "dead space" -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    } else if post_residual > 50 {
        score -= 8.0; // large leftover is reusable
    }

    // Perfect fit: zero waste is always best.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic coupling: can next_item_size land exactly in the leftover?
    // Class the leftover by quarters of capacity.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chain perfect fit
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // reward if the chained placement also leaves a harmonic class
            if nxt_post == 0 {
                score -= 35.0;
            } else if nxt_post <= 10 {
                score += 15.0; // chains into dead space
            }
        } else {
            // leftover cannot host the next item: penalize proportionally
            score += (next_item_size as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave tiny waste
    // or when the item barely fits anywhere.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 25.0;
        // but if placing in any open bin creates dead space <= 5, prefer new bin
        if post_residual <= 5 && post_residual > 0 {
            score -= 45.0;
        }
        if next_item_size > 0 && item_size >= 60 && next_item_size >= 60 {
            score -= 20.0; // two big items pair naturally in a fresh bin
        }
    }

    // Slight preference for fuller bins (waste-avoidance tiebreak).
    let fullness = 1.0 - (bin_residual as f64) / cap;
    score -= fullness * 5.0;

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
