    }

    // Late-stream consolidation: as stream progresses, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // Slight preference for bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect 2-step match: post_residual exactly equals next item size
        // -> chain two items into this bin, huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits exactly into the current residual before placement
        // (i.e., post_residual == next_item_size already covered); also reward
        // near-perfect matches with a decaying bonus.
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + diff * diff * 0.05);

        // Penalize leaving a residual that the next item can almost-but-not fit
        // into (dead space trap): post_residual just below next_item_size.
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    } else {
        // Last item: pure tightness reward.
        score -= 15.0;
    }

    // --- Tightness relative to mean residual ---
    // Bins tighter than average (small residual) are precious; using them
    // for large items is good. Reward placing into below-average bins.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = res / mean_residual;
        if rel < 0.5 {
            score -= 8.0 * (0.5 - rel); // filling a tight bin well
        } else if rel > 1.5 {
            score += 4.0 * (rel - 1.5); // wasting a loose bin's flexibility
        }
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Only this open bin fits; avoid opening a new bin unless post_residual
        // is very wasteful (large dead space).
        if post_residual <= 15 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base penalty so we prefer existing bins,
        // but allow opening when the best existing fit would leave large waste.
        // Compare against the waste this placement creates (zero for new bin
        // beyond post_residual = capacity - item).
        let waste_here = post_residual as f64;
        let mut penalty = 30.0;
        // If lookahead next item is huge and current residual can't hold it
        // anyway, opening fresh is fine.
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            penalty -= 15.0;
        }
        // Late in stream, keep bins open (fewer bins matter more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 10.0 * progress;
        // If this placement leaves very small residue, new bin is attractive.
        if waste_here <= 5.0 {
            penalty -= 25.0;
        }
        score += penalty;
    }

    // Slight preference for bins with small pre-residual (best-fit core).
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can't fit typical future items (below min size).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the bin that wastes least relative to others.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a residual the next item just barely misses.
            let miss = (post_residual as f64 - next_item_size as f64).abs();
            if miss < 10.0 {
                score += 10.0;
            }
        }
    }

    // Prefer bins with residuals close to the mean (keep residuals homogeneous),
    // but only when many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Time horizon: late in the stream, consolidate aggressively (avoid new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheaper early, expensive late.
        score += 15.0 + 40.0 * progress;
        // Opening a new bin is more acceptable if no bin fits well.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If the next item is large, a fresh bin is attractive.
        if next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Late stream: reward using existing bins more.
        score -= 10.0 * progress;
    }

    // Mild penalty for very large items into already-crowded bins (fragmentation risk).
    if item_size > 60 && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post_residual (tight fit), with non-linear sharpening
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling with stream progress:
    // late in the stream, dead space matters more (no future items to fill it)
    let dead_weight = 0.5 + 3.0 * progress * progress * (2.0 - progress);
    score += dead_weight * norm_post * norm_post * cap;

    // Reward filling a bin almost completely, more aggressively as stream advances
    let fill = 1.0 - norm_post;
    score -= (1.0 + 2.0 * progress) * fill * fill * fill * 6.0;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    } else {
        // slight penalty when many bins compete (avoid scattering)
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: smooth interaction between post_residual and next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (post - nx).max(0.0);
        let usable = 1.0 - (fit_next / cap);
        score -= 3.0 * progress * usable * (nx / cap);
        // penalize leaving residual just barely below the next item (dead zone)
        let miss = if post < nx { (nx - post) / cap } else { 0.0 };
        score += 5.0 * miss * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (keep balanced residuals late)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.4 * progress * dev;

    // New-bin candidate: make empty bin slightly unattractive unless residuals are terrible
    if bin_residual == bin_capacity {
        let avg_dead = mean_residual / cap;
        score += 4.0 + 10.0 * avg_dead * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        // Reward post-residuals that are multiples of small harmonic bases
        // (common item sizes 10, 20, 25, 50), making leftovers reusable.
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 4.0; }
        if pr % 20 == 0 { bonus += 3.0; }
        if pr % 25 == 0 { bonus += 3.0; }
        if pr % 50 == 0 { bonus += 5.0; }
        score -= bonus;

        // Penalize dead space: leftover too small to hold even a minimum item
        // (assuming min size ~10) is pure waste.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }

        // Integer-division class: leftover in the "awkward middle band"
        // (e.g. 21..=29, 31..=39) is harder to fill than round bands.
        let band = pr / 10;
        match band {
            2 | 3 => score += 3.0,
            5 => score += 2.0,
            _ => {}
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 20.0;
        } else if pr > next_item_size {
            let nxt_post = pr - next_item_size;
            if nxt_post % 10 == 0 { score -= 5.0; }
            if nxt_post < 10 { score += 6.0; }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how much of the leftover would be stranded.
            let stranded = (next_item_size - pr) as f64;
            score += stranded * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins offer poor fits. Give it a moderate baseline score so good fits
    // in open bins (low post_residual, bonuses) beat it.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream or when
        // many bins are open and mean residual is high (fragmented state).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = (bin_capacity - item_size) as f64 + 12.0
            - 6.0 * progress
            + if open_bins_count > 0 { mean_residual * 0.05 } else { 0.0 };
    }

    // Mild pressure toward filling fuller bins first (smaller residual => lower score).
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    } else {
        // Larger residual space: mild quadratic penalty to prefer tight fits
        let r = post_residual as f64;
        score += 0.05 * r * r / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item cannot use this gap; penalize proportionally
            score += 0.3 * (post_residual as f64);
        }
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are healthy.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 - progress);
    score += 0.5 * pressure;

    // Mean residual coupling: if this bin's residual is below mean, it's tighter than average -> prefer.
    let diff = mean_residual - bin_residual as f64;
    score += 0.1 * diff;

    // New-bin candidate handling: only attractive when no good fits exist.
    if bin_residual == bin_capacity {
        // penalize opening new bin, but less when many bins are open and fragmented
        score += 20.0 - 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin guarantees room for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
        // chain fit: item + next item leaves small remainder again
        let chain_res = post_residual - next_item_size;
        score -= 0.3 * chain_res as f64;
    } else if next_item_size > 0 {
        // penalize dead space that cannot fit the lookahead item
        score += 0.4 * post_residual as f64;
    }

    // Compare post_residual relative to mean residual of open bins
    score += 0.2 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or no good fit exists (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score += 40.0 + 0.6 * waste as f64;
        // opening a new bin is attractive when item is big (little waste)
        if item_size >= bin_capacity / 2 {
            score -= 55.0;
        }
        // late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on leftover space.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * pr;

    // Strong reward for perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size <= bin_residual {
            // next item could still fit this bin now, but our placement kills that.
            score += 4.0;
        }
        // If next item is small relative to post residual, extra reward.
        if next_item_size > 0 && post_residual >= next_item_size + 10 {
            score -= 2.0;
        }
    }

    // Penalize leaving dead space in bins with small residuals (unusable fragments).
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Global state: with many open bins, prefer consolidating into fuller bins.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fullness * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Prefer bins whose residual is above the mean (balance residuals).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be more open to new bins; late, squeeze into existing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - progress) - 4.0 * progress;

    // New-bin candidate: neutral-ish baseline; open a new bin only when fit is poor
    // or the bin is empty and item is large.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fit_everywhere = fitting_bins_count <= 1 && pr > 15.0;
        if large_item || poor_fit_everywhere {
            score -= 10.0;
        } else {
            score += 20.0 + 0.5 * (open_bins_count as f64).min(20.0);
        }
    }

    // Mild preference for bins that can still hold a mid-size future item.
    if post_residual >= 30 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * p2 * norm_pr * norm_pr;
    score -= 20.0 * p3 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Reward tight fits smoothly, more so later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space near mid residuals with smooth bump
    let bump = 4.0 * norm_pr * (1.0 - norm_pr);
    score += 10.0 * bump * bump;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Smooth penalty relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual) * (0.3 + 0.7 * progress);

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_next = ((pr - n) / cap).max(0.0);
        score -= 8.0 * fit_next * fit_next * (1.0 - progress);
        if n > pr {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Slight preference for consolidating into fewer bins
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it neutral-ish but slightly penalized so it
    // only wins when open bins would create large dead space
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into capacity
    // fractions are more reusable. Classify post_residual by its class
    // relative to common capacity fractions (100: 50, 25, 20, 10).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward: zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residue bonus: post_residual that is a multiple of 10 or 25
    // leaves reusable "harmonic" space for typical item sizes.
    let harmonic = (post_residual % 10 == 0) as f64 * 8.0
        + (post_residual % 25 == 0) as f64 * 6.0
        + (post_residual % 5 == 0) as f64 * 3.0;
    score -= harmonic;

    // Penalize small awkward dead space (unusable for items 1..100 range
    // typical sizes): residual in (0, 15) is nearly dead.
    if post_residual > 0 && post_residual < 15 {
        score += 20.0;
    }

    // Coupling with lookahead item: if next item fits exactly into the
    // post-residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover after next placement matters.
            let post2 = post_residual - next_item_size;
            if post2 == 0 {
                score -= 40.0;
            } else if post2 < 10 {
                score += 10.0; // creates tiny dead space
            } else {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: slight penalty for trapping the bin.
            score += 4.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it
    // wins only when fits into open bins are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, opening bins is cheaper; later, prefer filling.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (tighter bins first keeps larger residuals available).
    score -= 0.5 * (mean_residual - pr).max(0.0);
    score += 0.3 * (pr - mean_residual).max(0.0);

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    // Integer-division threshold: post_residual in the "half-bin band"
    // (>= half capacity) is very reusable.
    if post_residual >= bin_capacity / 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1) can use
    // are worthless; gaps below the typical minimum (10) are nearly worthless.
    if post_residual == 0 {
        score -= 50.0; // perfect fit: strongly reward
    } else if post_residual < 10 {
        score += 25.0; // unusable dead space: strong penalty
    } else {
        // Usable residual: mild reward proportional to how well it could
        // host the lookahead item, otherwise keep base cost.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // residual remains useful for lookahead
        }
        // Fractional dead-space pressure: smaller usable gaps are less flexible
        score += (10.0 - (post_residual.min(60) as f64) / 6.0).max(0.0);
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Open-bin pressure: when many bins are open, discourage adding new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // New bin: penalize base cost plus pressure from open bins and mean residual.
        score += 10.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.1;
        // Late in the stream, opening new bins is less costly (fewer chances to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= open_bins_count as f64 * 0.5;
    }

    // If lookahead item fits after this placement, extra reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && next_item_size >= item_size {
        // Lookahead won't fit here; slightly favor bins with more residual left
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Aggressive 2-step lookahead: big reward if the next item fits
    // exactly into the post_residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect 2-item completion
        } else if next_item_size <= post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            // Reward chains that leave little dead space after the next item.
            score -= 60.0 * (1.0 - leftover / bin_capacity as f64);
            // Extra reward if chain completes the bin (post_residual == next + 0 slack).
            if leftover <= 5.0 {
                score -= 30.0;
            }
        } else {
            // Next item does NOT fit here: penalize, since this bin's residual
            // is likely to become dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 20.0 + 0.5 * gap;
        }

        // Relative-to-mean coupling: bins with residual far above the mean
        // are "wasteful" targets unless the chain works perfectly.
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        if next_item_size <= post_residual {
            score -= 15.0 * dev;
        } else {
            score += 15.0 * dev;
        }
    } else {
        // Last item: just close out bins as tightly as possible.
        score -= 30.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Slight penalty when many bins are open (encourage consolidation).
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: neutral-ish default, only chosen when open bins
    // score badly. Penalize slightly so good fits win, but keep it
    // competitive when all open bins leave large dead space.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If next item is huge, a fresh bin is attractive for future pairing.
        if next_item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, tighten more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // New-bin candidate: prefer it when item fits poorly everywhere else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins mildly; discount when few fitting bins or big item.
        let mut nb = 20.0 + 15.0 * progress;
        if fitting_bins_count == 0 { nb -= 40.0; }
        if fitting_bins_count == 1 { nb -= 25.0; }
        if item_size as f64 > 0.6 * cap { nb -= 15.0; }
        nb += 0.05 * open_bins_count as f64;
        return nb;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Tight fit reward: small post residual relative to capacity
        score -= 40.0 * (1.0 - post / cap);
    }

    // Penalize dead space that no future item can plausibly use
    let smallest = 1.0f64;
    if post > 0.0 {
        let waste = (post - smallest).max(0.0);
        score += 0.15 * waste;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            // good if next item leaves small remainder too
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: mild penalty for tight fills
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidating
    let spread = mean_residual - post;
    if spread > 0.0 {
        score -= 0.05 * spread;
    } else {
        score += 0.05 * (-spread);
    }

    // Time horizon: early in stream, be picky (favor tight fits more); late, accept fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress) * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with a smooth non-linear penalty
    // that grows super-linearly for large leftover space (wasted capacity).
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Coupling with stream progress: later in the stream, tighter packing matters more,
    // so amplify the post-residual penalty smoothly.
    score += 20.0 * progress * norm_pr * norm_pr;

    // Smooth interaction: penalize leaving residual close to next item's need mismatch.
    let next = next_item_size as f64;
    if next > 0.0 {
        let fit_gap = (pr - next).abs() / cap;
        score += 12.0 * fit_gap * (1.0 - progress);
    } else {
        // End of stream: leftover space is pure waste.
        score += 15.0 * norm_pr;
    }

    // Reward near-perfect fits smoothly (small post residual relative to item size).
    score -= 10.0 * norm_item * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it,
    // smoothly scaled by how tight the fit is.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across too many open bins vs mean residual:
    // prefer bins whose residual deviates smoothly from the mean (consolidation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.5 + 0.5 * progress);

    // Slight preference for fuller bins (low residual) as open bin count grows.
    score += 0.3 * (open_bins_count as f64).ln() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left

    // Perfect fits are golden: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic thresholds: residual in [0,10] -> dead space; [10,25] -> poor;
    // [25,50] -> moderate; >50 -> good reusable space.
    if post_residual <= 10 {
        score += 30.0; // nearly dead space, penalize
    } else if post_residual <= 25 {
        score += 12.0;
    } else if post_residual > 50 {
        score -= 15.0; // plenty of room left, good
    }

    // Modulo arithmetic: residual divisible by common item classes (10s, 5s)
    // is more likely to be filled by future items.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            // next item leaves another residual: penalize small leftovers again
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score += 10.0;
            } else if next_post % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: mild penalty for tight bins
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is large.
    if bin_residual == bin_capacity {
        // new bin score = capacity residual baseline; make it unattractive
        // unless existing best option is bad. Add fixed opening cost.
        score += 55.0;
    }

    // Prefer bins tighter than the mean residual (fill fuller bins first).
    score += (post - mean_residual) * 0.3;

    // Slight preference for reusing bins over spawning many: scale with open bins.
    score += open_bins_count as f64 * 0.05;

    // Stream progression: early on, be more tolerant of new bins (exploration),
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= progress * 20.0;
    } else {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the minimum item size (1..12) are pure waste; scale penalty
    // so tiny residuals become very unattractive.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 15.0;
    }
    // Medium dead space (12..30) is risky: only mid-small items can use it.
    if post_residual >= 12 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 3.0;
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if the post residual cannot hold the next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0);
        } else {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new
    // bins; favor filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (it's an outlier small bin), prefer packing it down.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f).min(30.0) * 0.8;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (large dead space would result). Empty bin residual == capacity gives
    // post_residual == capacity - item_size, which is naturally large; add a
    // fixed opening cost so it's chosen only when genuinely better.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: this bin's leftover
    // exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial reward: next item still fits in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize creating dead space that the next item cannot use,
    // especially when the dead space is small (unusable).
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        let small_dead_penalty = if dead < 10.0 { 25.0 } else { 10.0 };
        score += small_dead_penalty * (1.0 - dead / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless the
    // current item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 - 10.0 * fit_pressure - 5.0 * progress
            + (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Mild normalization relative to mean residual: prefer bins that are
    // already tighter than average (reduces fragmentation).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    // Slight preference for filling fuller bins early in the stream.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual), with a non-linear curve.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward filling the bin nearly completely (waste minimization).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill * fill;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward small residuals.
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 && post_residual < next_item_size {
                score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
            }
            let _ = gap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0;
        // If other bins can fit the item, make new bin less attractive unless
        // their residuals are poor (high mean residual spread).
        if fitting_bins_count > 1 {
            score += 25.0;
        } else if fitting_bins_count == 1 {
            // Only one open bin fits: compare its quality implicitly via mean residual.
            score += 10.0 * (mean_residual / bin_capacity as f64);
        }
        // Early in the stream, opening bins is cheaper (builds future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // Penalize placing into bins whose residual deviates wildly from the mean
        // (keeps a portfolio of usable residuals).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.3 * open_bins_count as f64;

    // Slight preference for using older/more crowded bins early vs late is
    // captured via progress-scaled tightness emphasis.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (quadratic penalty on large residual grows with progress).
    let poly = pr_norm * pr_norm * (0.5 + 2.0 * progress) + pr_norm * (1.0 - progress) * 0.3;
    score += poly * cap;

    // Reward near-perfect fits with a smooth super-linear bonus.
    let fill = 1.0 - pr_norm;
    score -= fill * fill * fill * 8.0;

    // Last-chance bin: smooth reward when few fitting bins exist.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else {
        score += (fitting_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 3.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        // Next item won't fit: mild smooth penalty scaled by how badly it misses.
        let miss = (next_item_size as f64 - pr) / cap;
        score += 2.0 * miss * miss * cap;
    }

    // Mean residual context: penalize bins far from the fleet mean (smooth quadratic).
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev;

    // New-bin candidate handling: only attractive late in the stream or when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 4.0 * (1.0 - progress) * (1.0 - crowd) * cap * 0.1;
        score -= 2.0 * progress * crowd;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead-space into residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward: post_residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic classes: residual that is a divisor-friendly fraction of capacity
    // (e.g., 0, 10, 20, 25, 50) is more reusable by future items.
    let harmonic_residuals: [u32; 6] = [0, 10, 20, 25, 50, 100];
    if harmonic_residuals.contains(&post_residual) {
        score -= 8.0;
    }

    // Penalize residuals in "awkward" modulo classes (dead space hard to fill).
    let class = post_residual % 10;
    if class != 0 {
        score += (10 - class) as f64 * 0.7; // non-multiples of 10 penalized
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if next item divides post_residual harmonically
            if post_residual % next_item_size == 0 && post_residual > 0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: penalize small unusable leftovers more
            // when next item is large (would need fresh capacity anyway).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when current item is large relative to capacity or
    // mean residual across open bins is too small to help.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Base penalty so we prefer existing bins unless they're bad.
        score += 30.0;
        // If item is huge (>70% of capacity), new bin is attractive.
        if item_frac > 0.7 {
            score -= 35.0;
        }
        // If open bins are mostly full (low mean residual), new bin is fine.
        if mean_residual < item_size as f64 * 0.6 {
            score -= 25.0;
        }
    }

    // Tight-fit reward: leaving very little behind is good (waste minimization).
    if post_residual > 0 && post_residual <= 5 {
        score -= 6.0;
    }

    // Mild stream-progress term: later in the stream, consolidate more eagerly
    // (avoid spreading across bins near the end).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (mean_residual / cap).min(1.0);

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * 5.0;

    // Penalize spreading when many bins are already open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately awkward gaps: partial penalty.
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small but not dead post_residual).
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, strongly prefer
    // placing into existing bins; penalize the new-bin candidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (40.0 + 8.0 * open_bins_count as f64 * (0.5 + progress));

    // Last-chance bin: if this is the only fitting bin, favor it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && new_bin < 0.5 {
        score -= 30.0;
    }

    // Lookahead: if next item could use the post_residual, reward leaving it.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size >= bin_residual {
        // Next item won't fit here anyway; no need to preserve space.
        score -= 5.0;
    }

    // Mild preference toward bins below mean residual (balance keeping
    // larger gaps open for larger future items).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect two-step chain: this item leaves exactly room for the next.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward leaving room for the next item (partial lookahead match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize post-residual that cannot ever be used by the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Favor tight fits relative to current bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize creating small unusable dead space (< 10, min item size).
    if post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins already below-average residual (well-packed).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Slight preference for existing bins over opening a new one early in the stream.
    if bin_residual == bin_capacity {
        score += 8.0 + 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if post-residual closely matches next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins with residual below the mean (filling emptier-looking bins less).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in stream, be picky (penalize mediocre fits);
    // late in stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * fit_ratio;
    score -= 15.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or all fits are terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by item size.
        score = 60.0 - 0.25 * item_size as f64;
        // If no other bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // If the next item is small and this item leaves a big residual that
        // could pair with it, opening is slightly more attractive.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 10.0;
        }
        // Late in the stream, avoid spreading items into new bins.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr_norm = pr / cap;

    // Base: best-fit preference (minimize post residual), with non-linear emphasis
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth stream-progress coupling: later in stream, penalize loose fits more
    score += 30.0 * progress * pr_norm * (1.0 - pr_norm) * 4.0;

    // Lookahead: reward bins whose post-residual can host the next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx) / cap;
        if fit_gap >= 0.0 {
            score -= 12.0 * (1.0 - fit_gap).max(0.0);
        } else {
            score += 6.0 * (-fit_gap);
        }
    }

    // Last-chance bonus: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Mean-residual coupling: when open bins are generally full, avoid wasting space
    let mean_norm = mean_residual / cap;
    score += 10.0 * mean_norm * pr_norm;

    // New-bin candidate handling: only attractive when item is large and no good fit exists
    if bin_residual == bin_capacity {
        let item_norm = item_size as f64 / cap;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score -= 55.0 * item_norm * item_norm * scarcity * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual: classify leftover space by
    // residue classes and integer-division thresholds (capacity = 100). ----
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap; // fraction of capacity left over

    // Dead-space penalty: leftover below the smallest useful class (<= 10
    // or < next_item_size) is nearly unusable. Penalize superlinearly.
    if pr < 10 {
        score += 40.0 * (10.0 - pr as f64);
    }
    if next_item_size > 0 && pr < next_item_size {
        // leftover can't fit the lookahead item -> dead space risk
        score += 12.0 + 0.5 * (next_item_size - pr) as f64;
    }

    // Harmonic residue classes: reward leftovers that are "clean" multiples
    // of common item granularity (residue 0 mod 10 packs well).
    let residue = pr % 10;
    score += match residue {
        0 => -8.0,
        1 | 9 => 6.0,
        5 => -3.0,
        _ => 2.0,
    };

    // Integer-division thresholds on post_residual (capacity classes):
    // leftover in [50,100) is very reusable; [25,50) moderate; <25 poor.
    let class = pr / 25; // 0..4
    score -= match class {
        4 | 3 => 10.0,
        2 => 4.0,
        1 => 0.0,
        _ => -4.0, // tiny leftover: mildly penalized already above
    };

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 15.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into existing bins is bad. Give the empty bin a base offset that
    // scales with how much capacity would be "wasted" by hoarding.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // early in the stream, opening bins is cheaper (future items unknown)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // if current item is large and mean residual is low, new bin is fine
        if (item_size as f64) > 0.6 * cap {
            score -= 15.0;
        }
        // many open bins with low mean residual: discourage another bin
        if mean_residual < 0.3 * cap && open_bins_count > 2 {
            score += 25.0;
        }
        // lookahead big item: reserve this fresh bin for it
        if next_item_size >= 70 {
            score -= 10.0;
        }
    }

    // Mild preference for bins whose residual is close to item size
    // (best-fit flavor) via squared gap, keeping scale moderate.
    let gap = (bin_residual as i64 - item_size as i64) as f64;
    score += 0.02 * gap * gap / cap;

    // Coupling with mean residual: prefer bins below mean residual
    // (concentrate fullness), spreading slack across bins is bad.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit even the smallest
    // plausible item (<= 10) are pure waste; punish them extra hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // If the next item can fit exactly in the post residual, reward this bin
    // (it preserves a perfect chain). Otherwise, if next item would leave a
    // tiny unusable gap again, slightly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 5.0; // bin becomes dead for the lookahead item
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing
    // bins; few open bins -> opening a new bin is less costly.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure and by how much
        // slack existing bins already carry (if mean residual is large,
        // existing bins are roomy, so prefer them).
        score += 10.0 + pressure + (mean_residual / 8.0);
    } else {
        // Existing bin gets a mild discount that grows with pressure.
        score -= pressure * 0.5;
    }

    // Early in the stream, be slightly more willing to open fresh bins to
    // build a good pool of residuals; late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0;
    } else {
        score += progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with tiny leftover
    else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score -= 35.0 - (post_residual - next_item_size) as f64 * 4.0;
    }
    // Next item does NOT fit here: penalize proportionally to how much we miss
    else if next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.35;
    }

    // Penalize small unusable dead space (hard to fill later)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward filling a bin almost completely (relative to capacity)
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins that keep residuals balanced
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Late in the stream: tighten up, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
        // If the next item is large, a fresh bin is fine
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the next item's lookahead.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        } else if post_residual >= next_item_size && post_residual < 2 * next_item_size {
            // post_residual can host the next item: bonus.
            score -= 4.0;
        }
    }

    // Last-chance bonus: this is the only open bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is penalized, more so
    // when many bins are open (consolidation pressure) or the fit elsewhere
    // is decent; less penalized early in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score += 25.0
            + 10.0 * (open_bins_count as f64).ln().max(0.0)
            - 10.0 * (1.0 - progress)
            + 6.0 * waste;
    } else {
        // Reward using bins whose residual deviates below the mean (draining
        // awkward bins first), penalize draining the "best" bins too eagerly.
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Prefer compacting residual toward multiples of small item sizes:
    // penalize residuals in (0,10) which are almost dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let shape = 0.6 + 1.6 * progress * (1.0 - 0.5 * progress);
    let mut score = pr * (1.0 + shape * pr);

    // Penalize dead space more strongly as stream progresses (less time to reuse).
    score += 2.0 * pr * pr * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 1.5 * tightness * (1.0 - pr) * (1.0 + 0.5 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 3.0;
    }

    // Discard new-bin option unless existing fits are poor; new-bin preference grows with progress.
    score += is_new * (2.5 - 1.5 * progress) + is_new * 3.0 * pr;

    // Lookahead: penalize leaving residual that cannot fit next item when it's large.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post_residual as f64 >= nxt) as f64;
        score += (1.0 - fits_next) * (nxt / cap) * (1.5 + progress);
    }

    // Mild regularization by open bins count / mean residual.
    score += 0.05 * (open_bins_count as f64).sqrt() * pr;
    score += 0.3 * (pr - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // Harmonic class of post_residual: exact fills are golden, tiny dead zones are poison.
    if pr == 0 {
        score -= 30.0;
    } else if pr < 10 {
        // residual falls into the "unusable sliver" class for items >= 10
        score += 18.0;
    } else if pr < 20 {
        score += 6.0;
    }

    // Integer-division coupling: how many copies of the next item fit in the leftover.
    if next_item_size > 0 {
        let copies = (pr / next_item_size) as f64;
        if copies >= 1 {
            score -= 10.0 + 4.0 * copies.min(3.0);
        } else {
            // next item cannot reuse this residual: mild penalty, worse for large leftovers
            score += 3.0 + 0.05 * pr as f64;
        }
        // modulo class: leftover nearly matches next item size (tight lookahead fit)
        let gap = (pr as i64 - next_item_size as i64).unsigned_abs();
        if gap <= 5 {
            score -= 8.0;
        }
    }

    // Last-chance bin before opening a new one: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // Phase of stream: early on, keep bins open and flexible; late, chase tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - (pr as f64 / cap));

    // Mean-residual divergence: prefer bins whose residual is close to the fleet mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // New-bin candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let mut nb = 22.0;
        // If other open bins can fit the item, opening a new bin is wasteful.
        if fitting_bins_count >= 1 {
            nb += 25.0;
        }
        // If fleet mean residual already exceeds item size, reuse existing space.
        if mean_residual >= item_size as f64 {
            nb += 15.0;
        }
        // Late in the stream, avoid spawning bins unless nothing fits.
        nb += 8.0 * progress;
        // Early stream with no fitting bin: opening is fine.
        if fitting_bins_count == 0 && step_index < total_items / 4 {
            nb -= 20.0;
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10)
    // can realistically use are hard-penalized dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize bins whose residual is barely above the item (fragile fit
    // that leaves a tiny gap) less harshly than a wide gap, but still
    // prefer exactness: coupling between residual and item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; add pressure term scaled by bin count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 8.0 * (0.5 + progress);

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 55.0;
        // But if this bin is the last chance or nothing fits well,
        // relax the penalty so a new bin beats a dead-space placement.
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        if post_residual < 10 {
            score -= 40.0;
        }
        // Late in the stream, opening fresh bins is less costly.
        score -= progress * 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it rather than leaving it and opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If next item cannot fit in post-residual but could fit in a larger
    // alternative, mildly penalize wasting space the future needs.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual
    // (fill the emptier-feeling bins with the current item).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 40.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // chain of perfect fits
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to wasted space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Relative-to-mean adjustment: bins tighter than average are better targets
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += bin_capacity as f64 * 0.35 + 30.0;
        // but if no existing bin fits well (post_residual large waste), soften
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 40.0; // existing bins would strand the next item anyway
        }
    }

    // Mild preference to fill older bins as stream progresses
    score -= 0.01 * (step_index as f64 / (total_items.max(1) as f64)) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual too small for typical future items.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Next item won't fit here; penalize wasting residual it could have used.
            if next_item_size <= bin_residual {
                score += 10.0;
            }
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when current bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (mean_residual / bin_capacity as f64).max(0.0);
        // Fresh bin penalty scales down as mean residual grows (existing bins nearly full).
        score += 35.0 + 60.0 * (1.0 - crowding) - 25.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big item coming, fresh bin useful
        }
    }

    // Prefer bins below mean residual (keep a balanced spread of leftover space).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Reward tight fits: post_residual near zero is heavily favored, more so late in stream
    score -= cap * (1.0 - norm_pr).powf(2.0) * (0.5 + 0.5 * progress);

    // Penalize mid-range dead space (unusable gaps) with a smooth bump
    score += cap * 0.4 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - ((pr - nxt) / cap).powf(2.0));
        } else {
            score += 4.0;
        }
    }

    // Slight preference for reusing existing bins over opening new ones
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues near "unusable" zones are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes via integer division thresholds on post_residual.
    // Residuals in (0,10] are nearly unusable for items >=10 in classic setting,
    // but with sizes 1..100 only tiny residuals are truly dead.
    if post_residual > 0 && post_residual < 4 {
        score += 60.0; // dead space penalty
    } else if post_residual <= 10 {
        score += 25.0;
    }

    // Modulo arithmetic: residual classes mod 10 — smooth residuals are reusable.
    let m = post_residual % 10;
    if m == 0 {
        score -= 15.0; // round residual is highly reusable
    } else if m >= 7 {
        score += 6.0; // awkward residue
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // reward proportional to tightness of the follow-up fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item won't fit here: mild penalty scaled by how much it overflows
            score += ((next_item_size - post_residual) as f64).min(30.0);
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
        if post_residual > 0 && post_residual < 4 {
            score += 80.0; // but not if it creates dead space
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 50.0;
        // cheaper to open a bin when many items remain and few bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // if next item is large and current item is small, fresh bin preserves big space
        if next_item_size >= 50 && item_size <= 30 {
            score -= 45.0;
        }
        // if current item is huge, a fresh bin is natural
        if item_size >= 60 {
            score -= 25.0;
        }
    }

    // Mean-residual coupling: prefer filling bins whose residual is above average
    // (keeps tight bins for tight fits).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Slight preference for tighter fits overall.
    score -= 0.5 * (item_size as f64) / cap * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 0.6 * open_bins_count as f64;

    // Penalize bins far below mean residual (fragmented bins) mildly.
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit the post_residual and post_residual is small, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral base, opened only when fits are poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75 + 0.3 * open_bins_count as f64;
        if post_residual < 10 {
            score += 0.0; // post_residual == capacity here, no dead space yet
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the post residual can host the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            // This bin can also take the next item: chain bonus scaled by tightness.
            let chain = next / (post_residual as f64 + 1.0);
            score -= 12.0 * chain;
        } else {
            // Dead space penalty: leftover can't host the next item.
            let dead = next - post_residual as f64;
            score += 4.0 * (dead / 100.0);
        }
        // Exact two-item fill (post_residual == next_item_size) is a perfect chain.
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.5 * diff;

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, avoid opening new bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // But if next item is huge and this residual can't ever help, new bin is fine.
        if next_item_size > 0 && next_item_size as f64 > bin_residual as f64 - item_size as f64 {
            score -= 5.0;
        }
    }

    // Mild reward for very tight fits (small post residual) overall.
    if post_residual <= 5 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: post_residual too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual >= 10 && post_residual < 30 {
        // Medium slack is somewhat useful; mild penalty scaled by unusability
        score += 8.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * next_fit * next_fit;
        } else {
            // Next item won't fit here; penalize leaving slack that invites fragmentation
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are underutilized or stream is late
        score += 30.0 + 40.0 * (mean_residual / bin_capacity as f64) + 25.0 * progress;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 20.0; // an open bin already fits; opening new bin is wasteful
        }
    } else {
        // Reward using existing bins when they are above-average full
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
        // Late in the stream, close out bins aggressively
        score -= 15.0 * progress * (1.0 - fill_ratio);
    }

    // Nonlinear coupling: best-fit squared interaction with residual
    score -= 0.05 * (post_residual as f64) * (post_residual as f64) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item (smooth interaction).
    let lookahead_penalty = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        gap * gap * 40.0 * (0.5 + progress)
    } else {
        0.0
    };

    // Reward using the last fitting bin (avoid opening a new bin).
    let last_chance = if fitting_bins_count == 1 { -8.0 } else { 0.0 };

    // Mild penalty for spreading across many bins early.
    let spread = (open_bins_count as f64).ln() * (1.0 - progress) * 0.5;

    // Reward tight fits: coupling of item size to residual.
    let tightness = -2.0 * (item_size as f64 / cap) * (1.0 - norm_pr);

    // New-bin candidate: prefer it only when it clearly beats poor fits late in stream.
    let new_bin_bias = if bin_residual == bin_capacity {
        6.0 + 10.0 * progress
    } else {
        0.0
    };

    let mut score = pr + 20.0 * poly + lookahead_penalty + spread + new_bin_bias + tightness + last_chance;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // class sizes (e.g. multiples of 20) are reusable; tiny odd residuals
    // are dead space. Penalize low-divisibility classes.
    let class = if post_residual == 0 {
        0.0
    } else if post_residual % 50 == 0 {
        -6.0
    } else if post_residual % 25 == 0 {
        -4.0
    } else if post_residual % 10 == 0 {
        -3.0
    } else if post_residual % 5 == 0 {
        -1.5
    } else {
        2.0
    };
    score += class;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual (or its harmonic class), reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 4.0;
            } else if gap <= 5 {
                score -= 2.0;
            } else {
                score += (gap as f64) * 0.05;
            }
        } else {
            // next item cannot use this residual anyway: slight penalty
            // scaled by wasted fraction.
            score += (next_item_size as f64) * 0.02;
        }
    } else {
        // Last item: prefer tightest packing.
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin (unless post-fit residual is tiny
    // dead space and a new bin would be cleaner).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
        if post_residual < 10 && post_residual > 0 {
            score += 3.0;
        }
    }

    // New-bin candidate: penalize opening a new bin when many bins are
    // open and mean residual is large (fragmentation risk); allow it
    // when open bins are nearly full.
    if bin_residual == bin_capacity {
        score += 10.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // If average residual across bins is small, opening a new bin is fine.
        score -= pressure * 8.0;
        if progress > 0.8 {
            score += 4.0; // late stream: consolidate, avoid new bins
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 6.0; // no open bin likely fits next item either
        }
    }

    // Mild preference for filling fuller bins first.
    score -= (bin_capacity - bin_residual) as f64 * 0.02;

    // Tie-break with mean residual: bins below mean residual are more
    // fragmented choices; prefer bins above mean.
    if (bin_residual as f64) < mean_residual {
        score += 0.5;
    } else {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post;

    // --- Strict dead-space avoidance ---
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 20.0;
    } else {
        // A leftover gap is "unusable" if it is smaller than the smallest
        // plausible future demand; penalize the closer it is to being wasted.
        let usable_threshold = if next_item_size > 0 {
            (next_item_size as f64).min(25.0)
        } else {
            10.0
        };
        if post < usable_threshold {
            score += (usable_threshold - post) * (2.0 + 2.0 * progress);
        }
        // Moderate gaps that could still serve the lookahead item get a mild bonus.
        if next_item_size > 0 && post >= next_item_size as f64 {
            score -= 3.0;
        }
    }

    // --- Open-bins pressure ---
    if is_new_bin {
        // Opening a new bin gets progressively more expensive as bins accumulate.
        score += 5.0 + open_bins_count as f64 * 2.0;
    } else {
        // Reusing existing bins is favored, more so when many bins are open.
        score -= open_bins_count as f64 * 0.5;

        // Last-chance bin: if this is the only bin that fits, use it.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Favor bins tighter than the current mean residual (consolidation).
        let tightness = mean_residual - bin_residual as f64;
        if tightness > 0.0 {
            score -= tightness * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly in post_residual,
    // strongly favor this bin (chains two items perfectly).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 800.0;
        } else if next_post <= 10 {
            score -= 250.0;
        } else {
            score -= 80.0;
        }
    }

    // Penalize residual that neither fills the bin nor can host the next item
    // (dead space relative to mean residual).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins already tighter than average
    // (pack dense bins, leave loose bins flexible).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But allow a new bin if the item is large and would leave a very tight fit.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 200.0;
        }
    }

    // Early in the stream, be slightly more open to new bins (build structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 30.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fit is extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item can fit into this bin's post-residual,
    // reward the pairing; otherwise penalize creating a bad residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 10.0;
        }
        // Perfect two-item chain: item + next exactly fill the bin.
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // New-bin candidate handling: empty bins are only attractive when
    // existing fits are poor or many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 25.0;
        // Early in the stream, prefer packing into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        // If many bins are open, spreading is less costly.
        score -= 2.0 * (open_bins_count.min(50) as f64);
        // If the item leaves a large residual in a fresh bin and the next
        // item is small, a new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Global state coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mild penalty when many bins compete for the item (favor any fit is fine,
    // but keep ordering stable via residual dominance).
    score += 0.5 * (fitting_bins_count.min(20) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer tight fits via smooth polynomial in post_residual
    let mut score = pr as f64;

    // Non-linear coupling: quadratic + cubic shaping of residual tightness
    let tight = 1.0 - fit_norm; // how "filled" the bin becomes
    score -= 30.0 * tight * tight;             // reward high fill
    score += 15.0 * fit_norm * fit_norm * fit_norm; // penalize large leftover, cubically

    // Stream-progress coupling: later in the stream, dead space matters more
    let prog_coupling = progress * progress;
    score += 40.0 * prog_coupling * fit_norm * fit_norm;

    // Interaction with mean residual: if this bin's post residual deviates from mean,
    // penalize outliers smoothly (variance-like term)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: if next item fits exactly in post residual, big reward (smooth gate)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let gate = (-gap / 20.0) * (-gap / 20.0); // smooth exp-like gate via series approx
        score -= 25.0 * (1.0 - gate.min(1.0));
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * fit_norm;

    // New-bin candidate: make it slightly unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose post-residual falls
    // into "nice" classes (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect closure
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -8.0
    } else if pr <= 10 {
        25.0 // tiny dead space, nearly unusable
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead coupling: does next_item_size harmonically divide the post-residual?
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            if pr % n == 0 {
                score -= 22.0; // perfect harmonic chain
            } else {
                let rem = pr % n;
                // reward small leftovers after next placement
                score -= 10.0 * (1.0 - rem as f64 / n as f64);
            }
        } else {
            // next item cannot fit here: penalize proportionally to wasted potential
            score += 6.0 * (n - pr) as f64 / cap;
        }
    }

    // Integer-division threshold on residual class
    let q = pr / 25; // quarter-capacity class
    score -= match q {
        0 => 12.0,  // pr < 25: small but usable for small items
        1 => 20.0,  // 25..50: sweet spot
        2 => 16.0,  // 50..75
        _ => 10.0,  // 75..100: still roomy
    };

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * (1.0 - 0.35 * congestion) + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing else fits, must open
        }
    }

    // Mild preference to spread load when many bins are open and mean residual is high
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit the minimum item are wasted.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving space usable by the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 8.0 + 5.0;
    }

    // Slight preference for bins with residual near the item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Mean residual coupling: if this bin is far below mean residual, it's a good squeeze target.
    score -= (mean_residual - bin_residual as f64).abs() * 0.05;

    // Late-stream conservatism: avoid waste near the end of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 60.0 - tightness * 0.5;
    } else if next_item_size > 0 {
        // Penalize creating dead space the next item cannot use.
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Compare post_residual against mean residual: avoid fragmenting below average.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    } else if (post_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // Last-chance bonus: only one bin can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin
    // unless current item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pair fits in fresh bin
        }
    }

    // Slight preference for tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (5.0 + 10.0 * progress);

    // Prefer bins that leave residuals in "usable" ranges (>= 10 typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that can't fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: discourage opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        // Base penalty so new bins only win when open bins are bad fits.
        score += 10.0;
        // As stream progresses, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
        // Many open bins => discourage another one.
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
        // If next item is large and current item is small, a fresh bin may be good.
        if next_item_size > item_size && post_residual < next_item_size {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (filling under-filled bins).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Slight preference for bins with larger residual when item is large (avoid fragmentation).
    if item_size > bin_capacity / 2 {
        score -= 0.03 * bin_residual as f64;
    }

    // Late-stream consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * (1.0 - progress);

    let mut score = pr + 40.0 * poly;

    // Reward tight fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 {
            score += 15.0 * (-gap / cap).powf(1.5);
        } else {
            score -= 5.0 * (gap / cap);
        }
    }

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild pressure to prefer bins over opening new ones as stream progresses
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality classes.
    // Class 0: residual is a multiple of 20 (highly reusable)
    // Class 1: multiple of 10 but not 20
    // Class 2: residual < 10 (near-dead space)
    // Class 3: odd / awkward residual
    let cls = if post_residual == 0 { 0 }
        else if post_residual % 20 == 0 { 0 }
        else if post_residual % 10 == 0 { 1 }
        else if post_residual < 10 { 2 }
        else { 3 };

    match cls {
        0 => score -= 14.0,
        1 => score -= 7.0,
        2 => score += 9.0,
        _ => score += 4.0,
    }

    // Perfect fit bonus scaled by tightness fraction of capacity.
    let frac = item_size as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 30.0 + 20.0 * frac;
    } else if post_residual <= 5 {
        score -= 12.0 * frac;
    }

    // Lookahead coupling: harmonic match between post_residual and next item.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 22.0;
        } else if diff > 0 && diff <= 10 {
            score -= 10.0;
        } else if diff > 0 && diff <= 20 {
            score -= 5.0;
        } else if diff < 0 {
            // next item can't use this bin's leftover at all
            score += 6.0;
        }
        // modulo-class resonance: residual and next item share granularity
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer filling it rather than wasting it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor = (mean_residual - item_size as f64).abs();
        score += 25.0 - 0.5 * mean_residual + poor * 0.3;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 18.0; // room to pair items in the fresh bin
        }
    }

    // Progress-aware mild tightening: early stream, be conservative about
    // fragmenting bins; late stream, exploit exact fits harder.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 3.0 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest item (1..=10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Reward near-perfect fits (small but still usable gaps).
    if post_residual <= 15 {
        score -= 8.0;
    }

    // Bonus when this placement leaves room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize if post_residual is nonzero but cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins,
    // i.e. slightly favor filling existing bins (new-bin candidate has
    // bin_residual == bin_capacity, so this term hits it).
    if bin_residual == bin_capacity {
        score += 3.0 + open_bins_count as f64 * 1.5;
    }

    // Prefer bins tighter than the mean residual (good compaction).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit_tightness = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - next_fit_tightness / bin_capacity as f64);
        } else {
            // post residual can't host next item: penalize proportionally to wasted space
            score += 30.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Compare residual relative to mean residual: prefer bins tighter than average
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize small dead space (< 10) that likely becomes unusable
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Early in stream: be more willing to open new bins (keep flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline at capacity, adjust with progress
        score = bin_capacity as f64 - 40.0 * (1.0 - progress) - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 25.0; // pairing consecutive items in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 -> use 10 as practical floor).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward;
    // if next item cannot fit anywhere after this placement, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 50.0; // perfect pairing
            } else {
                score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
            }
        } else {
            score += 15.0;
        }
    }

    // Progress-based horizon: early in the stream, prefer consolidating into open bins;
    // late in the stream, be more tolerant of opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early (keep bins consolidated), reward late.
        score += 120.0 * (1.0 - progress);
        score -= 30.0 * progress;
    } else {
        score -= 20.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    let density = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += density.min(40.0);

    // Prefer bins whose residual is close to the item (relative fit).
    let rel_fit = (bin_residual as f64 - item_size as f64) / (bin_capacity as f64);
    score += 30.0 * rel_fit * rel_fit;

    // Mild penalty for very empty open bins when many bins are already open.
    if bin_residual > (bin_capacity * 3) / 4 && bin_residual < bin_capacity {
        score += 10.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize leftover space, with a smooth quartic dead-space profile
    let mut score = x.powf(2.0) * (2.0 + 3.0 * progress) - x * (1.0 + 0.5 * progress);

    // Smooth coupling: exact fit reward amplified by progress
    score -= (1.0 - x).powf(2.0) * (1.0 + 2.0 * progress);

    // Lookahead: reward if next item fits in post residual (smooth ramp)
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_frac = next_item_size as f64 / cap;
        score -= 0.8 * (1.0 - fit_frac) * (1.0 - fit_frac) * (1.0 - 0.5 * progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 + progress);
    }

    // Mildly prefer bins below mean residual (tighter bins) via smooth interaction
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 1.5 - 0.8 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual bucketed by capacity/8
    let class = post_residual / (bin_capacity / 8);
    let class_penalty: f64 = match class {
        0 => -30.0,                      // near-perfect fit
        1 => -12.0,                      // small leftover, likely reusable by small items
        2 => 8.0,                        // awkward ~25% gap
        3 => 2.0,
        4 => -6.0,                       // half-full bin: very reusable
        5 => 0.0,
        6 => -3.0,
        _ => -10.0,                      // still mostly empty
    };
    score += class_penalty;

    // Modulo-10 harmonic: leftover divisible by 10 pairs well with grid-like item sizes
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead coupling: does the leftover exactly or partially fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;               // perfect chain
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to lookahead: penalize proportionally
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are congested or fit is terrible
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        score = 55.0
            + 20.0 * (step_index as f64 / total_items.max(1) as f64)
            - if fitting_bins_count <= 1 { 40.0 } else { 0.0 }
            - (mean_residual / bin_capacity as f64).min(1.0) * 15.0
            + congestion * 0.5;
    }

    // Tight-fit bonus: reward minimizing wasted fraction
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 8 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Reward near-perfect fits (small but usable post_residual).
    if post_residual > 0 && post_residual <= 10 {
        score -= 20.0;
    }
    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 12 {
        score -= 15.0; // next item leaves near-perfect state
    }
    // Penalize if post_residual can't host the lookahead item but is close in size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size - 3 {
        score += 12.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading; make new bins less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // New-bin candidate handling: empty bin should only win when the fit into
    // existing bins would be poor. Penalize the fresh bin mildly, more when
    // open-bin count is low and mean residual is large.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.4 + open_bins_count as f64 * 2.0;
        // Late in the stream, keep fewer bins: new bins cost more.
        score += progress * 20.0;
    } else {
        // Favor bins with residual close to what is needed (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.05;
        // Reward bins below mean residual (already partially filled well).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: baseline score = capacity, adjusted by phase.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer opening a new bin late in the stream or when many bins fit
        // (i.e., current bins are fragmented); otherwise make it costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64
            - 30.0 * progress
            - 8.0 * (fitting_bins_count as f64).ln().max(0.0)
            + 15.0 * (1.0 - (open_bins_count as f64 / 20.0).min(1.0));
        return score;
    }

    // Perfect fit: extremely favorable.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead-space penalty: small residuals (< 10, the min item size) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 12.0 * (overshoot / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are good targets.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: only this bin fits the item -> avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Mild preference for tighter bins overall.
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.35 * next_item_size as f64;
        }
        // Penalize creating residual just below the next item size (dead space trap).
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Last chance: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // (high mean residual) or late in the stream with many open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Opening a new bin costs ~capacity of wasted potential; penalize by default.
        score += 45.0;
        // But if open bins are highly fragmented, a fresh bin is more attractive.
        score -= fragmentation * 55.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= (1.0 - progress) * 20.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for filling bins with less residual overall (keep big holes free).
    if !is_new_bin {
        score += (bin_residual as f64) * 0.08;
    }

    // Penalize bins whose leftover would be tiny-but-nonzero (unusable sliver).
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = (item_size as f64) / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let base = pr.powf(1.6) / cap;

    // Smooth progress coupling: early on, waste slightly less penalized;
    // later, tight fits matter more (amplify residual cost over time)
    let progress_coupling = base * (0.5 + 1.5 * progress * progress);

    // Dead-space penalty: post-residual too small for typical future items
    let dead = if pr < 10.0 { 0.0 } else {
        let d = pr / cap;
        d * d * (1.0 - d)
    } * 8.0;

    // Lookahead: reward if next item fits into post_residual (smooth kernel)
    let lookahead = if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        -6.0 * (-gap / 20.0).exp()
    } else { 0.0 };

    // Last-chance bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -15.0 } else { 0.0 };

    // Crowding penalty: many open bins with high mean residual -> discourage
    // adding to already-loose bins; encourage consolidation
    let crowd = (mean_residual - pr) / cap * (open_bins_count as f64).sqrt() * 2.0;

    // Slight preference for filling larger fraction of the bin
    let fill_bonus = -fit_norm * fit_norm * 10.0 * (1.0 - progress);

    // New-bin candidate: make empty bins mildly unattractive unless residuals
    // elsewhere are terrible (smooth via base term)
    let new_bin_penalty = if bin_residual == bin_capacity {
        6.0 + 10.0 * progress
    } else { 0.0 };

    base + progress_coupling + dead + crowd + new_bin_penalty + lookahead + last_chance + fill_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover decomposes into
    // "usable" size classes (small items 1..=10, medium 11..=30, large 31..=60).
    let small = (post_residual / 10) as f64;          // number of 10-slots
    let medium = (post_residual % 30) as f64;          // harmonic remainder mod 30
    let large = (post_residual % 50) as f64;           // harmonic remainder mod 50

    // Perfect fits are ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead space penalty grows super-linearly for tiny unusable remainders,
    // but a remainder that exactly admits the next item is golden.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Fraction of next item that fits into the leftover.
            let fit_frac = next_item_size as f64 / post_residual as f64;
            score -= 120.0 * fit_frac;
        } else {
            // Leftover too small for next item: penalize by how "wasted" it is.
            let waste = post_residual as f64 / next_item_size as f64;
            score += 60.0 * (1.0 - waste).max(0.0);
        }
    }

    // Modulo-class bonus: leftover divisible by common item sizes is reusable.
    if post_residual % 10 == 0 { score -= 25.0 * small; }
    if post_residual % 20 == 0 { score -= 15.0; }
    if post_residual % 25 == 0 { score -= 20.0; }
    if post_residual % 30 == 0 { score -= 30.0; }
    if post_residual % 50 == 0 { score -= 35.0; }

    // Penalize awkward remainders in (0,10): nearly dead space.
    if post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Medium harmonic band penalty: leftover in 11..=29 fits only small items.
    if post_residual >= 11 && post_residual <= 29 {
        score += 0.8 * medium;
    }
    // Band 31..=49: fits medium items but not half-bin pairs.
    if post_residual >= 31 && post_residual <= 49 {
        score += 0.3 * large;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        if post_residual >= 50 {
            score -= 30.0; // fresh bin with half capacity is fine early
        }
        // Prefer reusing open bins when mean residual is ample.
        score += 0.5 * mean_residual;
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * progress;
        // If many bins can fit, prefer one of them over a new bin.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit bias).
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    // Small tie-breaker toward bins whose residual is close to item size.
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Medium dead space (10..20) mildly penalized since few items fit.
    if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate handling: neutral-ish baseline, but attractive when
    // the item fits poorly everywhere (large dead space elsewhere) or when
    // the next item would pair well with a fresh bin.
    if bin_residual == bin_capacity {
        let fresh_bonus = 30.0
            + (next_item_size as f64 / 100.0) * 20.0
            - (post_residual as f64) * 0.1;
        // If an open bin gives a perfect fit, never open a new bin.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 100.0;
        }
        // When many bins are open, discourage proliferation.
        score += open_bins_count as f64 * 1.5;
        score -= fresh_bonus.min(45.0);
    } else {
        // Favor bins whose residual is close to the item (tight fit).
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= tightness * 10.0;
        // Prefer bins below mean residual (smaller residuals = tighter bins).
        score += ((bin_residual as f64) - mean_residual) * 0.15;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    }
    // If next item fits in post residual, mildly reward.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 3.0;
    }

    // Early in the stream, be slightly more willing to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Strong reward when the leftover space exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 60.0;
        } else if post_residual as u32 >= next_item_size {
            // Next item still fits here: mild reward proportional to how well it matches.
            let slack = post_residual as f64 - next;
            score -= 20.0 / (1.0 + slack / 10.0);
        } else {
            // Next item won't fit: penalize dead space, especially tiny unusable gaps.
            if post_residual > 0 && post_residual < 10 {
                score += 25.0;
            }
            score += 5.0;
        }
    }

    // Reward/penalize relative to mean residual across open bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral baseline, slight penalty so tight fits in open bins win,
        // but bonus when many bins are open and mean residual is small (fragmented state).
        score = bin_capacity as f64 * 0.6;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Penalize leaving residuals that no plausible item (>=1) can ever use well:
    // residuals smaller than the minimum item size are dead weight.
    if post_residual > 0 && post_residual < 1 {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // Good chain potential; scale by how snugly the next item also fits.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 8.0 * (1.0 - chain_slack / cap);
        } else {
            // Next item cannot follow here: mild penalty proportional to leftover waste.
            score += 5.0 * (post_residual as f64) / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into
    // already-tight bins rather than spreading residual space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * (open_bins_count as f64) * (mean_residual / cap) * (0.5 + progress);

    // Dead-space penalty: residuals that are too small for typical future items
    // (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate: bin_residual == bin_capacity. Its naturally large
    // post_residual already disfavors it; add an extra adaptive penalty that
    // shrinks when the item is large relative to capacity (big items deserve
    // fresh bins) or late in the stream.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 18.0 * (1.0 - item_frac) * (1.2 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let base = post
        + 40.0 * post_norm * post_norm
        + 25.0 * post_norm * post_norm * post_norm;

    // Smooth stream-progress coupling: later in stream, penalize large residuals more
    let progress_coupling = (1.0 + 3.0 * progress) * post_norm * (1.0 - post_norm) * 30.0;

    // Dead-space penalty: post_residual too small to ever fit a future item (items >= 1)
    let dead_penalty = if post == 0.0 { -20.0 } else { 0.0 };

    // Last-chance bonus: strongly favor the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -15.0 } else { 0.0 };

    // Lookahead: reward if next item fits exactly into post_residual
    let lookahead = if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        -12.0 / (1.0 + diff)
    } else {
        0.0
    };

    // Mild preference for filling bins with low mean residual (balance)
    let balance = 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference for existing bins over opening new ones
    let new_bin_penalty = if bin_residual == bin_capacity { 8.0 + 10.0 * progress } else { 0.0 };

    base + progress_coupling + dead_penalty + last_chance + lookahead + balance + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and near-perfect fits are gold.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else {
        // Integer-division thresholds: dead space classes.
        let dead = post_residual;
        if dead <= 10 {
            score -= 50.0; // tiny dead space, essentially full
        } else if dead <= 20 {
            score -= 20.0;
        } else if dead <= 30 {
            score -= 5.0;
        } else if dead <= 50 {
            score += 15.0; // half-empty bin is wasteful
        } else {
            score += 40.0; // mostly-empty bin: poor placement
        }

        // Modulo arithmetic on residual: residuals divisible by 10 are
        // "harmonic" with typical item sizes and reusable.
        if dead % 10 == 0 {
            score -= 8.0;
        }
        // Residuals that are awkward primes-ish (odd, not multiple of 5) are harder to fill.
        if dead % 2 == 1 && dead % 5 != 0 {
            score += 4.0;
        }
    }

    // Lookahead: can next item also fit in the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0; // chain-friendly
            // Harmonic bonus: next item exactly fills the leftover.
            if next_item_size == post_residual {
                score -= 60.0;
            }
            // next item leaves a small residue again -> great packing
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 {
                score -= 15.0;
            }
        } else {
            score += 10.0; // next item won't fit here; bin will die
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize so it's only chosen when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Late in the stream, opening a fresh bin is less harmful (future items exist).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * progress;
    }

    // Spread-awareness: prefer bins below mean residual (tighter bins) to keep
    // large residuals available for large future items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else if (bin_residual as f64) > mean_residual * 1.5 {
        score += 5.0;
    }

    // Early stream: keep bins flexible; late stream: squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // future item (min size 1, but practically tiny gaps) are pure waste.
    // Penalize hard when post_residual falls into the "unusable" zone.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity (low relative waste).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_ratio * waste_ratio;

    // Open-bin pressure: discourage scattering across many bins unless the
    // fit is excellent. Mild penalty proportional to open_bins_count.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a
    // new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && post_residual as f64 <= bin_capacity as f64 * 0.5 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current fit is poor or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // If mean residual across open bins is large, opening a new bin is
        // wasteful; penalize more.
        score += 0.4 * mean_residual;
        // But if the item is large and wouldn't fit well anywhere, allow it.
        if item_size >= 60 {
            score -= 18.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly reward this placement (chains items nicely).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits here: mildly reward leaving useful space.
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for the next item: penalize dead space.
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // anticipates the next item size (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match bonus: post_residual == next_item_size
        if diff < 1.0 {
            score -= 30.0;
        } else if post_residual as f64 >= nxt {
            // Next item still fits after this placement: mild reward scaled by closeness
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally
            score += 6.0 * (diff / bin_capacity as f64);
        }
    }

    // Penalize small unusable gaps (fragmentation) more sharply.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Prefer already-opened bins over opening new ones as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream matures, less if the stream is early.
        score += 8.0 + 20.0 * progress;
    } else {
        score -= 3.0;
    }

    // Slight preference to spread load when many bins are open and mean residual is high.
    if open_bins_count > 3 && mean_residual > 40.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: penalize large post_residual nonlinearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the item fits badly
    // everywhere else or open bins are very full on average.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins are usually preferred.
        score += 60.0;
        // If this item leaves a large hole in any open bin anyway, new bin
        // becomes competitive: reduce penalty by wasted-space ratio.
        let waste = post_residual as f64;
        score -= 0.4 * waste;
        // Early in stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // Many open bins with high mean residual -> prefer consolidating.
        score += 0.5 * (open_bins_count as f64);
        score -= 0.2 * mean_residual;
    }

    // Lookahead: if next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot fit here; mild penalty for leaving big gaps anyway.
            score += 0.1 * (post_residual as f64);
        }
    }

    // Prefer filling bins with low residual relative to mean (consolidate waste).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference for bins that are already fairly full.
    let fill = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
    score -= 10.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping.
    let base = pr + 30.0 * norm_pr * norm_pr;

    // Stream progress coupling: penalize waste more as stream advances (quadratic in progress).
    let progress_penalty = 25.0 * norm_pr * (progress * progress);

    // Reward tight fits when this is the last fitting bin (avoid opening new bin).
    let last_chance = if fitting_bins_count == 1 { -12.0 } else { 0.0 };

    // Scarcity coupling: fewer fitting bins -> stronger preference for this bin.
    let scarcity = if fitting_bins_count > 0 { -4.0 / fitting_bins_count as f64 } else { 0.0 };

    // Dead-space penalty: post-residual that can't fit the next item is wasted.
    let dead = if next_item_size > 0 && (post_residual as u32) < next_item_size {
        15.0 * (1.0 - norm_pr)
    } else {
        0.0
    };

    // Smooth lookahead reward: if next item exactly fits remaining space, strong bonus.
    let exact_next = if next_item_size > 0 && (post_residual as u32) == next_item_size {
        -20.0
    } else {
        0.0
    };

    // Deviation from mean residual: prefer bins below mean residual (more filled).
    let mean_dev = 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: mildly penalize opening a bin unless residual is large.
    let new_bin = if bin_residual == bin_capacity {
        10.0 + 20.0 * progress * progress
    } else {
        0.0
    };

    base + progress_penalty + last_chance + scarcity + dead + exact_next + mean_dev + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on coarse
    // residue classes are more reusable. Reward leftovers in "friendly"
    // classes (multiples of 10, and mid-range values 20..50), penalize
    // tiny dead space (1..9) and near-full waste.
    let pr = post_residual;
    let class = pr / 10; // integer division harmonic class 0..=10
    match class {
        0 => {
            // post_residual in 0..9: near-perfect fit or tiny dead space.
            if pr == 0 {
                score -= 40.0; // perfect closure is ideal
            } else {
                score += 25.0 + (10 - pr) as f64 * 3.0; // tiny unusable slivers
            }
        }
        1 => score += 6.0,          // 10..19: small but usable
        2 | 3 => score -= 8.0,      // 20..39: sweet spot for medium items
        4 | 5 => score -= 12.0,     // 40..59: prime reusable zone
        6 => score -= 4.0,          // 60..69
        _ => {}                     // 70+: mostly empty bin, neutral
    }

    // Modulo-10 alignment bonus: leftover that is a multiple of 10 pairs
    // well with typical item sizes drawn from decile classes.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chained harmonic match).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // reward proportional to how tightly next item nests
            let nest = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - nest / 50.0).max(0.0);
        } else {
            // next item cannot fit here: slight penalty scaled by overshoot class
            let over = next_item_size - pr;
            score += ((over / 10) as f64) * 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless post_residual would be a tiny sliver.
    if fitting_bins_count == 1 {
        score -= 10.0;
        if pr > 0 && pr < 10 {
            score += 15.0; // don't burn last-fitting bin for a sliver
        }
    }

    // New-bin candidate handling: an empty bin (residual == capacity) should
    // only win when no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 18.0;
        // cheaper to open a new bin early in the stream (plenty of future items
        // will amortize it) and when open bins are already crowded with small residuals
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 14.0 * (1.0 - progress);
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 8.0; // all open bins are near-full; fresh capacity is valuable
        }
        // large items prefer a fresh bin to avoid fragmenting partial bins
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        // placing into an existing bin: reward tightness relative to capacity
        let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
        score -= 10.0 * tightness;
        // penalize opening many bins when a mild fit exists
        score += (open_bins_count as f64) * 0.05;
    }

    // Global mean-residual steering: keep population of residuals balanced;
    // bins far below mean residual are "richer" targets.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the minimum plausible item size,
    // and worse if it is small-but-not-zero (wasted space that nothing fits).
    if post_residual > 0 {
        if post_residual < 10 {
            // tiny sliver: nearly dead, but at least it's tiny -> moderate penalty
            score += 12.0;
        } else if post_residual < 20 {
            // dead zone: too small for most items (items 10..80), pure waste
            score += 45.0;
        } else if post_residual < 30 {
            // risky zone: only very small items could use it
            score += 15.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size) more strongly
    // than the raw linear term does: a perfect fit should be strongly preferred.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual < 20 {
            score -= 15.0; // tight fit in last chance bin is ideal
        }
    }

    // Open-bin pressure: penalize spreading across many open bins slightly,
    // encouraging consolidation when many bins are already open.
    score += 0.35 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement is excellent; reward it. If next item almost fits but not
    // quite, mildly penalize creating a tempting-but-insufficient gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 0.2 * next_item_size as f64;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 8.0; // gap will be dead for the next item
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual, which
    // naturally scores high (bad). Only open a new bin when all existing fits
    // would create significant dead space or no bin fits at all.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 55.0 + 1.5 * open_bins_count as f64;
        // but if the item is large, a fresh bin is often the right call
        // (large items fragment bins badly); reduce the penalty.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Slight phase pressure: early in the stream, be a bit more willing to
    // consolidate; late in the stream, keep as-is.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    // Mean residual coupling: if this bin's residual is far below the mean
    // (it's the fullest bin), prefer filling it (best-fit style).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.25 * (mean_residual - residual_f);
    } else {
        score += 0.15 * (residual_f - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: extremely desirable
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits, penalize proportional leftover slack after both placements
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.15 * slack_after_next;
        } else {
            // Next item does NOT fit in this bin after placement: penalize
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(60.0);
        }
    } else {
        // Last item: just minimize post_residual waste
        score += 0.1 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (hard to fill later)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 45.0;
        // More attractive late in stream or when many bins are open and fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin can host both current and next item comfortably
            score -= 20.0;
        }
    }

    // Mild penalty for waste proportional to item size (fragmentation avoidance)
    score += 0.05 * (post_residual as f64 / item_size.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that no future item (sizes 1..100) can use well:
    // residuals below 10 are nearly unusable.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't follow into this bin; mild penalty scaled by how close it was.
        score += 3.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidation (tight fits already favored);
    // when few bins open, slightly favor spreading into emptier bins.
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    } else {
        score -= 0.5 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: early in stream, be pickier about wasting space (long future);
    // late in stream, just fill anything reasonable.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 0.08 * post_residual as f64;

    // Prefer bins whose residual is above the mean (keep low-residual bins for small items).
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // fits well. Make the empty-bin call moderately expensive but not prohibitive.
    if bin_residual == bin_capacity {
        score += 18.0 + 6.0 * t;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && item_size <= 50 {
            // roomy new bin can host the next item too
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), with a mild concavity
    // that increasingly punishes large leftover space as the stream progresses.
    let mut score = pr * (1.0 + 0.6 * progress * (pr / cap));

    // Non-linear coupling: penalize post_residual relative to mean residual
    // state; bins far from the mean get a smooth quadratic nudge.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.5 + progress);

    // Reward filling a bin nearly exactly (post_residual near zero),
    // smoothly scaled by item fraction.
    score -= 12.0 * (-pr / (5.0 + fit * cap)).exp() * (1.0 - progress * 0.5);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate handling: make an empty bin moderately attractive
    // only when it enables a good pairing with the lookahead item.
    if bin_residual == bin_capacity {
        let pair_waste = if next_item_size > 0 {
            let r = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            r / cap
        } else {
            0.5
        };
        score = 18.0 + 40.0 * pair_waste * pair_waste - 8.0 * progress;
    }

    // Lookahead synergy: if the next item fits exactly into the post_residual,
    // reward this placement smoothly.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size as f64 <= pr {
        score -= 4.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for spreading across too many open bins late in stream.
    score += (open_bins_count as f64).ln().max(0.0) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Residuals that are "harmonic" (multiples of common small sizes) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward residuals divisible by small harmonic steps (5, 10, 20, 25, 50)
    if post_residual % 50 == 0 { score -= 18.0; }
    else if post_residual % 25 == 0 { score -= 12.0; }
    else if post_residual % 20 == 0 { score -= 9.0; }
    else if post_residual % 10 == 0 { score -= 6.0; }
    else if post_residual % 5 == 0 { score -= 3.0; }
    else { score += 4.0; } // non-harmonic dead space penalty

    // Integer-division threshold: residual in the "danger zone" (1..10) is nearly dead.
    let dead_zone = post_residual / 10; // 0 => residual < 10 (unusable for min item 1? still tiny)
    if dead_zone == 0 && post_residual > 0 { score += 25.0; }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 { score -= 40.0; }

    // Coupling with next item: if next item fits exactly in post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 30.0; }
        else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // harmonic check on the gap after hypothetical next placement
            if gap % 10 == 0 { score -= 8.0; } else { score += gap as f64 * 0.3; }
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 15.0; }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when existing residuals are large but poorly harmonic,
        // or late in the stream with many open bins.
        let penalty = 12.0 + pressure * 10.0 + progress * 8.0 + open_bins_count as f64 * 0.5;
        score += penalty;
        // But if item is large and current open bins can't offer harmonic post-residual,
        // new bin becomes relatively better (score already high for bad fits).
    }

    // Slight preference for filling fuller bins overall (tight packing).
    score -= (1.0 - post / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    // A residual gap is "dead" if it is smaller than the smallest possible item (1),
    // but practically gaps below a threshold cannot absorb future items well.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        // Quadratic penalty for near-dead space
        score += (dead_threshold - post_residual as f64).powi(2) * 0.8;
    }

    // Reward tight fits: if post_residual is very small, strongly subtract.
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Open bins pressure: penalize using bins when many are open, to encourage
    // filling existing bins rather than spreading; but encourage closing bins out.
    let open_pressure = open_bins_count as f64;
    // Slight penalty proportional to open bins to prefer consolidating items
    score += open_pressure * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty-bin score moderately high so it is
    // only chosen when fits into open bins are poor (large post_residual).
    if bin_residual == bin_capacity {
        // New bin baseline: its post_residual equals capacity - item_size.
        // Add a fixed opening cost plus mild penalty scaled by open bins already.
        score += 18.0 + open_pressure * 0.5;
        // But if no open bin fits well (this is checked implicitly by score comparison),
        // lookahead: if next item is large, opening fresh bin may be better.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 6.0;
        }
    }

    // Lookahead synergy: reward bins whose post_residual can fit the next item.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post_residual too small for next item: penalize proportional to wasted gap
        score += (post_residual as f64) * 0.15;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.2;
    } else {
        score += (bin_res_f - mean_residual) * 0.1;
    }

    // Stream progression: early on, be slightly more willing to open bins (explore);
    // later, be conservative and squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 10.0; // opening new bins gets costlier later
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Perfect fit for next item is highly desirable.
        score -= 30.0 * (1.0 - diff / bin_capacity as f64);
    }

    // Penalize post_residual that is small but nonzero (dead space) relative to next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Dead space: unusable for the next item.
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Perfect closure of the bin is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Compare against mean residual: bins tighter than mean are better choices.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early in the stream, be more willing to spread items across bins (open new ones);
    // later, consolidate to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses unless item is large.
        score += 10.0 + 20.0 * progress - 0.1 * item_size as f64;
        // But if no open bin fits well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Slight preference for placing large items in fuller bins.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 24.0 * fit_ratio * fit_ratio;

    // Penalize using a large-residual bin for a small item (dead-space waste).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.12 * waste;

    // Lookahead: if the next item can still fit in the post-residual, reward this bin;
    // if the next item would no longer fit, penalize slightly (chain-breaking).
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit, i.e. when the best available residual is much larger than
    // the item or when few bins are open. Penalize the empty-bin candidate otherwise.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        // High mean residual across open bins => poor fits exist => new bin less costly.
        score += 20.0 * (1.0 - open_pressure);
        // Early in the stream, opening bins is cheap; later, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If item is large relative to typical residual, a fresh bin is fine.
        score -= 8.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild consolidation pressure: more open bins => prefer reusing existing bins.
    score += 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Prefer bins whose residual is close to the mean residual (balanced usage),
    // discouraging extreme outliers early.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap; // 0..1 normalized post residual
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: quadratic polynomial in normalized post-residual
    let mut score = 1.0 + 4.0 * fit_norm - 3.0 * fit_norm * fit_norm;

    // Non-linear coupling with stream progress: later in stream, prefer tighter fits
    score += (1.0 - progress) * 0.5 * (fit_norm * fit_norm).sin();

    // Penalize dead space relative to mean residual across open bins (smooth coupling)
    score += 0.3 * (pr - mean_residual) / cap;

    // Lookahead: reward leaving space usable by the next item (smooth ramp)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr - nx).max(0.0);
        score -= 0.6 * (usable / cap);
        // next item exactly fits: strong reward
        if (pr - nx).abs() < 0.5 {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly reward using it before opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 1.5;
    } else if fitting_bins_count > 1 {
        // many options: mild penalty to prefer best fit via post residual
        score += 0.05 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: default penalty so it's chosen only when fits are poor;
    // penalty decays with stream progress and shrinks when item is large.
    if is_new_bin {
        let size_frac = item_size as f64 / cap;
        score += 3.0 - 1.5 * progress - 2.0 * size_frac * size_frac;
        if next_item_size > 0 && pr < next_item_size as f64 {
            score += 0.5; // new bin wastes space for lookahead
        }
    }

    // Small smooth jitter-free regularization tied to open bins count
    score += 0.01 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Bins whose post_residual falls into "usable" classes (multiples of small
    // denominators of 100: 1,2,4,5,10,20,25,50) leave re-combinable space.
    let mut h = 0u32;
    for &d in &[1u32, 2, 4, 5, 10, 20, 25, 50] {
        if post_residual % d == 0 {
            h += 1;
        }
    }
    // Reward harmonic alignment: subtract for each divisor matched.
    score -= 6.0 * h as f64;

    // Integer-division thresholds: small dead space is bad unless harmonic.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0; // tiny unusable sliver
        // but if it is a harmonic class value (1,2,4,5,8), soften
        if h >= 3 { score -= 10.0; }
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual accommodate next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 + 0.15 * slack as f64;
            if post_residual == next_item_size {
                score -= 20.0; // chain of exact fits
            }
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should win only when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, modulated by stream progress and crowding
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 + 30.0 - 20.0 * progress + 2.0 * open_bins_count as f64;
        // opening a bin is more attractive if it will be harmonic-friendly later
        // (item_size itself in harmonic class of capacity)
        let mut hi = 0u32;
        for &d in &[1u32, 2, 4, 5, 10, 20, 25, 50] {
            if item_size % d == 0 { hi += 1; }
        }
        score -= 3.0 * hi as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter fill).
    score += 0.3 * ((bin_residual as f64 - mean_residual).max(-50.0)).min(50.0);

    // Late-stream conservatism: squeeze existing bins harder near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (item dominates residual).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap slightly larger than the next item (waste).
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 5 {
        score += 10.0;
    }

    // Mild progress coupling: later in stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 - mean_residual) * (0.3 + 0.4 * progress);

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: dead space zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item exactly fills the post-residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how tightly it fills the remainder.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * tightness;
        } else {
            // Next item does NOT fit in the residual: penalize leaving this much slack.
            let waste = post_residual as f64 - next_item_size as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize small unusable residuals (dead space below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Tight fit relative to current bin residual (prefer bins where the item
    // consumes a large fraction of the remaining space).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 100.0 * fill_ratio;

    // Compare against mean residual: prefer bins tighter than average.
    if (mean_residual - post_residual as f64).abs() < 1e-9 {
        score += 10.0;
    }
    if (post_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 30.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive late in the stream or when item is huge
    // relative to open residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let avg_open_residual = if open_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        let fit_quality = item_size as f64 / avg_open_residual.max(1.0);
        score = 200.0 + 100.0 * progress - 150.0 * item_frac - 50.0 * fit_quality;
        if post_residual == 0 { score -= 1000.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: quadratic decay of residual waste.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Lookahead: penalize residuals that can't host the next item (dead space),
    // reward residuals that can exactly or nearly host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64); // next item fits well here
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (gap / bin_capacity as f64).sqrt(); // stranded space
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.05 * (item_size as f64);
    }

    // New-bin candidate handling: opening a new bin should only win when current
    // bins fit poorly. Penalize new bins mildly, more so late in the stream or
    // when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 6.0 * progress + 0.3 * open_bins_count as f64;
        // But if next item is huge and no open bin will hold both, new bin is fine.
        if next_item_size > bin_capacity - item_size {
            score -= 12.0;
        }
    }

    // Global state coupling: if mean residual is high, prefer consuming the
    // emptiest-feeling bins (large residual) to consolidate space.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Perfect fit celebration.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 5.0; // near-perfect fill, tiny dead space
    }

    // Time horizon: early in stream, be conservative about fragmenting bins;
    // late in stream, squeeze everything in.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer minimal post_residual, scaled non-linearly
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth polynomial coupling: dead space hurts more as stream progresses
    let norm_pr = pr / cap;
    score += cap * (norm_pr * norm_pr) * (0.3 + 1.2 * progress);

    // Reward filling bins deeply (large item fraction) with smooth term
    score -= 3.0 * (it / cap) * (it / cap) * cap * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Penalize spreading across many open bins mildly
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let tight = 1.0 - (pr - nxt) / cap;
            score -= 10.0 * tight * tight;
        } else {
            // post_residual too small for next item: penalize proportionally to waste
            score += 6.0 * (pr / cap) * (1.0 - nxt / cap);
        }
    }

    // New-bin candidate: neutral-ish baseline, slightly worse than a decent fit
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.4 * progress) - 0.5 * mean_residual;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items sizes 1..100, capacity 100.
    // Class 0 (perfect fit) strongly rewarded; large dead space penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Dead-space class via integer division: leftover <= 10 is highly reusable.
        let cls = pr / 10; // 0..=10 harmonic band
        score -= match cls {
            0 => 25.0,
            1 => 15.0,
            2 => 8.0,
            3 => 3.0,
            _ => 0.0,
        };
        // Modulo coupling: leftover divisible by common item granularities (5,10)
        // tends to be reusable; penalize awkward leftovers.
        if pr % 5 == 0 { score -= 4.0; }
        if pr % 10 == 0 { score -= 3.0; }
        if pr > 50 { score += 6.0; } // wasteful half-empty placement
    }

    // Lookahead harmony: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0; // chain placement possible
            // Harmonic class match: next item leaves another small residue
            if (pr - next_item_size) <= 10 { score -= 6.0; }
        } else {
            score += 5.0; // next item won't chain here
        }
    } else {
        score -= 5.0; // last item: just pack tightly
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is
    // chosen only when open bins offer poor fits.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.05 * (open_bins_count as f64);
        // But if the item is large relative to capacity, new bin is natural.
        if item_size * 2 >= bin_capacity { score -= 10.0; }
    }

    // Late-stream tightening: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress;
    score += 0.03 * (mean_residual - pr as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A post_residual below the minimum item size (1) is impossible here, but tiny
    // residuals (1..=10) are nearly unusable dead space — apply a superlinear penalty.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - pr) * (11.0 - pr) * 2.0;
    }
    // Residuals that cannot fit the lookahead item are less flexible.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can still absorb the next item after this placement.
        score -= 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins and
    // encourage filling existing ones (especially tight fits).
    let open_pressure = open_bins_count as f64;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64) * 3.0;

    // Slight global preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Penalize bins whose residual deviates far above the mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive when no open bin fits well or open count is low.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 20.0 * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        score += 10.0 - new_bin_bonus;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        score -= progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect or near-perfect 2-step lookahead matches.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // exact chain: item + next item fill the bin
        } else if post_residual >= next_item_size {
            // next item still fits; reward tighter leftover after the chain
            score -= 25.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize small dead space that
            // neither fits the next item nor is likely usable later
            score += 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: avoid wasting it unless the fit is very tight.
    if fitting_bins_count == 1 {
        score -= 8.0 * (item_size as f64 / bin_residual as f64);
    } else if fitting_bins_count > 1 {
        // spread items across bins to keep flexibility
        score += 3.0;
    }

    // Prefer bins with residuals below the mean (pack tight bins first),
    // keeping loose bins available for larger future items.
    score += 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Penalize leaving awkward small residuals (dead space < typical item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for opening a new bin early in the stream when
    // existing bins would be filled to an awkward level.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, especially very tight ones.
    let tight_fit = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight_fit * tight_fit;

    // Penalize dead space: residual that cannot fit a typical item (below 10 or
    // awkwardly small slivers) is wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= (1.0 - slack as f64 / bin_capacity as f64) * 20.0;
        } else {
            // Next item won't fit here; mild penalty proportional to overflow gap.
            score += 5.0 + 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    } else {
        // Last item: prefer minimal final residual.
        score -= 10.0 * tight_fit;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (bin_residual as f64);
    }

    // New-bin candidate handling: empty bin baseline. Opening new bins is costly
    // when many bins are already open and mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64
            - 20.0 * (1.0 - progress)          // early stream: fresh bins are fine
            + 2.0 * open_bins_count as f64     // many open bins: discourage new ones
            + 0.5 * mean_residual;             // high average slack: reuse bins instead
    }

    // Slight preference for bins whose residual is close to the fleet mean
    // (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize wasted post residual, non-linearly (dead space grows quadratically).
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: late in the stream, prefer tight fits more aggressively.
    let late = progress * progress;
    score += late * pr * (1.0 - norm_item);

    // Reward placements that leave room for the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let fits_next = (norm_next - norm_pr).max(0.0);
        score -= 8.0 * (1.0 - fits_next) * norm_item * (1.0 - late);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - late);
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * norm_item;
        if fitting_bins_count > 0 {
            score += 30.0 * (1.0 - norm_item);
        }
    }

    // Mild penalty for scattering across many open bins when mean residual is high.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap - norm_pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but discount post_residual by its "waste class".
    // Harmonic classes: residuals divisible by common item sizes are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // residual that is a multiple of 10 is a "good class" (common item quantum)
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        }
        // very small dead space (< 10) is nearly useless: penalize hard
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }
    } else {
        // perfect fill is ideal
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item chains nicely into this bin -> reward
            score -= (next_item_size as f64) * 0.5;
            // extra reward if chained residual stays in a good class
            if (pr - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: this bin becomes dead space for the lookahead
            let overflow = (next_item_size - pr) as f64;
            score += overflow * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing bins would leave bad classes.
    if bin_residual == bin_capacity {
        // baseline competitiveness: empty bin wastes (capacity - item_size)
        score = (bin_capacity - item_size) as f64;
        // opening a new bin is fine early in the stream or when few bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        score -= (open_bins_count as f64).sqrt() * 2.0;
        // if the item is large, a fresh bin is safer
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        // if next item is large too, fresh bin preserves flexibility
        if next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Slight preference for bins below the mean residual (keeps spread balanced)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    let mut score = post_residual as f64;

    // Tight fit reward: the closer post_residual is to 0, the better.
    score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(4);

    // Penalize "unusable" gaps: post_residual too small for typical future items
    // (items >= 1, but small gaps like 1..=10 are almost certainly dead space).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 10.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward residual that can still host the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0; // gap cannot host next item -> potential dead space
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes all open residual capacity.
    if bin_residual == bin_capacity {
        // Only attractive if open bins are very full (little usable space left)
        // or many bins fit (no scarcity pressure).
        score = bin_capacity as f64 * 0.6
            + open_bins_count as f64 * 2.0
            - mean_residual * 0.5;
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when a last-chance fit exists
        }
    }

    // Open-bin pressure: mild penalty per open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual can still fit the next item: mildly good
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Post residual too small for next item but nonzero: dead space penalty
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 18.0;
        // Extra penalty if the dead space is tiny (unusable)
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Compare post_residual against mean residual: leaving less than average
    // concentrates packing (good), leaving more than average is wasteful
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: encourage closing bins out (prefer tighter fits)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // New-bin candidate: penalize so it's only chosen when open bins are bad fits
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in stream with few fitting bins, a fresh bin is less bad
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
    }

    // Reward tight fits relative to item size
    score += (item_size as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to smallest plausible item (1..100 range).
        // Dead space that can never be used is worse than moderate leftover.
        let dead = post_residual as f64;
        score += 0.8 * dead;

        // If the next item fits exactly into post_residual, strongly favor this bin.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // Next item fits: leftover after that matters (2-step lookahead).
            let two_step = post_residual - next_item_size;
            score += 0.3 * two_step as f64;
            if two_step == 0 {
                score -= 120.0;
            }
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item won't fit here; small post_residual is fine (dead space anyway).
            score -= 0.2 * dead;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 0.5 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: opening a new bin wastes current residual space.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when good fits exist elsewhere.
        score += 150.0;
        if fitting_bins_count > 0 {
            // Prefer using an existing bin unless the item is huge relative to
            // typical residuals (fragmentation risk).
            let avg_fit_gap = (mean_residual - item_size as f64).abs();
            if avg_fit_gap < 10.0 {
                score += 120.0; // existing bins fit well; don't open new
            } else {
                score -= 40.0; // existing bins fit poorly; new bin is reasonable
            }
        }
        // Late in the stream, avoid opening bins that will stay mostly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && item_size < 40 {
            score += 100.0 * progress;
        }
    }

    // Mild pressure to consolidate: fewer open bins is better; prefer bins with
    // low residual (fuller bins) when many bins are open.
    score += 0.05 * open_bins_count as f64;
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Time-adaptive tightness: early on, be slightly greedy toward full bins;
    // later, prioritize exact chains via lookahead (already handled).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, growing with stream progress
    let mut score = pr * (1.0 + 1.5 * progress) + 60.0 * norm_pr * norm_pr;

    // Dead-space penalty: residuals too small for the smallest plausible item are worthless
    let dead = (12.0 - pr).max(0.0);
    score += 25.0 * dead * dead / 144.0;

    // Reward tight fits (small post_residual relative to item)
    let tightness = 1.0 - pr / (item_size as f64 + pr).max(1.0);
    score -= 20.0 * tightness * tightness;

    // Keep large residuals available for large future items; penalize burning them on small items
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste_potential = (pr - nxt).max(0.0) / cap;
        score -= 10.0 * waste_potential; // residual can still host next item
        let too_small = (nxt - pr).max(0.0) / cap;
        score += 15.0 * too_small * too_small; // can't host next item -> future fragmentation
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: smooth sigmoid-like preference, stronger early when many bins can fit
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (open_bins_count as f64 + 3.0)) * (1.0 - progress);
        score = cap as f64 * 0.75 + 40.0 * openness + 0.5 * (item_size as f64);
        // If next item is huge, a fresh bin is attractive
        if next_item_size > 0 {
            score -= (next_item_size as f64 / cap) * 30.0;
        }
    }

    // Mild penalty when many bins are open and this placement adds fragmentation vs mean residual
    let frag = (pr - mean_residual).max(0.0) / cap;
    score += 8.0 * frag * frag * (open_bins_count as f64).min(10.0) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    // (item sizes are multiples of 10 in the classic regime; dead space
    // that is a "harmonic complement" of common item sizes is more usable).
    let post = post_residual as i64;
    let next = next_item_size as i64;

    // Reward when the NEXT item fits exactly into the post-residual (perfect chain).
    if next > 0 && next == post {
        score -= 60.0;
    } else if next > 0 && next < post {
        // Next item fits, but leaves another residual: reward proportionally
        // to how "harmonic" the remaining class is (small residue = tight).
        let rem = post - next;
        score -= 30.0 - (rem as f64) * 0.5;
    } else if next > 0 && next <= post + bin_capacity && post < 10 {
        // Next item cannot fit here; tiny dead space penalty.
        score += 15.0;
    }

    // Dead-space harmonic penalty: residuals in awkward classes (1..9 after
    // mod 10 normalization for non-multiple-of-10 streams) are less reusable.
    let class = post % 10;
    score += match class {
        0 => -8.0,          // perfectly harmonic residual
        1..=3 => 4.0,       // nearly useless sliver
        4..=6 => 0.0,       // marginal
        _ => -3.0,          // fits small items
    } as f64;

    // Integer-division thresholds on post_residual: bins whose residual can
    // still hold at least one more "typical" item (>=10) are valuable.
    if post >= 10 {
        score -= 12.0 + (post / 25) as f64 * 4.0;
    } else if post > 0 {
        score += 10.0; // sealed bin: fine, but don't prefer unless empty-ish
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many candidates, prefer tighter fits (lower post_residual wins
        // naturally, but add slight crowding pressure).
        score += (fitting_bins_count as f64) * 0.5;
    }

    // New-bin candidate handling: an empty bin (residual == capacity) should
    // only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced late in the stream or when
        // few bins are open (consolidation phase).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 55.0 - 20.0 * progress;
        if open_bins_count <= 2 { new_bin_cost -= 10.0; }
        // If next item is large, a fresh bin is more attractive.
        if next >= 50 { new_bin_cost -= 12.0; }
        score += new_bin_cost;
    }

    // Mean-residual coupling: when the fleet average residual is large,
    // packing into existing bins is cheap; penalize spreading further.
    score += (mean_residual - post as f64).max(0.0) * 0.3;

    // Mild tightness reward scaled by item size (big items should go into
    // tight bins, leaving big residuals for small items).
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits
    score -= 8.0 * (item_size as f64 / bin_capacity as f64);

    // Pressure from number of open bins: prefer reusing bins when many are open
    score += 0.6 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 12.0;
    }

    // New-bin candidate: make it unattractive unless residuals across open bins are tiny
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.3;
    }

    // Progress-based mild adaptation: later in stream, tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Penalize dead space: post-residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64 / bin_capacity as f64) * 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this leftover: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or many bins are already open (fragmentation pressure).
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > 60 {
            score -= 20.0; // big items are fine in fresh bins
        }
        if mean_residual < item_size as f64 * 0.9 {
            score -= 15.0; // open bins can't take it well
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Mild pressure to consolidate into bins below mean residual (balance).
    if (bin_residual as f64) > mean_residual && bin_residual != bin_capacity {
        score += 3.0;
    } else if bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Time horizon: early on, be more willing to open bins (long future to fill them);
    // late in the stream, prefer squeezing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 0.0 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // early on, tolerate looser fits; later, demand tighter packing
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * pr;

    // Penalize dead space relative to mean residual across open bins (smooth interaction)
    score += 0.3 * (pr - mean_residual).abs() * (1.0 + progress);

    // Lookahead coupling: reward bins whose post-residual can still fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (1.0 - progress) * (pr - nxt + 1.0).sqrt();
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong smooth reward scaled by scarcity of fitting bins
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    } else {
        score += 1.5 * (fitting_bins_count as f64).ln() * (1.0 + progress);
    }

    // Mild bonus for consolidating into already-open bins vs new bin
    score -= 2.0 / (1.0 + open_bins_count as f64);

    // New-bin candidate: prefer it only when post_residual is huge (item nearly fills a fresh bin)
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "coarse" residue classes are more reusable; reward low-class leftovers.
    let class = post_residual % 10;
    score -= (10 - class) as f64 * 0.6;

    // Integer-division thresholds: leftover divisible by common item sizes
    // (half, quarter) is highly reusable.
    if post_residual > 0 && post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual > 0 && post_residual % 50 == 0 {
        score -= 4.0;
    }
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 2.5;
    }

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Lookahead coupling: reward if the next item fits exactly or nearly
    // into the post residual (harmonic match of next_item_size class).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= (slack % 10) as f64 * 0.4 + 3.0;
        if slack == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This bin becomes dead for the next item; penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or mean residual is tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) * 0.7 + mean_residual * 0.15;
        score += 30.0 + crowded - progress * 10.0;
        if next_item_size > 0 && next_item_size > 60 {
            score -= 12.0; // big next item: fresh bin is valuable
        }
    }

    // Prefer tighter existing bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Slight preference for compacting large items early.
    score -= (item_size as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest item (1..10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    // Residuals that cannot fit the lookahead item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }
    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward using a bin whose residual is tightly consumed (small waste ratio).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: prefer existing bins when many bins are open,
    // penalize opening new bins (empty candidate has bin_residual == capacity).
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * open_bins_count as f64;
    } else {
        score -= 5.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // balances the pool, avoiding many tiny residuals.
    score += 0.5 * (mean_residual - post_residual as f64).abs();

    // Slight preference to fill bins with larger residuals early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // New-bin candidate: keep it attractive only as a fallback.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes capacity when an existing bin fits reasonably;
        // make it slightly worse than a decent existing fit but better than dead space.
        score += 55.0;
        // Early in the stream, prefer opening bins (more room for future items).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        return score;
    }

    // 2-step lookahead: reward post_residual that exactly accommodates next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0; // chain fit: this bin will be perfectly filled next step
        } else if post_residual >= next_item_size {
            // slack after next placement; smaller slack is better
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space: next item cannot use what remains; penalize proportionally
            let waste = post_residual as f64;
            score += 25.0 * (waste / 50.0).min(1.0);
        }
    } else {
        // Last item: any nonzero residual is pure waste; smallest residual wins.
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Prefer bins below mean residual (consolidating space), avoid fragmenting fat bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Tighter fit relative to current residual is better.
    score += 0.3 * (bin_residual as f64 - item_size as f64) / bin_capacity as f64 * 10.0;

    // Penalize opening extra bins when many are already open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: bonus if next item fits in the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Penalize residuals that nearly-but-don't fit the next item.
            if post_residual >= next_item_size.saturating_sub(4) {
                score += 6.0;
            }
        }
    }

    // Time horizon: early in the stream, be conservative with bin openings;
    // late in the stream, prefer consolidating into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, allow when open bins are fragmented or full-ish.
        let mut new_bin_penalty = 20.0 + 15.0 * progress;
        let fragmentation = mean_residual / (open_bins_count.max(1) as f64);
        if fragmentation > 30.0 {
            new_bin_penalty -= 10.0;
        }
        // If item barely fits nowhere well (large item), opening a new bin is fine.
        if item_size >= 60 && post_residual == 0 {
            new_bin_penalty -= 18.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: mild reward grows with progress (consolidation pressure).
        score -= 3.0 * progress;
        // Prefer bins below mean residual (balance load across bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    // Penalize opening too many bins when open bins are still roomy.
    if open_bins_count > 4 && mean_residual > 40.0 && bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - pr / cap; // fraction of capacity used
    score -= 2.5 * fill_ratio * fill_ratio * cap * 0.1;

    // Exact-ish fit bonus: smooth polynomial peak when post_residual is tiny.
    let pr_norm = pr / cap;
    score -= 8.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Lookahead coupling: penalize leaving a residual that next_item_size cannot use,
    // reward residuals that the next item can exactly consume.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let leftover = pr - nxt;
            let lo_norm = leftover / cap;
            score -= 3.0 * (1.0 - lo_norm) * (1.0 - lo_norm);
        } else {
            // dead space: unusable by next item, penalize proportionally
            score += 4.0 * (1.0 - pr / nxt) * pr_norm;
        }
    }

    // Stream-progress coupling: later in the stream, waste matters more;
    // early on, tolerate imperfect fits to keep bins flexible.
    let flex = 1.0 - progress;
    score += 3.0 * progress * pr_norm * pr_norm;
    score -= 2.0 * flex * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 * fill_ratio;
    }

    // New-bin candidate handling: empty bin gets a mild baseline penalty so that
    // decent existing fits win, but very poor fits (large pr) lose to it.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (1.0 - progress);
    }

    // Mean-residual context: when open bins are generally full, prefer this bin more.
    score -= 0.5 * (mean_residual / cap) * fill_ratio;

    // Small penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes relative to capacity fractions.
    // Residuals in the "harmonically useful" band (small, divisible-friendly) get rewarded.
    let pr = post_residual;
    if pr > 0 {
        // class 0: tiny dead space (pr <= 5) -> excellent, reward strongly
        if pr <= 5 {
            score -= 60.0;
        }
        // class 1: pr in (5, 15] -> still usable by smallest items
        else if pr <= 15 {
            score -= 25.0;
        }
        // class 2: pr in (15, 33] -> fits items of size ~16..33
        else if pr <= 33 {
            score -= 12.0;
        }
        // class 3: pr in (33, 50] -> half-bin zone
        else if pr <= 50 {
            score -= 5.0;
        }
        // class 4: large residual left -> wasteful placement, penalize
        else if pr <= 66 {
            score += 10.0;
        } else {
            score += 20.0;
        }

        // Modulo-arithmetic bonus: post_residual divisible by common item sizes
        // (10, 20, 25, 50) is more likely to be exactly filled later.
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 && pr > 0 { score -= 4.0; }

        // Integer-division threshold: pr / 10 gives "harmonic decade" of the gap.
        let decade = pr / 10;
        score -= (decade as f64) * 0.5;
    } else {
        // Perfect fit: maximal reward.
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 50.0;
        } else if slack <= 10 {
            score -= 20.0;
        } else {
            score -= (10.0 / (1.0 + slack as f64 / 20.0));
        }
    } else if next_item_size > pr {
        // Next item cannot use this bin's leftover: penalize proportional to overshoot.
        score += ((next_item_size - pr) as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: many open bins -> prefer tightening existing bins.
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 1.5;
    }

    // Mean-residual coupling: placing into a bin below mean residual is good.
    score += (mean_residual - (bin_residual as f64)) * 0.4;

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate calibration: empty bin should lose unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + post_residual as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize unusable dead space: small gaps that no item (min size 1, but
    // practically items >= 10 in classic streams) can fill.
    if post_residual > 0 {
        let dead_threshold = if item_size >= 10 { 9.0 } else { 0.0 };
        if (post_residual as f64) <= dead_threshold {
            score += 40.0; // strict dead-space penalty
        }
        // Moderate gaps: mildly penalize unless next item fits into them.
        if next_item_size > 0 {
            if (next_item_size as u32) > post_residual {
                score += 8.0; // gap unusable for the lookahead item
            } else {
                score -= 5.0; // gap is useful for the next item
            }
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: mildly discourage spreading across many bins,
    // but encourage using existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize proportionally to open bins count
        // so it only wins when fits into existing bins are truly poor.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If the new bin can host the next item well, soften slightly.
        if next_item_size > 0 && next_item_size as u32 <= bin_residual {
            score -= 5.0;
        }
    } else {
        // Existing bin: small reward to prefer re-use, scaled by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 + 2.0 * progress;
    }

    // Prefer bins below mean residual (tighter bins) slightly.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Perfect chain: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits exactly after this placement chain: penalize leaving slightly-too-small gaps
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // tiny dead space is bad
        }
    } else {
        // Last item: minimize leftover
        score += 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is very poor
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score += 10.0 + 20.0 * fit_quality; // discourage opening new bins for small items
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // allow fresh bin when a chain may follow
        }
    }

    // Late in the stream: be extra frugal with remaining capacity
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction of the bin.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Strong reward when this bin becomes perfectly filled.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.2 * item_size as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 < 10 {
                score -= 12.0; // two-item chain nearly fills bin
            }
            score -= 5.0; // mild bonus for keeping next item placeable
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // When many bins are open, consolidate; when few, allow spreading.
    if open_bins_count > 3 {
        score += 2.0 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: make opening a new bin costly early,
    // but acceptable late in the stream or when the fit here is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 - 15.0 * progress;
        // If the item is large and would leave a big hole in any open bin,
        // opening fresh is more attractive.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // large items coming: fresh bin useful
        }
    }

    // Mild time pressure: late in the stream, avoid leaving tiny residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalized non-linearly by post-residual
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth progress coupling: late in stream, tighten more aggressively
    let tightness = 1.0 + 2.0 * progress * progress;
    score *= tightness;

    // Penalize post-residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 30.0 * gap * gap * (1.0 - progress);
        } else {
            // Reward bins that can also host the next item
            score -= 8.0 * (pr / (pr + nxt)) * (0.5 + progress);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    let mean_norm = mean_residual / cap;
    score += 5.0 * mean_norm * mean_norm * (open_bins_count as f64).sqrt() * progress;

    // New-bin candidate: make empty bins moderately attractive only when
    // post-residual would be large (poor fit elsewhere)
    if bin_residual == bin_capacity {
        score = pr + 25.0 - 20.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strong bonus for small but usable leftovers.
    if post_residual > 0 {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * fill_frac;
        // Harmonic class of post_residual modulo capacity quarters:
        // leftover classes that pair well with small items get a discount.
        let quarter = bin_capacity / 4;
        match post_residual % quarter {
            0 => score -= 8.0,      // exact quarter boundaries: reusable
            _ => {}
        }
        // Penalize dead space too small for the smallest plausible item (1..=10).
        if post_residual < 10 {
            score += 25.0;
        } else {
            // reward leftovers that can host a medium item
            score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Perfect closure of the bin is ideal.
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // extra reward if next item nearly fills the leftover
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover that next item cannot use: mild penalty scaled by waste
        score += 4.0 * (1.0 - (next_item_size as f64 / post_residual as f64).min(1.0));
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it wins only when
    // the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        score = 0.5 * bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // forced new bin
        } else if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0; // current bin can't host the follow-up either
        }
        // fewer open bins -> slightly prefer reusing over spreading
        if open_bins_count > 4 {
            score += 3.0;
        }
    }

    // Mean-residual coupling: if this bin is much emptier than average,
    // it's a good consolidation target.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Stream progression: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest conceivable item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // gaps 10..19 can only fit tiny items: moderate dead-space penalty
        score += 12.0;
    }

    // Reward near-perfect fits (waste almost zero).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing ones
    // over opening new bins; the new-bin candidate (residual == capacity)
    // gets penalized proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 30.0 + 6.0 * open_bins_count as f64;
        // Late in the stream, opening a new bin is less costly (fewer future
        // placements to consolidate), so ease the penalty slightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    } else {
        // Reuse reward, stronger when many bins are open.
        score -= 1.0 + 0.15 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin for an awkward item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Coupling with mean residual: placing into a bin whose residual is far
    // below the mean tightens the spread of residuals (good); placing into
    // an outlier-large residual bin may be wasteful.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Lookahead: if the next item can use this bin's post_residual, reward;
    // if post_residual is useless for the next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match reward: next item fits snugly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward decays as slack grows: tight chains are good
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space: post_residual too small for the lookahead item
        // Penalize proportionally to wasted capacity (unusable residual)
        score += 25.0 * (post / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already tight; using them is fine, but bins far above mean should
    // absorb large items to keep the residual distribution balanced.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a good fit. Penalize it mildly so tight existing
    // fits win, but let it beat bins with large dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, opening bins is cheap and useful
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin preserves flexibility
        if next >= 50.0 {
            score -= 10.0;
        }
    }

    // Slight penalty when post_residual is tiny but nonzero (unusable sliver)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: superlinear waste for small leftovers that few future items can use.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 30.0 * (10.0 - dead); // tiny leftovers are nearly worthless
        }
    }

    // Reward tight fits (exact or near-exact fill).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, this placement chains well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to gap
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer using it
    // over opening a new bin (avoids wasting an almost-full bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the item is large
    // relative to capacity (poor fit anywhere else) or many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins for small items; relax penalty for large items late in the stream.
        let new_bin_penalty = 60.0 * (1.0 - fill_ratio) * (1.0 - 0.3 * progress);
        score += new_bin_penalty;
        // Fragmentation pressure: many open bins with high mean residual -> opening fresh bin
        // can be fine, but if mean residual is low, reuse is cheap; discourage new bin slightly.
        score += 0.1 * mean_residual - 0.5 * open_bins_count as f64;
    } else {
        // Reusing an existing bin: reward keeping the spread of residuals tight around mean.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        // Slight preference for filling fuller bins first (best-fit bias beyond raw post_residual).
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: prefer small post-residual, with non-linear saturation
    let mut score = pr * (1.0 + 0.8 * pr / cap) - 12.0 * (pr / cap).powi(3);

    // Stream-progress coupling: early on, tolerate larger residuals; later, tighten
    score += 20.0 * progress * (pr / cap);
    score -= 15.0 * (1.0 - progress) * (pr / cap).powi(2);

    // Smooth interaction: item size vs residual (favor tight fits)
    score += 0.05 * it * (pr / (cap - it + 1.0));

    // Lookahead coupling: reward if next item fits into post_residual (smooth kernel)
    if nx > 0.0 {
        let fit_gap = (nx - pr).abs();
        score -= 10.0 * (-fit_gap / 20.0).exp();
        score += 0.05 * nx;
    }

    // Last-chance bin: strong smooth reward when few fitting bins
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }
    score += 2.0 * (fitting_bins_count as f64 - 1.0).max(0.0);

    // Mean-residual dispersion penalty (encourage balanced residuals)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: penalize mildly unless current bin would leave dead space
    if bin_residual == bin_capacity {
        score = cap * 1.5 + 10.0 * progress - 0.2 * it;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: small classes are "dead space" traps.
    let dead_class = post_residual % 10;
    score += (10 - dead_class) as f64 * 0.7; // penalize residuals far below a multiple of 10

    // Reward near-zero post residual (perfect closure).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Integer-division threshold: post_residual in [1,20] is hard-to-fill zone.
    if post_residual >= 1 && post_residual <= 20 {
        score += 15.0;
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0 - 0.3 * post_residual as f64;
    }

    // Coupling with mean residual: prefer bins with residual below mean (tighter bins).
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    // Late in stream: close bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Harmonic fraction of capacity used.
    let used_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= used_frac * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps
    // (gaps below the minimum plausible item size are pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    } else {
        // Larger gaps are reusable; mildly reward tight-but-usable fits.
        score -= 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a forced new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // would create severe dead space or are nearly full.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        } else if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0; // open bins are too fragmented anyway
        }
        // Pressure from many open bins makes opening less attractive.
        score += open_bins_count as f64 * 1.5;
    }

    // Lookahead: if the next item would fit in this bin's post-residual,
    // reward chaining; penalize if post-residual would block the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Bin-count pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Slight late-stream tightening: keep bins tight as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // Next item fits here: reward proportionally to how snugly.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 30.0 * snug;
        } else {
            // Next item cannot fit here: penalize dead space left behind.
            let dead = post_residual as f64;
            score += 0.15 * dead;
            // Extra penalty if dead space is too small for typical items.
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (denser bins)
    // to keep emptier bins flexible for future items.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.08 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when reasonable fits exist, unless stream is early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 55.0 - 20.0 * (1.0 - progress);
        // But allow new bin if this bin would leave tiny unusable residue.
        if post_residual > 0 && post_residual < 10 {
            score -= 40.0;
        }
    }

    // Mild penalty for too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Utilization of this placement: fraction of the bin filled by the item
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio; // reward high-utilization placements

    // Dead-space penalty: small post-residuals that cannot fit typical items are wasted
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < next_item_size as u32 && next_item_size > 0 {
        // next item cannot fit here; penalize proportionally to how much it misses
        score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // lookahead fits: reward chaining placements in the same bin
        score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competing bins: slight tie-break toward tighter fits via post_residual already handled
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Default: discourage opening a new bin (its raw post_residual is large anyway),
    // but allow it when existing fits are poor (large waste) or stream is early/late.
    if bin_residual == bin_capacity {
        let waste_threshold = mean_residual.max(0.0);
        // opening a new bin is attractive if current mean residual is large (fragmented bins)
        score += 5.0;
        score -= 0.10 * waste_threshold;
        // early in the stream, building fresh bins is cheap; late, conserve bins
        score -= 10.0 * (1.0 - progress);
        // if the item is large relative to capacity, a fresh bin gives clean future space
        score -= 20.0 * fill_ratio * fill_ratio;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Small tie-breaker noise-free deterministic jitter based on step parity
    score += if step_index % 2 == 0 { 0.01 } else { -0.01 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals less (waste compounds over many items);
    // late, a tight fit matters even more.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * pr_norm * pr_norm * (3.0 * progress);
    score += 60.0 * poly;

    // Reward when the leftover could host the next item (smooth interaction)
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nxt = next_item_size as f64;
        let slack = (pr - nxt) / cap;
        score -= 25.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        // post-residual too small for next item: penalize dead space non-linearly
        let dead = pr / cap;
        score += 20.0 * dead * dead;
    }

    // Last-chance bonus: only one bin fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - pr_norm);
    }

    // Mild penalty when bin is far below mean residual (keeps bins balanced)
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: opening a fresh bin should lose unless the item fits
    // poorly everywhere; make the empty bin score moderately high but scaled
    // by progress (early stream: reusing bins is cheap; late: new bins fine).
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.3 * progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic dead-space classes: residuals that can likely never be used again
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 30.0; // tiny dead space is nearly worthless
    } else if pr >= 10 && pr < 20 {
        score += 12.0; // only smallest items can use it
    } else if pr == 0 {
        score -= 20.0; // perfect closure: reward exact fills
    }

    // Coarse harmonic bucketing of post_residual (integer division thresholds)
    score += ((pr / 25) as f64) * 3.0;

    // Modulo-class coupling with next item: residual that harmonically aligns
    // with the lookahead item's size class is valuable
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            score -= 10.0;
            // extra reward when residual is a near-exact multiple class of next item
            if pr % n == 0 {
                score -= 6.0;
            } else if pr - n <= 5 {
                score -= 4.0;
            }
        } else {
            score += 6.0; // lookahead item can't use this bin's remainder
        }
    }

    // New-bin candidate handling: penalize opening a fresh bin when alternatives exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 8.0 * fitting_bins_count as f64
               + 20.0 * (1.0 - progress); // late in stream, prefer consolidation less strictly
        // but if the item is large, a new bin is relatively more attractive
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Alignment with mean residual: prefer bins whose remainder diverges usefully
    score -= 0.15 * (mean_residual - pr as f64).abs();

    // Mild pressure against bin sprawl
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, min item size)
    // are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that are small relative to the smallest plausible item are also risky.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has residual == capacity, so this term hurts it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below average (they are the "worst fitting"
    // leftovers) -> consolidate waste into bins that can't serve future items well.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Lookahead: if the next item could use this bin's post-residual exactly,
    // reward leaving that space; otherwise if post_residual is large enough for
    // the next item anyway, no penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Mild penalty for the brand-new bin candidate so it only wins when
    // existing fits are truly poor.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to tightness
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item won't fit here: penalize large dead space
            score += 0.15 * diff;
        }
    }

    // Reward tight fits relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist, unless item is huge
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let mut penalty = 30.0 * (1.0 - fill_frac);
        if open_bins_count > 0 && next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // new bin could also host next item: mild bonus
            penalty -= 10.0;
        }
        score += penalty;
    }

    // Late-stream: prefer closing bins tightly (small post_residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good; amplify near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else {
        // Penalize dead space relative to smallest plausible future item (1..100 range).
        let t = step_index as f64 / (total_items.max(1) as f64);
        // Dead space becomes more costly as stream progresses (less chance to fill it).
        let urgency = 0.5 + 1.5 * t;
        score += urgency * (post_residual as f64).powf(1.3) * 0.05;

        // If post_residual cannot accommodate the next item, mild penalty unless it's tiny.
        if next_item_size > 0 {
            if (post_residual as u32) < next_item_size {
                score += 8.0 * urgency;
            } else {
                score -= 4.0; // this bin remains useful for the lookahead item
                // Bonus if next item exactly fills the remaining space after this placement.
                if post_residual == next_item_size {
                    score -= 12.0;
                }
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    // or the bin landscape is fragmented.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its full empty capacity is "wasted potential".
        score += 60.0;
        // Opening new bins is more attractive early (room to build good structure)
        // and when existing residuals are fragmented (high mean residual spread).
        let frag = (mean_residual - post_residual as f64).abs();
        score -= 20.0 * (1.0 - step_index as f64 / (total_items.max(1) as f64));
        if mean_residual > 0.0 && frag > item_size as f64 {
            score -= 15.0; // fragmentation justifies a fresh bin
        }
        // If item is large relative to capacity, new bin is often fine.
        if item_size * 2 >= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Reward filling bins that are already partially committed.
        let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio;
        // Slight penalty for spreading across too many open bins when residuals are large.
        if open_bins_count > 4 && mean_residual > 40.0 {
            score += 3.0;
        }
    }

    // Global pressure: when many bins are open, prefer consolidating into existing ones.
    score += 0.15 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fit), scaled polynomially.
    let mut score = post * (1.0 + norm_post * norm_post);

    // Smooth non-linear coupling with stream progress: later in the stream,
    // increasingly punish leftover space (dead space matters more near the end).
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += progress_coupling * post * norm_post * 2.0;

    // Interaction with mean residual: bins far below mean residual are better
    // candidates to absorb this item (they are already "loose").
    let mean_gap = mean_residual - post;
    score += 0.35 * mean_gap * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_post);
    } else {
        // Slight penalty when many bins compete, encouraging consolidation.
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - nxt / cap);
        } else {
            // Penalize blocking the next item by a smooth overflow term.
            let overflow = (nxt - post) / cap;
            score += 18.0 * overflow * overflow;
        }
    }

    // Mild penalty for opening a new bin when many bins are already open,
    // unless the residual is large (a fresh bin is genuinely useful).
    if bin_residual == bin_capacity {
        let new_bin_cost = 8.0 + 0.6 * open_bins_count as f64;
        let new_bin_benefit = 30.0 * norm_post * (1.0 - progress);
        score += new_bin_cost - new_bin_benefit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: finer dead space is worse.
    let class = post_residual / 10;
    score += match class {
        0 => -30.0,                 // near-perfect fit
        1 => -10.0,
        2 => 0.0,
        3 => 5.0,
        4 => 10.0,
        _ => 15.0,                  // large dead space
    };

    // Reward if the lookahead item fits exactly into post_residual (chained perfect fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // next item would have fit this bin only via current item placement choice
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Modulo harmonic penalty: post_residual in awkward residue classes (e.g. 1..9 leftovers)
    // that few item sizes can fill.
    let m = post_residual % 20;
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny slivers are dead space
    }
    if m == 0 {
        score -= 6.0; // round residuals are reusable
    }

    // Empty new-bin candidate: prefer it when current bins are mostly full
    // or when the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual / bin_capacity as f64;
        // open a new bin if existing residuals are small or item is big
        if tight < 0.25 || item_size > 60 {
            score -= 20.0 * (1.0 - tight) + progress * 5.0;
        } else {
            score += 10.0; // discourage wasting a fresh bin
        }
    }

    // Slight preference for bins below mean residual (balance load).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps after placement.
    // A gap is "dead" if it is too small to hold any plausible future item
    // (items range 1..100, but small gaps below ~10 are nearly always wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps slightly above the minimum are semi-dead: penalize proportionally.
    if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Coupling with mean residual: if this bin's post-fit residual is far below
    // the mean residual, it uses space efficiently relative to the pool.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.2;
    }
    // Penalize leaving a gap that just barely misses the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: make the empty bin moderately attractive only when
    // current fits are poor (high post residual elsewhere); slight bias to reuse.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to the miss.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.4 * miss;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // the mean residual of open bins (open bins are too tight for future flow).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / mean_residual.max(1.0);
        score += 45.0 - 30.0 * tightness.min(2.0);
        // Late in the stream, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Reward packing into bins tighter than average.
        score -= 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space under
    // the smallest plausible item (<=10) is truly wasted.
    if post_residual < 10 {
        score -= 25.0; // perfect/near-perfect fill
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Penalize large leftover space only mildly; the new-bin candidate
    // naturally has post_residual = C - item, so keep base comparable.

    // Lookahead coupling: if next item fits into this bin's post-residual,
    // reward chaining two items into one bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.15; // prefer chain with tight second fit
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            score += (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is costly; make it
    // attractive only when the fit is large relative to capacity or when
    // open bins are mostly full (mean residual low).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 45.0 // base cost of opening a bin
            - fill_ratio * 40.0;      // big items deserve fresh bins
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        new_bin_score -= mean_fill * 20.0; // when existing bins are nearly full, new bin is fine
        if open_bins_count == 0 {
            new_bin_score -= 100.0; // must open first bin
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 10.0;
        score = new_bin_score;
    } else {
        // Slight preference for fuller bins among open candidates.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
        // Avoid draining bins that remain the best host for future big items:
        if bin_residual < 30 && post_residual > 0 {
            score += 3.0;
        }
    }

    // Mild global pressure: many open bins -> consolidate into existing ones.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear penalty on mid-range residuals
    let mut score = pr as f64;
    score += 18.0 * (norm_pr - 0.5) * (norm_pr - 0.5) * (norm_pr - 0.5).abs() * 4.0;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = (norm_pr * (1.0 - progress)) * (norm_pr - 0.35);
    score += 22.0 * coupling * coupling * (1.0 + progress);

    // Penalize creating dead space relative to mean residual of open bins
    let dead = (pr as f64 - mean_residual).max(0.0) / cap;
    score += 10.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack) * (0.5 + progress);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Mild pressure to consolidate: fewer open bins relative to stream length
    score += 3.0 * (open_bins_count as f64 / (total_items.max(1) as f64)) * 10.0 * progress;

    // New-bin candidate: penalize opening a fresh bin unless it enables a good pairing
    if bin_residual == bin_capacity {
        score += 14.0 - 10.0 * progress;
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 16.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let has_next = next_item_size > 0;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64) } else { 0.0 };

    // Baseline: best-fit (smaller leftover => lower score)
    let mut score = post;

    // Perfect closure: bin exactly filled
    if post_residual == 0 {
        score -= 4.0;
    }

    // Micro-sliver dead zone via integer-division threshold on capacity (cap/20)
    let sliver = bin_capacity / 20;
    if post_residual > 0 && post_residual <= sliver {
        score += 1.5 + 1.5 * progress; // late in the stream, stranded slivers are permanent waste
    }

    // Harmonic lookahead coupling with the next item
    if has_next {
        if post_residual >= next_item_size {
            // Reward snugness: leftover mostly consumed by the next item
            let fill = next / (post + 1.0);
            score -= 1.5 + 3.5 * fill;
            // Modulo logic: exact multiple => zero-waste chaining of identical items
            if post_residual % next_item_size == 0 {
                score -= 2.0;
            }
            // Same harmonic class: floor(cap/x) equal => proportionally matched sizes
            let cls = |x: f64| (cap / x.max(1.0)) as u32;
            if cls(post) == cls(next) {
                score -= 1.2;
            }
        } else {
            // Leftover is dead for the next item: penalize, but among dead leftovers
            // prefer larger ones (they retain optionality for later, smaller items)
            let dead = (next - post) * 0.5;
            score += dead * (0.7 + 0.6 * progress);
        }
    }

    // Scarcity: residuals that few bins can reproduce are harmonically rare; use them
    if fitting_bins_count >= 1 {
        score -= 2.0 / fitting_bins_count as f64;
    }
    if fitting_bins_count == 1 {
        // Last chance before opening a new bin: strongly prefer this bin
        let mut bonus = 5.0 + 2.0 * progress;
        if has_next && post_residual < next_item_size {
            bonus -= 3.0; // dead leftover reduces urgency of using it
        }
        if has_next && post_residual >= next_item_size {
            bonus += 2.0; // next item chains here, extra urgency
        }
        score -= bonus;
    }

    // Fragmentation consolidation: favor filling below-average (more fragmented) bins
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    // New-bin candidate: discourage proliferation, scaled by open-bin pressure
    if bin_residual == bin_capacity {
        score += 1.5 + 0.4 * open_bins_count as f64;
        // Ease up if the fresh bin would chain snugly with the next item
        if has_next && post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item are "dead" — penalize them hard.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward bins whose residual after placement can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // near-miss wastes future opportunity
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage fragmenting further,
    // favor consolidation into existing bins.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate handling: empty bin should only win when the item is
    // large and fits poorly anywhere else.
    if bin_residual == bin_capacity {
        score += 45.0; // default penalty for opening a new bin
        if item_size >= 50 && (fitting_bins_count == 0 || fitting_bins_count == 1) {
            score -= 55.0;
        }
    }

    // Tight-fit bonus: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but tiny slivers (< 10)
    // are dead space unless the next item can use them.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // dead-space penalty
    }

    // Aggressive 2-step lookahead: if next item exactly fills post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 0.5 && pr > 0.0 {
            score -= 60.0; // perfect two-item completion
        } else if nxt <= pr && pr - nxt < 10.0 {
            score -= 40.0; // next item fits leaving near-zero waste
        } else if nxt <= pr {
            score -= 15.0; // next item fits comfortably
        } else {
            // next item won't fit here: penalize more when this bin is
            // relatively full compared to the fleet average.
            score += 10.0 + 0.3 * (mean_residual - pr).max(0.0);
        }
    }

    // Prefer bins whose residual is close to item_size (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when the item is large
    // relative to capacity (big items deserve fresh bins).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 50.0 * frac; // large item -> lower score for new bin
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powi(3);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post-residual gap
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Dead space penalty scaled by how much next item overshoots
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.15 * overshoot;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when many open bins exist with slack
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins are fragmented
        let fragmentation = (mean_residual - item_size as f64).abs();
        score += 15.0 + 0.5 * open_bins_count as f64 - 0.3 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Mild preference for using bins with below-average residual (balance)
    if bin_residual < bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Late in stream: be more conservative, avoid waste
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste shaping: penalize large residuals more as stream progresses
    let norm_post = post / cap;
    score += 30.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth falloff
    score -= 25.0 * (-norm_post * 4.0).exp();

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 18.0 * (1.0 - (next_item_size as f64 / cap));
        } else {
            // dead space penalty scaled by how much next item misses fitting
            let miss = (next_item_size as f64 - post) / cap;
            score += 15.0 * miss * miss;
        }
    }

    // New empty bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
        // but if current bin would leave huge dead space, new bin becomes attractive
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    // Coupling with mean residual: prefer bins deviating from mean when mean is high
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: sizes bucketed by modulo 10 classes
    let item_class = (item_size % 10) as f64;
    let item_bucket = (item_size / 10) as f64;

    // Harmonic class of post_residual: residual mod classes
    let post_class = (post_residual % 10) as f64;
    let post_bucket = (post_residual / 10) as f64;

    // Reward tight fits: small post_residual
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space: post_residual that no typical item (>=1) can use well
    // Residuals in (0,10) are nearly dead; residuals in harmonic-friendly zones are fine.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Residual classes that pair well with common small items (10..=30)
    if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0;
    }

    // Harmonic pairing: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fill;
        } else {
            // next item does not fit here: penalize slightly, this bin becomes dead
            score += 4.0;
        }
        // modulo harmony: next_item_size shares class with post_residual
        if post_residual > 0 && (next_item_size % 10) == (post_residual % 10) && next_item_size <= post_residual {
            score -= 6.0;
        }
    } else {
        // last item: prefer any bin, minimize final waste
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Fractional capacity logic: prefer bins whose residual fraction is a "harmonic" fraction
    let post_frac = post_residual as f64 / cap;
    if (post_frac * 10.0).fract() < 1e-9 {
        // residual is an exact decile of capacity: clean class
        score -= 3.0;
    }

    // Mean residual coupling: if this bin is far below mean residual (already tight), favor it
    score += (mean_residual - post_residual as f64) * 0.15;

    // Early stream: be more aggressive about keeping bins tight (many items to come)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += post_residual as f64 * 0.1;
    } else if progress > 0.8 {
        score -= post_residual as f64 * 0.05;
    }

    // New empty bin candidate: penalize unless nothing fits well elsewhere
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if item is large and mean residual across bins is small, opening is reasonable
        if item_size as f64 > mean_residual + 10.0 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Small bonus for using bins with many open bins (consolidation pressure)
    if open_bins_count > 5 {
        score -= 2.0;
    }

    // Integer-division threshold on post bucket: residual buckets 0-1 (near full) are excellent
    if post_bucket <= 1.0 && post_residual > 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are pure waste. Penalize them quadratically.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 4.0;
    }

    // Bonus for tight fits (low post residual but still usable).
    if post_residual > 0 {
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward last-chance bins (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // would strand space the next item can't use
    }

    // New-bin candidate calibration: an empty bin has post_residual = C - item.
    // Make it attractive only when the current fit is poor.
    if bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Mild preference for bins with below-average residual (fuller bins).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    // -> this bin will be perfectly filled by the NEXT item. Strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item can fit into post_residual comfortably
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - 2.0 * slack; // tighter fit for next item is better
    }
    // Next item cannot fit here: penalize proportionally to wasted lookahead opportunity
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits now (small post_residual) with a non-linear bonus
    if post_residual <= 10 {
        score -= 150.0; // nearly perfect fill
    } else if post_residual <= 25 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless post_residual would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
        if post_residual > 40 {
            score += 80.0; // but avoid leaving huge dead space in last-chance bin
        }
    }

    // Discard fragment bins: residuals too small for any item (min size 1, but
    // tiny residuals relative to mean are low-utility). Compare against mean residual.
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large and would leave a very poor fit in existing bins.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = (bin_capacity - item_size) as f64 + 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin pairs well with next item
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open new bin
        }
    }

    // Late in the stream, prefer closing out bins (reduce open-bin sprawl)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 {
        score += 2.0 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residue too small for the minimum item size (1..100 unknown, use a soft threshold around 10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // dead space that even the next item can't use
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += 6.0;
        // if several bins already fit this item elsewhere, discourage opening another
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).min(4.0);
        }
        // early in the stream, opening bins is cheaper (builds diversity)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // if open bins are collectively full-ish, a new bin is fine
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 5.0;
        }
    } else {
        // Prefer bins with larger residual among ties (best-fit is encoded by post_residual already,
        // but tilt toward bins that were "meant" for big items)
        score += (bin_residual as f64) * 0.02;
    }

    // Slight preference to keep number of open bins from exploding late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * progress;

    // Mean-residual coupling: if mean residual is high, prefer filling the emptiest bins
    if (bin_residual as f64) > mean_residual {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits (favor spreading); late, punish dead space harder.
    let coupling = 0.35 + 0.9 * progress * progress + 0.4 * progress;
    score += coupling * (norm_post * norm_post) * cap;

    // Interaction with mean residual: penalize if this bin is much looser than average.
    let mean_norm = mean_residual / cap;
    score += 12.0 * (norm_post - mean_norm) * (norm_post - mean_norm) * cap * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    } else {
        // Slight penalty when many bins compete, to encourage consolidation.
        score += 2.0 * ((fitting_bins_count as f64).ln().max(0.0));
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0) * (0.4 + 0.6 * progress);
        // If next item fits exactly in the post residual, big reward.
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        }
    } else {
        // Last item: strongly prefer minimal post residual.
        score -= 20.0 * (1.0 - norm_post);
    }

    // Mild consolidation pressure: fewer open bins relative to stream is good.
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate shaping: empty bin should win only when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer-division buckets of capacity/10.
    let bucket = post_residual / (bin_capacity / 10);
    match bucket {
        0 => score -= 40.0,           // near-perfect fit, dead space < 10
        1 => score -= 25.0,           // small leftover
        2 => score -= 12.0,           // moderate leftover
        3 => score -= 5.0,            // half-ish bin remains
        4 => score += 8.0,            // large leftover, wasteful
        _ => score += 15.0,           // bin barely used
    }

    // Modulo-10 harmonic: leftovers divisible by 10 pair well with
    // items of size 10..80 in typical streams.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 && post_residual >= 20 {
        score -= 4.0;
    }

    // Lookahead coupling: reward leftovers that exactly fit next item,
    // penalize leftovers slightly larger than next item (bad pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current
    // item is large and leftovers would be tiny anyway.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= bin_capacity * 3 / 4 {
            score -= 35.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer tightest residual among open bins: scale by global tightness.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual) * (0.3 + 0.5 * progress);

    // Slight preference for filling bins with larger items early.
    score -= item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    } else {
        // Larger residual space is valuable: reward keeping big gaps.
        score -= (post_residual as f64 - 35.0) * 0.15;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + next_item_size as f64 * 0.1;
    }
    // If next item would be blocked by the dead space left here, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer tighter bins relative to the fleet mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight progression term: early in the stream, allow new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near matches of next item into the post-residual (2-step lookahead).
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post_residual as f64;
        if next_fits {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 25.0 + 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize residuals that are unusable for the next item but small (dead space).
            let dead = post_residual as f64;
            if dead < next_item_size as f64 && dead < 30.0 {
                score += 12.0 * (1.0 - dead / 30.0);
            }
        }
    }

    // Prefer tight fits relative to mean residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Deviation from mean residual: prefer bins close to the mean (balanced packing),
    // penalize outliers slightly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline; make it attractive only when
    // the item fits poorly everywhere (large post_residual elsewhere is already penalized).
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    // Slight preference to fill older bins as stream progresses.
    score -= 2.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio bonus.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 30.0 * fill * fill;

    // Penalize dead space that is too small to be useful later (below min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Next item won't fit here; if this bin would be left with useless residual, penalize.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened carelessly.
        score += 20.0;
        // If item is large, a fresh bin is attractive (large items pair well with later smalls).
        if item_size as f64 > 0.6 * cap {
            score -= 15.0;
        }
        // Late in the stream, avoid spreading out.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * t;
        // Many open bins with high mean residual: prefer using them.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
    }

    // Prefer bins below mean residual (consolidate emptier bins).
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    // Mild penalty for opening many bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - t) + x * x * x * t;
    score += 20.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tight = 1.0 - x;
    score -= 15.0 * tight * tight * (0.5 + 0.5 * t);

    // Penalize dead space that can't fit the lookahead item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 8.0 * (1.0 - pr / ns) * (1.0 + t);
        } else {
            score -= 3.0 * (pr / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild pressure from open bins count relative to stream length
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // Deviation from mean residual (prefer typical bins)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: prefer it only when post_residual of a fresh bin is attractive
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fill is best; small dead space penalized superlinearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 60.0 - (post_residual as f64) * 3.0;
    } else if post_residual <= 20 {
        score += (post_residual as f64 - 10.0) * 2.0;
    }

    // Dead-space penalty when residual can't fit the next item (waste pocket).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward if next item fits snugly into the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }

    // Modulo-10 harmonic classes of post_residual: multiples of 10 leave reusable space.
    let cls = post_residual % 10;
    if cls == 0 && post_residual > 0 {
        score -= 8.0;
    } else {
        score += cls as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Prefer the tightest among many candidates: residual already in score.
        score += (fitting_bins_count as f64) * 0.5;
    }

    // New-bin candidate: only attractive when open bins are quite full or none fit well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if open_bins_count == 0 {
            score -= 50.0;
        } else if pressure < 0.25 {
            score += 120.0; // open bins mostly empty -> don't open another
        } else {
            score += 35.0 * pressure;
        }
        // Early stream: opening bins is cheaper.
        score -= (step_index as f64 / total_items.max(1) as f64) * 20.0;
    }

    // Slight preference for filling fuller bins (tight coupling to mean residual).
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are unusable.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 200.0; // hard penalty for creating unusable gap
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward bins whose residual can still host the next item after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.25 * next_item_size as f64;
        } else {
            // leftover can't host next item: mild penalty scaled by how close it was
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    if bin_residual == bin_capacity {
        // candidate for a brand-new bin
        score += 80.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 150.0; // no open bin fits: opening new bin is correct
        }
    } else {
        score += 5.0 * open_bins_count as f64;
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream, tighten packing (favor dense fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit)
    let post = post_residual as f64;
    score += 0.35 * post * post / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills remaining space
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0; // exact 2-item completion
            }
        } else {
            // Next item won't fit here -> residual becomes dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.9 * dead;
        }
    } else {
        // Last item: just minimize post_residual
        score -= 5.0;
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score += 0.5 * (post - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening new bins when good fits exist among open bins
    if bin_residual == bin_capacity {
        // New bin candidate: score is its full residual; add penalty so it's
        // only chosen when no open bin offers a decent fit
        score += 15.0;
        // But if next item is large and no bin chains well, a fresh bin is fine
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Early in stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (open_bins_count as f64 / (total_items.max(1) as f64).sqrt());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is already good via base term.
    // Strong bonus for near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize creating dead space that likely can't be reused:
    // small leftovers (1..=9) are hard to fill later.
    if post_residual >= 1 && post_residual <= 9 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 + 10.0 * chain_quality;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item could have fit here but won't after this placement:
            // mild penalty unless post_residual is very small.
            if post_residual > 10 {
                score += 8.0;
            }
        }
        // If next item is large, prefer consuming this bin's space now.
        if next_item_size >= 60 && post_residual < next_item_size {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when current
    // open bins are nearly full on average and the fit here is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a new bin is chosen only when justified.
        score += 45.0;
        // Justify a new bin when mean residual is small (bins nearly full)
        // and this placement would leave awkward dead space.
        let tight_state = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 50.0 * tight_state;
        // Late in the stream, opening new bins is less costly than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If no open bin fits well, new bin becomes attractive.
        if post_residual >= bin_capacity {
            // item didn't fit logic (shouldn't happen), neutralize
            score += 0.0;
        }
    } else {
        // Mild reward for using existing bins, scaled by how many exist.
        let crowding = (open_bins_count as f64).ln().max(1.0);
        score -= 5.0 / crowding;
    }

    // Global balance: penalize placements that diverge the bin's residual
    // far from the mean residual (keeps residuals homogeneous, easier packing).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * deviation;

    // Time horizon: early in stream, be conservative (favor tight fits more);
    // late in stream, prioritize just fitting items anywhere.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: minimize post residual (tight fit), smoothed polynomial
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (dead space penalty grows)
    let pr_norm = pr / cap;
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Perfect fit bonus (strongly reward zero-ish residual)
    if pr == 0 { score -= 100.0; }
    else if pr <= 10 { score -= 20.0 * (1.0 - pr / 10.0); }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack * slack) * (0.3 + 0.7 * (1.0 - progress));
        } else {
            // post residual cannot host next item: mild penalty scaled by residual size
            score += 5.0 * pr_norm;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New bin candidate: penalize mildly early, allow late in stream when fits are bad
    if is_new_bin {
        score += 25.0 - 20.0 * progress;
        // discourage new bin when a good fitting bin exists
        if fitting_bins_count >= 1 {
            score += 10.0;
        }
    }

    // Residual dispersion: prefer bins below mean residual (tighter bins)
    score -= 3.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: quantize post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Dead-space penalty: residuals that cannot fit the smallest plausible item (<=10)
    // are nearly worthless; penalize small-but-nonzero leftovers sharply.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit reward: harmonic class 0.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Class the residual into integer-division buckets (harmonic classes of C/10).
    let class = post_residual / 10; // 0..10
    score -= (10 - class.min(10)) as f64 * 3.0;

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly: leftover can host the next item.
            let tightness = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 15.0 + 10.0 * tightness;
        } else if next_item_size > bin_residual {
            // Next item cannot fit anywhere in this bin anyway; leftover value is lower.
            score += 5.0;
        } else {
            // Next item fits this bin only if placed elsewhere first: dead-end risk.
            score += 20.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that scales with
    // how many bins are already open, so we prefer filling existing bins unless
    // the fit is terrible.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + (open_bins_count as f64) * 2.0;
        // Allow a new bin if the item is huge and would leave a bad residue elsewhere.
        if item_size >= 70 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // room for a clean pair in the fresh bin
        }
        return score;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // mildly, so we don't create extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late in the stream, tighten up: waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += frac * 30.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically < 10 after item sizes 10..80) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver -> strong penalty
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.6;

    // Lookahead: prefer placements that still leave room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Bonus if the next item would also fit snugly afterwards.
            let post2 = post_residual - next_item_size;
            if post2 < 10 {
                score -= 4.0;
            }
        } else {
            score += 3.0; // forces a new bin for the next item anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bin would leave big dead space
        // or nothing fits well; otherwise penalize.
        let dead = post_residual as f64;
        score += 55.0 + pressure;
        if dead > 45.0 {
            score -= 20.0; // current placements would waste a lot anyway
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    } else {
        // Favor bins with residual far from mean? No: favor bins below mean residual
        // (denser bins) to keep many large-residual bins available.
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
        score -= pressure * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Next item can also go here: chain bonus scaled by how snugly it fits
            let snug = 1.0 - ((post_residual as f64) - nxt) / (bin_capacity as f64);
            score -= 15.0 * snug;
        } else {
            // Next item won't fit after this placement: penalize dead space
            score += 0.5 * ((post_residual as f64) - nxt);
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "efficient" bins;
    // placing into them keeps mean low. Penalize using high-residual bins.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.35 * (res - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make opening a new bin unattractive unless the fit is poor
    if bin_residual == bin_capacity {
        // Waste of a fresh bin for a small item is very bad
        score += 40.0 + 0.8 * (bin_capacity - item_size) as f64;
        // Early in the stream, opening bins is more acceptable
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for leaving very small unusable fragments
    if res > 0.0 && res < 10.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus (item exactly fills the bin).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling: penalize leaving a residual that neither fits nor
    // is close to the next item, reward residuals that match the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can still go here: keep this bin usable.
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += 0.35 * post_residual as f64;
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit, i.e. when the item barely fits anywhere.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more when many bins are open and late in stream.
        score += 30.0 + 5.0 * openness * (0.5 + 0.5 * progress);
        // But relax the penalty if the mean residual is small (open bins are full)
        // or if the item is large relative to capacity.
        score -= 40.0 * (1.0 - mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild global pressure: prefer using existing bins when mean residual is high.
    if bin_residual != bin_capacity {
        score -= 3.0 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early in the stream, slightly discourage fragmenting bins
    // (future items unknown); late in the stream, allow aggressive filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.08 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: penalize wasted space, quadratically to punish tiny dead space
    let mut score = post + 40.0 * post_norm * post_norm;

    // Smooth non-linear coupling: post_residual interacts with stream progress.
    // Late in the stream, waste is costlier -> amplify the post-residual penalty.
    let progress_coupling = 1.0 + 3.0 * progress * progress * (1.0 - post_norm);
    score *= progress_coupling;

    // Reward filling bins tightly (post near 0), smoothly via cubic falloff
    score -= 25.0 * (1.0 - post_norm).powi(3) * (1.0 + progress);

    // Coupling with item size: prefer bins that absorb large items well
    score -= 15.0 * item_norm * (1.0 - post_norm).powi(2);

    // Last-chance bin: strongly favor using it (avoid opening new bins)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - post_norm);
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_quality = 1.0 - diff / cap;
        if fit_quality > 0.0 {
            score -= 18.0 * fit_quality * fit_quality;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (smooth homogenization)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference for fewer open bins early on
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: keep it neutral-to-slightly-high unless post-residual logic dominates
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes mod 10.
    let r = post_residual;
    let class = r % 10;

    // Perfect fits (residual 0) are ideal.
    if r == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space that nothing (min size 1) can be lost on... but small
    // residuals (1..=9) are "harmonically dead" classes if next item can't use them.
    if r > 0 && r <= 9 {
        score += 40.0;
        // If lookahead item exactly matches the dead class, reward instead.
        if next_item_size == r {
            score -= 120.0;
        }
    }

    // Harmonic division thresholds: post_residual in "good" classes divisible by
    // common item sizes (10, 20, 25, 50) keep bins reusable.
    if r % 10 == 0 && r > 0 {
        score -= 15.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 10.0;
    }
    if r % 50 == 0 && r > 0 {
        score -= 10.0;
    }

    // Integer-division threshold: bins whose residual stays above half capacity
    // remain flexible; below quarter capacity they are near-dead.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if r >= half {
        score -= 20.0;
    } else if r < quarter {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == r {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= r {
        // Next item fits but leaves another residual: mild reward scaled by fit quality.
        let next_post = r - next_item_size;
        score -= 10.0 + (next_post as f64) * 0.2;
        if next_post % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > r {
        // Lookahead cannot use this bin's leftover: penalize dead class.
        score += 20.0 + (r as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer filling it rather than leaving it stranded.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Many fitting bins: keep tightest fit preference (post_residual already does this),
    // but add slight tie-break pressure proportional to bin count.
    if fitting_bins_count > 3 {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // and no bin leaves a harmonically useful residual.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 30.0 + 40.0 * (frac - 0.5);
        }
        // Avoid hoarding new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * (1.0 - progress);
        // Opening a new bin wastes the mean residual of existing bins.
        score += mean_residual * 0.3;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's an
    // outlier worth consolidating.
    let diff = mean_residual - r as f64;
    if diff > 15.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are nearly worthless; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Gaps below ~25 are rarely reusable by mid/large items.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    if post_residual > 0 {
        score -= 8.0 / (post_residual as f64).sqrt();
    } else {
        // Perfect fill is excellent.
        score -= 20.0;
    }

    // Pressure from open bin count: with many open bins, prefer filling existing
    // ones (penalize the new-bin candidate and discourage spreading).
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are open,
        // relaxed early in the stream when few bins exist.
        score += 5.0 + open_pressure * 1.2;
    } else {
        score -= 1.0 + 0.05 * open_pressure;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward keeping
    // that space; otherwise the gap is more likely dead space.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Mean residual coupling: if this bin's post-residual is far below the mean,
    // it is consolidating space well; slight reward.
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0).min(50.0) * 0.1;

    // Stream progression: late in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
