pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero).
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Penalize dead space that no future item can plausibly fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward if next item fits into the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot follow here: slight penalty, worse if gap is large
            score += 0.05 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin is badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        // open new bin if mean residual of open bins is small relative to item
        score += 60.0;
        score -= 50.0 * (1.0 - (item_size as f64 / 100.0)) * (mean_residual / 100.0);
        score -= 10.0 * (1.0 - progress);
        let _ = fragmentation;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, be conservative (favor tight fits more); late, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty per extra open bin to discourage bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic dead-space penalty, modulated by stream progress
    let mut score = x * (1.0 + 0.9 * x) * (1.0 + 0.5 * progress) * 100.0;

    // Smooth coupling: small post-residuals are valuable late in the stream
    let tight_fit = (-x * 6.0).exp();
    score -= tight_fit * (20.0 + 40.0 * progress);

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64 / cap;
        score -= (1.0 - slack_after_next) * (15.0 + 15.0 * progress);
    } else if next_item_size > 0 {
        score += 8.0 + 12.0 * progress;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when bin is far from the mean residual (keeps spread balanced)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: keep it slightly unattractive unless residuals are large
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small residue"
    // classes (0..=10, i.e. nearly perfect fills) get strong reward.
    let class = post_residual % 25;
    match class {
        0 => score -= 30.0,           // perfect harmonic fill
        1..=10 => score -= 12.0,      // near-perfect, dead space negligible
        11..=20 => score += 3.0,      // mediocre leftover
        _ => score += 8.0,            // awkward class 21..=24
    }

    // Reward tiny post_residual nonlinearly (waste minimization).
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item can fit into post_residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.05 * next_item_size as f64;
            // Harmonic bonus when next item's size shares a residue class with post_residual
            if next_item_size % 25 == class {
                score -= 6.0;
            }
        } else {
            // Next item won't fit: penalize leaving medium dead space.
            if post_residual > 10 && post_residual < next_item_size {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins are tight or item huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64 * 1.5;
        if item_size >= 60 || (tight && open_bins_count > 2) {
            score -= 8.0 + 10.0 * progress;
        } else {
            score += 25.0;
        }
    }

    // Mild preference for bins below mean residual (balance preservation).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // later are heavily penalized (proportionally to how "dead" they are).
    if post_residual > 0 {
        let dead_threshold = 10.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
        // Medium gaps that likely cannot fit a typical item (>= 10) are wasted.
        if post_residual < 10 {
            score += 25.0; // fully dead gap
        }
    } else {
        // Perfect fill: reward strongly.
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // new bins; concentrate fill.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        // or mean residual is still large (existing bins have room).
        score += 18.0 + open_pressure * 6.0 + (mean_residual / bin_capacity as f64) * 25.0;
        // Allow new bin late in stream if lookahead item won't fit leftovers anyway.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 5.0;
        }
    } else {
        // Reward using existing bins more when many are open.
        score -= open_pressure * 3.0;
        // Lookahead synergy: if next item fits the post residual, big reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 6.0; // leftover won't serve the next item
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (close them out rather than fragmenting large residuals).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Early vs late stream: early on, be more willing to open bins for
    // good structure; late, squeeze everything into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Penalize leaving dead space that likely cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item.
            let combo_slack = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - combo_slack / bin_capacity as f64);
        } else {
            // Dead space for the lookahead item: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins when open bins have plenty of usable space.
        score += 12.0 * pressure;
        // Slight time-varying bias: early on, allow opening bins more freely.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * (1.0 - t);
        // If the item fits snugly in a fresh bin, mild reward.
        score += 0.2 * (bin_capacity - item_size) as f64;
    }

    // Prefer bins that are already more filled than average (consolidation).
    let fill_delta = mean_residual - bin_residual as f64;
    score += 0.15 * fill_delta;

    // Mild preference for bins with larger residuals among many open bins.
    score += 0.05 * (open_bins_count as f64).ln() * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Quadratic penalty on dead space, amplified by stream progress.
    let x = pr / cap;
    score += 8.0 * x * x * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly over time.
    score -= 12.0 * (1.0 - x) * (1.0 - x) * progress;

    // Non-linear coupling: residual vs mean residual deviation.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev.abs();

    // Last-chance bin bonus (smooth via inverse fitting count).
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: penalize if next item cannot use the post residual.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr as f64 {
            score += 6.0 * (ns / cap) * (1.0 - progress);
        } else {
            score -= 4.0 * (ns / cap);
        }
    }

    // Mild penalty for many open bins, encouraging consolidation.
    score += (open_bins_count as f64).ln() * 1.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it partitions the capacity.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Dead-space penalty: residuals too small for the smallest item are worthless.
    if post < 10 {
        score += 60.0;
    } else if post < 20 {
        score += 25.0;
    }

    // Reward post-residuals that form "clean" harmonic fractions of capacity
    // (usable by many future item classes): near 1/4, 1/2, 3/4 of capacity.
    let targets = [quarter, bin_capacity / 2, 3 * quarter];
    let mut best_dist: u32 = u32::MAX;
    for t in targets.iter() {
        let d = if post >= *t { post - t } else { t - post };
        if d < best_dist { best_dist = d; }
    }
    if best_dist <= eighth {
        score -= (eighth - best_dist) as f64 * 1.5;
    } else {
        score += (best_dist.min(eighth * 3)) as f64 * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0);
            // Penalize if post residual is then nearly consumed leaving dead space
            if slack < 10 { score += 12.0; }
        } else {
            // Next item won't fit here; mildly penalize tight fits anyway
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 0.5;
        // But if the item is large, a fresh bin is fine (best-fit for big items).
        if item_size > bin_capacity / 2 {
            score -= 55.0;
        }
    }

    // Prefer bins whose residual is far below the mean (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.4;

    // Modulo-class tiebreak: prefer residuals that are multiples of small classes.
    if post % 10 == 0 { score -= 4.0; }
    if post % 5 == 0 { score -= 2.0; }

    // Late-stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Mid-range gaps (10..20) are only usable by small items; mild penalty.
    else if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins that can also accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that blocks the known next item (forced new bin).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (favor bins with small residual); when few bins, be picky.
    let pressure = open_bins_count as f64;
    score -= pressure * 0.8 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Prefer bins whose residual deviates below the mean (tighter bins first).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: make empty bins attractive only when the
    // current bin would leave a large awkward residual or no bin fits well.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: mildly worse than a good existing fit.
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 0.5;
        // If placing here would strand a tiny dead gap, new bin looks better.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheap; late, avoid sprawl.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 1.5;
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize if next item cannot fit into post_residual (dead space for the future)
        if post_residual < next_item_size {
            score += 40.0;
        }
    }

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Tight-fit preference: small item relative to residual is good
    score += (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.8;

    // New-bin candidate: penalize slightly so we prefer good fits into open bins,
    // but keep it competitive when fits are poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    // Late in stream: prefer filling existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    score -= 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6) * 10.0;

    // Penalize dead space that is too small to be useful later (items >= 1)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // If many bins can fit the item, mild penalty for using a scarce-fit bin wrongly
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item would fit in post-residual, mild reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }
    // If next item is large and this bin's post-residual is small, good (save big bins)
    if next_item_size > item_size && post_residual < next_item_size.min(10) {
        score += 3.0;
    }

    // Prefer filling bins with larger residuals when mean residual is high (fragmentation control)
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 1.5 * dev / bin_capacity as f64;
    } else {
        score += 1.0 * (-dev) / bin_capacity as f64;
    }

    // New-bin candidate handling: make opening a new bin costly unless current fits are terrible
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.8 + open_bins_count as f64;
        // If only this candidate fits, it must win
        if fitting_bins_count == 0 {
            score = -100.0;
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference to fill older bins (reduce open bin count pressure)
    score += 0.5 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);

    // Time-horizon modulation: early stream, be conservative with tight fits; later, pack aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer small post-residual (tight fit), with non-linear penalty
    let mut score = pr * (1.0 + 0.8 * norm_post * norm_post);

    // Polynomial coupling of post-residual with stream progress:
    // early on tolerate slack; later penalize residual more strongly
    let progress_coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 0.5 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Dead-space penalty: residuals too small for typical future items
    let dead = ((20.0 - pr).max(0.0) / 20.0).powi(2) * 12.0;
    score += dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // mild preference when few bins can fit
        score -= (fitting_bins_count as f64).recip() * 3.0;
    }

    // Lookahead: reward if next item fits the post-residual, penalize near-miss
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - ((pr - nxt) / cap).min(1.0));
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Discard fragmentation relative to mean residual across open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Slight preference for keeping number of open bins moderate
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: neutral-ish baseline with penalty so it's only chosen
    // when open bins fit poorly (high post_residual or dead space dominates)
    if bin_residual == bin_capacity {
        score = cap * (1.1 + 0.6 * progress) + 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let tight_bonus = 60.0 * (-post_residual as f64 / 12.0).exp();
    score -= tight_bonus;

    // Harmonic class of post_residual: residue classes mod 10, 25, 50.
    // Dead space that is a common denominator (10, 20, 25, 50) can still be
    // filled by typical small items; odd residues are near-useless.
    let pr = post_residual;
    let mut class_penalty = 0.0;
    if pr > 0 {
        if pr % 50 == 0 { class_penalty -= 25.0; }
        else if pr % 25 == 0 { class_penalty -= 15.0; }
        else if pr % 10 == 0 { class_penalty -= 10.0; }
        else if pr % 5 == 0 { class_penalty -= 3.0; }
        else { class_penalty += 12.0; } // awkward leftover
        // Tiny slivers are dead space.
        if pr < 10 && pr > 0 { class_penalty += 30.0; }
    }
    score += class_penalty;

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            // Next item fits here: reward proportional to how well it packs.
            score -= 20.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving this bin chosen.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer reusing
    // open bins unless the fit is poor. Give empty bins a mild penalty so a
    // decent existing fit wins, but a bad fit (large post_residual, odd class)
    // loses to it.
    if bin_residual == bin_capacity {
        score += 35.0 - 15.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Stream progression: early on, be more willing to open bins (diversity);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) - 10.0 * progress;

    // Prefer bins below mean residual (balancing keeps options open) only
    // mildly; overly full bins are already rewarded via tight_bonus.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residual values that are
    // too small to be useful (below the smallest plausible item size band).
    // A post gap of 1..=12 is nearly unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 13 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Favor tight fits: ratio of item to residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 10.0;

    // Open-bin pressure: penalize bins when many bins are already open,
    // pushing toward consolidation into existing bins rather than new ones.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // New-bin candidate: make opening a new bin moderately unattractive
    // unless existing bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Progress-aware dead-space weighting: later in the stream, dead space
    // matters more since less opportunity to recover it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 35.0;
    } else {
        score += fit_ratio * 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        score -= 25.0 - (chain_waste as f64) * 0.3;
    } else if next_item_size > 0 {
        // Penalize bins that leave dead space the next item cannot use.
        score += 12.0;
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bonus: if only this bin fits, avoid opening a new bin
    // unless the waste is severe.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: prefer it only when it enables a good future fit
    // or all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to plausibly hold future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly in the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual; penalize proportionally to wasted space
            score += 4.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Encourage consolidation when many bins are open
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * tightness;

    // Time horizon: later in stream, prefer filling existing bins over opening new ones
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 15.0 + 20.0 * progress;
        // but allow new bin if mean residual is very low (all bins nearly full)
        score -= 10.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    } else {
        score -= 3.0 * progress;
    }

    // Slight preference for bins below mean residual (balance preservation)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Smooth coupling with stream progress: tighten packing later in stream
    score += 20.0 * progress * x * x;

    // Penalize post-residual that fails to fit the lookahead item (smoothly)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) as f64;
        score += 0.8 * gap * (1.0 - progress * 0.5);
        // Reward when post-residual exactly accommodates next item
        let fit_bonus = (pr - (nx - pr).abs()).max(0.0);
        score -= 0.5 * fit_bonus / cap;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * (1.0 - x);
    }

    // Prefer bins with residual near mean (balanced packing), smooth term
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for many open bins to discourage bin sprawl
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: baseline score so it's chosen only when open bins score worse
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class 1: tiny dead space (< 1/8 of capacity) -> excellent, strong reward.
    if frac < 0.125 {
        score -= 25.0;
    }
    // Class 2: small-but-usable (1/8 .. 1/4) -> moderate reward.
    else if frac < 0.25 {
        score -= 10.0;
    }
    // Class 3: awkward middle (1/4 .. 1/2) -> mild penalty.
    else if frac < 0.5 {
        score += 5.0;
    }
    // Class 4: large leftover (>= 1/2) -> big penalty, wasteful placement.
    else {
        score += 20.0;
    }

    // Integer-division harmonic class on post_residual (bucket size 10).
    let bucket = post_residual / 10;
    let bucket_center = (bucket * 10 + 5) as f64;
    score += (bucket_center - pr).abs() * 0.05; // prefer residuals near bucket centers? mild
    score -= bucket as f64 * 0.3; // lower bucket (less leftover) slightly favored

    // Modulo coupling: how well does the leftover pair with the next item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item fits exactly into this bin's future residual: strong reward
            let tight = (post_residual - next_item_size) as f64;
            score -= 15.0 - tight.min(15.0) * 0.5;
            // modulo harmony: next item divides leftover cleanly
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize proportional to mismatch
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0) * 0.2;
        }
    } else {
        // last item: prefer filling as tightly as possible
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to capacity or many bins are open with little mean room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / cap;
        score += 35.0
            - item_size as f64 * 0.25
            - open_bins_count as f64 * 0.5
            - (1.0 - pressure) * 10.0
            - progress * 5.0;
        // very large items deserve their own bin
        if item_size as f64 > 0.75 * cap {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual is close to the item (perfect fit coupling).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.1;

    // Mild preference for keeping fewer open bins when mean residual is low.
    score += open_bins_count as f64 * 0.2 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Penalize medium dead space that next item likely cannot use.
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 4.0 + 0.05 * (next_item_size as f64 - post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item.
        score -= 2.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when item barely fits open bins
    // (i.e., would leave tiny dead space) or when open-bin residuals are small.
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64;
        score -= 3.0;
        if spread < 0.0 {
            score += (-spread) * 0.5;
        }
    }

    // Mild preference toward bins below mean residual (tighter bins first).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / 100.0).max(0.0);
        // Perfect chain: item then next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Post-residual can still hold next item: keep bin attractive.
        if post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Penalize small dead space that nothing can use (items >= 1, so any residual is usable,
    // but tiny residuals relative to typical item scale are still wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 70.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        let waste = bin_residual as f64 - item_size as f64;
        score += 40.0 + 0.8 * waste;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can chain the next item too
        }
    }

    // Late in the stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
