pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: reward tight fits via quadratic penalty on post_residual.
    let norm_post = post / cap;
    let mut score = 4.0 * norm_post * norm_post + norm_post;

    // Strong penalty for opening a new bin, decaying as stream progresses
    // (late in the stream, consolidation matters more, but early we allow growth).
    let new_bin_penalty = is_new_bin * (cap * (1.6 - 0.9 * progress));
    score += new_bin_penalty;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 0.5 * cap * (1.0 - progress);
    }

    // Smooth interaction: penalize leaving residual that no typical next item fits.
    let next = next_item_size as f64;
    if next > 0.0 {
        let waste = (post - next).max(0.0) / cap;
        score += 2.0 * waste * waste * (1.0 - progress);
        // Reward if next item exactly fits the post residual.
        let snug = (next - post).abs() / cap;
        score -= 1.5 * (1.0 - snug).max(0.0) * (1.0 - progress) * (1.0 - is_new_bin);
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    let dev = (mean_residual - post) / cap;
    score -= 0.8 * dev;

    // Mild pressure to consolidate as open bins grow.
    score += 0.05 * open_bins_count as f64 * (1.0 - is_new_bin) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "dead space"
    // (too small for the smallest plausible item) are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 40.0;
    } else {
        // Reward post-residuals that fall into "harmonic" classes: multiples
        // of common item sizes (harmonic classes of capacity 100).
        let harmonic_bonus = if post_residual % 50 == 0 {
            25.0
        } else if post_residual % 25 == 0 {
            18.0
        } else if post_residual % 10 == 0 {
            12.0
        } else if post_residual % 5 == 0 {
            6.0
        } else {
            0.0
        };
        score -= harmonic_bonus;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (perfect harmonic pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Integer-division class of the slack: exact multiples are good.
            if slack as u32 % 10 == 0 {
                score -= 20.0;
            }
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty scaled by how much it overflows.
            let overflow = (next_item_size - post_residual) as f64;
            score += 5.0 * (overflow / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance logic: if this is the only bin that fits the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when open bins exist with reasonable room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - progress);
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 20.0;
        }
    }

    // Prefer tighter fits overall: reward small post_residual relative to capacity.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Waste fraction penalty: residual that is a large non-harmonic fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.5 && (post_residual % 10 != 0) {
        score += 8.0 * frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

