    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize proportionally to overflow
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins
    // would leave bad residuals, and when many bins are already open.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + open_bins_count as f64 * 0.5 - mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big-follows-big stream: fresh bin helps
        }
    }

    // Late in stream, tighten packing (prefer tight fills).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Small tie-break toward bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(0.0) * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 35 {
        score += 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage unless open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0;
        let poor_fit = if post_residual > 40 { 10.0 } else { 0.0 };
        score += 30.0 - pressure - poor_fit;
    }

    // Open-bin pressure: mild penalty for proliferating bins.
    score += (open_bins_count as f64) * 0.3;

    // Progress: tighten packing later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins where the next item fits snugly into post_residual
    if next_item_size > 0 {
        let lookahead_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits: reward tight coupling
            score -= 120.0 * (1.0 - lookahead_diff / (bin_capacity as f64));
            if lookahead_diff == 0.0 {
                score -= 250.0;
            }
        } else {
            // next item would not fit here: mild penalty proportional to dead space
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize creating dead space far below the typical next-item size
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins)
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else {
        // More fitting bins -> slight penalty to encourage spreading across tight fits
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: penalize opening a new bin unless current alternatives are poor
    if bin_residual == bin_capacity {
        score += 300.0;
        // But if lookahead suggests a big next item, opening fresh may be reasonable
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 100.0;
        }
    }

    // Early in the stream, slightly discourage hoarding many bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 5 && progress < 0.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful later.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 18.0; // tiny useless sliver
        } else if dead < 20.0 {
            score += 6.0;
        }
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = 1.0 - (next_item_size as f64 / post_residual.max(1) as f64).abs();
        score -= 20.0 + 10.0 * chain;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // next item would have fit before this placement but not after: penalize.
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // with alternatives, mild penalty to encourage exploring other bins
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: many open bins with large mean residual -> discourage opening new bins,
    // encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score -= crowd.min(8.0);

    // Dynamic time horizon: late in the stream, tighten packing aggressively.
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate handling: empty bin gets a base cost that scales with
    // how much residual capacity already exists across open bins.
    if bin_residual == bin_capacity {
        let surplus = mean_residual - item_size as f64;
        if surplus > 0.0 {
            score += 15.0 + 0.3 * surplus;
        } else {
            score -= 8.0; // nothing else fits well; fresh bin is fine
        }
    }

    // Mild preference for bins whose residual is close to mean (balanced packing).
    score += 0.08 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: quadratic in post_residual (dead space penalized super-linearly)
    let mut score = post * post / cap;

    // Smooth interaction: dead space matters more as the stream progresses
    score *= 0.5 + progress;

    // Reward tight fits with a smooth saturating term
    let tightness = item / bin_residual.max(1) as f64;
    score -= tightness * tightness * 20.0;

    // Lookahead: penalize leaving a residual that barely misses the next item
    if next > 0.0 {
        let gap = post - next;
        if gap < 0.0 {
            // next item won't fit here: mild penalty proportional to how far off
            score += (-gap).powf(1.3) * 0.3;
        } else {
            // next item fits: reward smooth in how well it fills the remainder
            let fill = next / post.max(1.0);
            score -= fill * fill * 15.0;
        }
    }

    // Last-chance bonus: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let waste = mean_residual / cap;
        score += 30.0 - 20.0 * waste * waste - 10.0 * progress;
        // extra penalty if other bins could actually fit the item
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild penalty for fragmenting large residuals into tiny unusable slivers
    if post > 0.0 && post < item.min(20.0) as f64 {
        score += (20.0 - post) * 0.5;
    }

    // Slight diversity pressure: avoid piling onto the most-filled average
    score += (post - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Post-residual harmonic classes: bins with residual in "dead zones" get penalized
    let class = post_residual % 10;
    if class == 0 {
        score -= 20.0; // round residuals are more reusable
    } else if class <= 3 {
        score += 5.0; // small odd leftover is semi-dead
    }

    // Integer division thresholds: residual >= half capacity is valuable
    if post_residual * 2 >= bin_capacity {
        score -= 15.0;
    } else if post_residual * 4 >= bin_capacity {
        score -= 5.0;
    } else {
        score += 10.0; // small residual: dead space risk
    }

    // Coupling with next item: reward if next item fits exactly or well
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_waste = post_residual - next_item_size;
        if next_waste == 0 {
            score -= 200.0;
        } else {
            score -= (next_waste as f64).recip() * 30.0;
        }
    } else if next_item_size > post_residual {
        score += 8.0; // next item won't fit here
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when open bins have large mean residual
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_penalty = mean_residual * 0.8 + open_bins_count as f64 * 3.0;
        score += 25.0 + waste_penalty * (0.5 + 0.5 * progress);
        // But allow new bin if this item is huge and mean residual can't hold it comfortably
        if item_size as f64 > mean_residual + 5.0 && fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild pressure to consolidate when many bins open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = if bin_capacity > 0 { bin_capacity as f64 } else { 100.0 };
    let item_f = item_size as f64;
    let residual_f = bin_residual as f64;
    let post_f = post_residual as f64;
    let next_f = next_item_size as f64;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let open_f = open_bins_count as f64;
    let fits_f = fitting_bins_count as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let log_open = (1.0 + open_f).ln();
    let mean_ratio = if mean_residual.is_finite() {
        (mean_residual / cap_f).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let fill = if residual_f > 0.0 {
        (item_f / residual_f).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let mut score = post_f;

    // Reward tight placement inside the selected bin.
    score -= 18.0 * fill;

    // Strong reward for perfect/near-perfect closure.
    if post_f == 0.0 {
        score -= 25.0;
    } else if post_f <= 2.0 {
        score -= 6.0;
    }

    // Strict dead-space avoidance: small nonzero gaps are penalized heavily,
    // especially when they cannot absorb the lookahead item.
    let low_useful = (0.12 * cap_f).max(1.0);
    if post_f > 0.0 && post_f < low_useful && next_f > 0.0 {
        let severity = 1.0 - post_f / low_useful;
        let mut dead_penalty = 22.0 + 55.0 * severity;

        if post_f < next_f {
            dead_penalty += 0.45 * (next_f - post_f).min(cap_f);

            // If this bin could have been saved for the next item, burning it now is worse.
            if !is_new_bin && residual_f >= next_f {
                dead_penalty += 18.0;
            }
        } else {
            // The small gap is at least immediately usable by the next item.
            dead_penalty *= 0.35;
        }

        score += dead_penalty;
    } else if post_f > 0.0 && next_f > 0.0 && post_f < next_f {
        let mut blocking_penalty = 0.10 * (next_f - post_f);

        if !is_new_bin && residual_f >= next_f {
            blocking_penalty += 10.0;
        }

        score += blocking_penalty;
    }

    // Mild reward when this bin can also accommodate the lookahead item.
    if next_f > 0.0 && post_f >= next_f {
        score -= 4.0;
    }

    if !is_new_bin {
        // Last usable open bin: strongly prefer it unless the dead-space penalty is severe.
        if fitting_bins_count == 1 {
            score -= 14.0 + 8.0 * (1.0 - progress);
        }

        // Pressure toward consolidating into already-open bins.
        score -= 2.0 + 2.0 * log_open + 5.0 * mean_ratio;
    } else {
        let mut new_bin_pressure = 10.0 * log_open + 12.0 * mean_ratio + 6.0 * progress;

        if fitting_bins_count == 0 {
            // No open bin can fit the item; opening a new bin is necessary.
            new_bin_pressure -= 45.0;
        } else {
            // More fitting alternatives makes opening another bin less attractive.
            new_bin_pressure += 3.0 * (fits_f - 1.0).max(0.0);

            // Never open a needless new bin on the final item.
            if next_f == 0.0 {
                new_bin_pressure += 100.0;
            }
        }

        // A fresh bin that can also take the next item is more acceptable.
        if next_f > 0.0 && post_f >= next_f {
            new_bin_pressure -= 5.0;
        }

        // Large items are the main case where opening a fresh bin can be justified.
        new_bin_pressure -= 0.08 * item_f;

        score += new_bin_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // ideal: bin becomes exactly full after two items
        } else if post_residual >= next_item_size {
            // Next item fits; reward small remaining gap after the pair.
            let gap_after_pair = post_residual - next_item_size;
            score -= 3.0 * (1.0 - gap_after_pair as f64 / 100.0);
            // Extra bonus for very tight two-item packing.
            if gap_after_pair <= 5 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; penalize leaving dead space that
            // is smaller than the likely next demand.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize creating tiny unusable slivers relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Prefer bins with residual below the mean (tighter bins first),
    // keeping mean-residual-aware balancing.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward residual that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (post_residual as f64 / (post_residual as f64 + next_item_size as f64));
        } else {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Prefer bins below mean residual (consolidate emptier space into fuller bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild preference to fill already-open bins as stream progresses,
    // but allow opening new bins early or when open bins are crowded.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += progress * 5.0 + crowd * 0.5;

    // New-bin candidate: neutral-ish score so it wins only on poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress * x + 0.6 * (1.0 - progress) * x * x);

    // Penalize residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if x < nx {
            score += (nx - x) * (1.0 + 0.5 * progress);
        } else {
            score -= 0.15 * nx * (1.0 - progress);
        }
    }

    // Reward near-perfect fits
    score -= 0.5 * (1.0 - x) * (1.0 - x);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 0.3;
    }

    // Mild preference for using existing bins vs opening new ones
    if bin_residual == bin_capacity {
        score += 0.25 + 0.25 * progress;
    }

    score += 0.1 * (mean_residual / cap - x).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "useful" residue classes (multiples of 10, or large enough to host
    // typical small items) are favored; awkward residues are penalized.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else {
        // Class the residual by integer division into capacity-fraction bands.
        let band = pr / 10; // 0..=10 harmonic class
        match band {
            0 => score += 60.0,                 // 1..9: dead space, nearly useless
            1 => score += 25.0,                 // 10..19: only tiny items fit
            2 | 3 => score += 5.0,              // 20..39: mid-small usable
            4 | 5 | 6 => score -= 5.0,          // 40..69: broadly usable
            _ => score -= 10.0,                 // 70..99: still very flexible
        }
        // Exact decade residuals are "harmonic" and pair well with streams
        // whose items are often multiples of 10.
        if pr % 10 == 0 {
            score -= 8.0;
        } else {
            score += (pr % 10) as f64 * 0.5;
        }
    }

    // Lookahead: reward bins that can also host the next item (k=2 lookahead).
    if next_item_size > 0 {
        if pr >= next_item_size {
            // This bin remains usable for the next item: strong reward,
            // scaled by how tightly the next item will fit.
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 + slack * 0.2;
        } else {
            // Next item won't fit here; penalize proportionally to how
            // much of the next item is "wasted" on this bin's future.
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin (unless post_residual would be awful).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive
    // only when current open bins are fragmented (high mean residual spread)
    // or the fit here is poor.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Baseline: empty bin leaves residual = capacity - item_size.
        // Compare against mean residual of open bins: if open bins are
        // already roomy on average, prefer them; if fragmented, new bin wins.
        score -= 20.0;
        if mean_residual > 50.0 {
            score += 35.0; // open bins are roomy; don't open another
        } else if mean_residual < 25.0 {
            score -= 15.0; // open bins are tight; a fresh bin helps
        }
        // Early in the stream, opening bins is cheap and builds flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score -= 12.0 * (1.0 - progress * 3.0);
        }
    }

    // Mild preference for keeping the number of open bins low.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to fit any
    // plausible future item (min item size 1, but practically small gaps
    // under ~10 are dead weight) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium unusable gaps: dead space if next item cannot use them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small waste relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item would leave a large, useful residual or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // More attractive when many bins are open (pressure to distribute).
        score -= open_bins_count as f64 * 0.5;
        // Attractive if placing in existing bins would create tiny dead gaps
        // (proxy: item almost exactly matches nothing).
        if post_residual >= 10 {
            score -= 8.0;
        }
    }

    // Lookahead: if this placement leaves room for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Late in the stream, consolidate: tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but reward tighter couplings more.
            score -= 100.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit: penalize leaving small dead space.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 60.0 * (10.0 - dead);
            }
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 200.0;
    }

    // Relative to mean residual: bins with less residual than average are scarcer;
    // prefer using them when the fit is decent.
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New empty bin candidate: penalize unless it's genuinely better
    // (e.g., many open bins and current fit is poor).
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative: must open new bin
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * progress; // slightly more willing to open bins early
    }

    // Mild preference for compacting many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual non-linearly.
    score -= 60.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Strong last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let leftover = post_residual as f64 - nxt;
            score -= 30.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 8.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Prefer bins with residual close to the item (perfect nesting) beyond raw post_residual.
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * gap * gap;

    // Global state: when many bins are open, discourage spreading; favor consolidation.
    let openness = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 6.0 * openness;

    // Mean residual coupling: if this bin is much below mean residual, it's "tighter" — reward it.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be conservative about opening new bins; late, prefer filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, soften late; also penalize if other bins fit.
        score += 18.0 * (1.0 - progress) + 10.0 * (fitting_bins_count.max(1) as f64);
        // If next item is large, opening a fresh bin may be wise.
        if next_item_size >= 70 {
            score -= 12.0;
        }
    } else {
        // Late stream: reward using existing bins more aggressively.
        score -= 10.0 * progress;
    }

    // Dead-space guard: residual too small for any future item (min size 1) is fine, but
    // residuals just above small items are valuable — keep moderate penalty for mid-range waste.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-perfect packing
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer small post_residual, with non-linear polynomial shaping.
    let mut score = pr
        - (pr / cap) * (cap - pr) * 0.6          // concave reward for tight fits (peaks mid-range)
        + (pr * pr) / cap * 0.35;                // convex penalty for large leftover dead space

    // Smooth stream-progress coupling: early on tolerate slack; late, squeeze bins hard.
    let late = progress * progress;
    score += late * pr * 0.8;
    score -= late * (cap - pr) * 0.25;

    // Coupling with mean residual: penalize bins far from the fleet mean (keeps residuals uniform).
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: only bin that fits -> strong reward (smooth, scaled by progress).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits snugly into post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let fits = if pr >= nx { 1.0 } else { 0.0 };
        score -= fits * (cap - gap) * 0.12 * (1.0 - 0.5 * progress);
        // penalize post_residual that is just barely unusable for the next item
        score += (1.0 - fits) * (nx - pr).min(20.0) as f64 * 0.3;
    }

    // New-bin candidate: mild penalty so it only wins when open bins are genuinely bad.
    if is_new_bin {
        score += 8.0 + 12.0 * (1.0 - progress) - 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: dead space in low classes is worse.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize small unusable residuals (below smallest plausible item / 2).
    let dead_zone = (bin_capacity / 4) as f64;
    if pr < dead_zone {
        score += 12.0 * (dead_zone - pr) / dead_zone;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // Harmonic (modular) classes on post_residual: multiples of capacity quarters
    // are "friendly" residuals that future items can fill exactly.
    let q = bin_capacity / 4;
    if post_residual % q == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does the residual exactly accommodate the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            let leftover = post_residual - next_item_size as f64;
            score -= 6.0 * (1.0 - leftover / cap_f);
        } else {
            // Next item cannot follow here: mild penalty scaled by waste.
            score += 4.0 * (next_item_size as f64 - pr) / cap_f;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        // Base aversion to opening new bins, relaxed as stream progresses
        // and open bins fragment.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 20.0 - 10.0 * progress;
        // If the item is large relative to capacity, a fresh bin is safer.
        if item_size as f64 > 0.6 * cap_f {
            nb -= 8.0;
        }
        // If many bins are open with small mean residual, fragmentation is high.
        if mean_residual < 0.25 * cap_f && open_bins_count > 2 {
            nb -= 6.0;
        }
        score += nb;
    }

    // Tie-break: prefer bins with residual closest to item (tight fit) via
    // harmonic distance on integer division of residual by item size.
    if item_size > 0 && bin_residual >= item_size {
        let k = bin_residual / item_size;
        score -= 2.0 / (k as f64 + 1.0);
    }

    // Slight preference for keeping mean residual balanced.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below the minimum item size is wasted forever
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 15.0; // small-but-reusable gap is actually a good tight fit
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tightness relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins / encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in the stream.
        score += 25.0 + 3.0 * open_bins_count as f64 + 40.0 * progress;
    } else {
        // Reward using existing bins, scaled by open-bin count pressure.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 35.0;
        } else if next_item_size as u32 > post_residual {
            // Next item won't fit here; slight penalty for leaving a gap it could have used.
            if next_item_size <= bin_residual && next_item_size > item_size {
                score += 10.0;
            }
        }
    }

    // Prefer bins below mean residual (consolidating space).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: exact-fit reward (waste minimization)
    let residual = bin_residual as f64;
    score -= 30.0 * (1.0 - (post_residual as f64 / residual)).powi(3);

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (-gap / 20.0).exp();
    }
    // Penalize leaving a residual too small for the next item (dead space)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / 100.0);
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score += 0.5 * (residual - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: encourage consolidation onto tighter bins
    if open_bins_count > 4 {
        score += 0.3 * post_residual as f64 * (open_bins_count as f64).ln();
    }

    // Early stream: allow new bins more freely; late stream: pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (waste minimization core).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Penalize new-bin candidate unless existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: prefer using open bins when reasonable.
        score += 25.0;
        // If only this bin fits, opening a new bin is natural (item must go somewhere).
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in stream, consolidating matters more: discourage new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If many open bins already, discourage proliferation.
        score += (open_bins_count as f64).ln().max(0.0) * 4.0;
        // Large items into fresh bins are fine (better long-term residual).
        score -= (item_size as f64 / 100.0) * 12.0;
    } else {
        // Reward using bins that would otherwise leave awkward dead space.
        if post_residual > 0 && post_residual < 10 {
            score -= 15.0; // near-perfect fill
        }
        // Penalize leaving residuals that are hard to reuse (small odd gaps).
        if post_residual > 0 && post_residual < item_size / 2 {
            score += 6.0;
        }
        // Last-chance bin: if this is the only fitting bin, favor it strongly
        // to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Lookahead: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 {
            if post_residual as i64 - next_item_size as i64 == 0 {
                score -= 25.0;
            } else if next_item_size as u32 <= post_residual {
                score -= 8.0;
            } else {
                // Next item won't fit here; slight penalty for blocking.
                score += 3.0;
            }
        }
        // Prefer bins with residual close to the mean (keep balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Global pressure: when many bins are open, favor consolidation (lower post_residual already does).
    let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
    score += scarcity * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual, with non-linear squashing.
    let tightness = (post / cap).powf(1.6); // convex in wasted space
    let mut score = 40.0 * tightness;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (future items can fill); late, waste is costly.
    let progress_coupling = 1.0 + 2.5 * progress * progress;
    score += 60.0 * tightness * progress_coupling;

    // Reward using a bin whose residual closely matches the item (smooth kernel).
    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 30.0 * (fit_ratio * std::f64::consts::PI).sin().abs();

    // Penalize leaving post_residual in the "unusable dead zone" smoothly:
    // dead space grows quadratically when post_residual is far below typical item sizes.
    let dead = ((cap * 0.2 - post) / cap).max(0.0);
    score += 50.0 * dead * dead * (1.0 - progress);

    // Mean residual coupling: prefer bins below the mean residual (fill emptier bins),
    // smoothly interpolated.
    let mean_gap = (mean_residual - bin_residual as f64) / cap;
    score += 10.0 * mean_gap;

    // Last-chance bin: strong smooth bonus when this is the only fitting bin.
    if fitting_bins_count <= 1 {
        score -= 35.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (smooth).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let next_fit = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 45.0 * next_fit.max(0.0);
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    // Opening a new bin is attractive only for large items or when no good fit exists.
    if (bin_residual as f64 - cap).abs() < 1e-9 {
        let large_item_bonus = (item / cap).powf(2.0);
        let poor_alternatives = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score -= 25.0 * large_item_bonus + 20.0 * poor_alternatives * (0.5 + progress);
    }

    // Mild penalty for bin sprawl (many open bins) to encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quartile bands
    let q = bin_capacity / 4;
    let class = post_residual / q; // 0..4 harmonic class
    match class {
        0 => score -= 12.0,                    // near-perfect fit: tiny dead space
        1 => score -= 4.0,                     // still very usable
        2 => { score += 2.0; }                 // half-full leftover: mediocre
        3 => { score += 8.0; }                 // large dead space risk
        _ => { score += 1.0; }                 // empty bin candidate handled below
    }

    // Exact-fill reward via integer division test
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic pairing: can next item land exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size < post_residual {
            let nxt_class = next_item_size / q;
            // reward chains where the leftover stays in a good harmonic class
            let post_class_after = (post_residual - next_item_size) / q;
            score -= (4 - post_class_after.min(4)) as f64 * 3.0;
            if post_residual - next_item_size <= q {
                score -= 6.0;
            }
        } else {
            // next item cannot fit here; leftover is final dead space
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 10.0;
        if post_residual > 0 && post_residual < q {
            score -= 5.0; // fresh bin with tiny item is fine
        }
        // discourage new bins when an open bin has a decent fit
        if fitting_bins_count > 0 && post_residual >= bin_capacity as u32 - item_size {
            score += 15.0;
        }
    }

    // Waste-rate coupling with mean residual across open bins
    let waste = (post_residual as f64) / cap;
    score += waste * waste * 20.0;

    // Stream progression: tighten standards late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.05 * progress;

    // Prefer filling bins with large residuals when many bins are open
    if bin_residual > mean_residual as u32 + q {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps below the minimum item size (1..=10)
    // are pure waste; gaps 11..=20 are risky. Penalize sharply.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 18.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score += 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open,
    // encourage using existing bins; but keep some openness late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (1.0 - progress);

    // Dead-space coupling with mean residual: penalize adding to bins that are
    // already fragmented (high mean residual means poor packing so far).
    score += 0.15 * mean_residual;

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily;
    // if post_residual is smaller than next item but nonzero, penalize (dead space).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over
    // opening a new bin unless the resulting dead space is severe.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mildly penalize opening a new bin when it wastes capacity,
    // but allow it if all existing bins would create unusable gaps (handled above).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward bins closed by this placement.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize leftover after the next placement (dead space chain)
            let second_left = post_residual - next_item_size;
            score += second_left as f64 * 0.6;
            // small reward for keeping chain alive
            score -= 8.0;
        } else {
            // next item does NOT fit here: penalize bins that leave medium residuals
            // that block the next item, scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += miss.min(20.0) * 0.8;
        }
    } else {
        // Last item: closing the bin is all that matters.
        score += post_residual as f64 * 0.3;
    }

    // Compare residual against the mean across open bins:
    // prefer bins already below-mean residual (tighter bins get filled first).
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make empty bins attractive only when the item is large
    // or few bins fit the item elsewhere; otherwise keep them mildly unattractive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (fitting_bins_count as f64).recip();
        let large_item_bonus = if item_size > bin_capacity / 2 { 12.0 } else { 0.0 };
        score += 10.0 - pressure * 18.0 - large_item_bonus - progress * 4.0;
    }

    // Prefer filling bins that are already quite full (small residual before placement).
    score += (bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here; mild penalty for wasting space.
        score += 5.0;
    }

    // Time horizon: early in stream, be more conservative (prefer new bins
    // less); late in stream, fill existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global pressure: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= 3.0 * pressure.ln().max(0.0);

    // New-bin candidate: penalize unless item is large relative to capacity
    // or open bins are crowded (mean residual low).
    if bin_residual == bin_capacity {
        let crowded = mean_residual < (bin_capacity as f64 * 0.25);
        if item_size >= 60 || crowded {
            score -= 20.0;
        } else {
            score += 30.0 + 10.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Prefer bins whose residual is close to item_size (perfect-ish fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: raw post-residual, damped by progress (late stream: residuals matter more)
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Smooth non-linear penalty on wasted space, stronger late in stream
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits with smooth cubic falloff
    score -= 30.0 * (1.0 - norm_pr).powi(3);

    // Coupling with mean residual: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Lookahead: penalize if next item cannot use the post-residual (smooth)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (ns - pr).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Bonus if next item fits exactly-ish into post-residual
        let fit_gap = (ns - pr).abs() / cap;
        score -= 20.0 * (1.0 - fit_gap.min(1.0)).powi(2);
    }

    // Last-chance bin: strong reward to use it rather than open new
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    }

    // Mild penalty when many bins open (encourage consolidation early)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // New-bin candidate: penalize opening a bin when good fits exist, relax late
    if bin_residual == bin_capacity {
        score += 18.0 - 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal wasted space, with a non-linear push so that
    // very small post-residuals (dead space) are strongly favored.
    let pr = post_residual as f64;
    score = pr * pr / (bin_capacity as f64) + pr * 0.5;

    // Lookahead (k=2): reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item: penalize dead space, worse when tiny
        score += 8.0 * (1.0 - pr / (bin_capacity as f64));
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Harmonic class logic: classify post_residual into capacity fractions.
    // Residuals that are "harmonically clean" (divisible into common item
    // sizes) are more reusable; reward them mildly.
    let cap = bin_capacity;
    if post_residual > 0 {
        let mut usable = 0u32;
        for d in [10u32, 20, 25, 50].iter() {
            if post_residual >= *d && post_residual % d == 0 { usable += 1; }
        }
        score -= 3.0 * usable as f64;
        // Penalize awkward residues (not divisible by 5/10) - hard to fill later
        if post_residual % 5 != 0 { score += 4.0; }
    } else {
        // Perfectly closed bin: excellent
        score -= 30.0;
    }

    // New-bin candidate handling: the empty bin should only win when no
    // open bin offers a decent fit. Give it a moderate baseline score.
    if bin_residual == bin_capacity {
        // Neutral-ish: beats only badly fitting open bins.
        // Scale with stream progress: later in stream, slightly more willing
        // to open new bins to keep tight residuals available.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 18.0 + 10.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 { score -= 6.0; }
        // Many open bins with slack: less eager to open another.
        if mean_residual > 25.0 { score += 8.0; }
    } else {
        // Prefer reusing bins that are already fairly full (small residual
        // relative to capacity), a best-fit-with-lookahead flavor.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (tighter bins absorb the item).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: favor filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // next item fits too: penalize leftover after the pair
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.5;
            if after_next < 10 {
                score -= 100.0;
            }
        } else {
            // next item does NOT fit in this bin's leftover: dead space penalty
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare post-residual against mean residual of open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0;
        // especially if some open bin would leave a small residual
        if post_residual as f64 > mean_residual {
            score += 100.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 200.0;
    }

    // Mild penalty for large leftovers that few items could use
    if post_residual > 0 && post_residual < 20 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly reward near-perfect fits (non-linear, saturating bonus).
    score -= 12.0 * (-post / 10.0).exp();

    // Lookahead coupling: if the next item can also fit into the leftover
    // space, this placement chains nicely; reward proportionally.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 4.0 + 0.15 * nxt;
        } else {
            // Dead space relative to the upcoming item is partially wasted.
            score += 0.08 * (nxt - post);
        }
    }

    // Unusable sliver penalty: tiny residuals below the minimum item size
    // are pure waste.
    if post_residual > 0 && post_residual < 5 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only open bin that fits the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: bias against opening a fresh bin, growing with the
    // number of already-open bins (favor consolidation).
    if bin_residual == bin_capacity {
        score += 7.0 + 0.15 * open_bins_count as f64;
        // But opening a new bin is more reasonable for very large items
        // that would leave existing bins with awkward leftovers.
        score -= 0.05 * item_size as f64;
    }

    // Mild time-horizon modulation: late in the stream, bins with larger
    // mean residual become slightly more attractive targets (use up slack).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.5 * t * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post-residual, with non-linear (quadratic + sqrt) coupling
    let mut score = post * (1.0 + 0.8 * (post / cap)) - 6.0 * (cap / (post + 1.0)).sqrt();

    // Smooth stream-progress interaction: tighten packing as stream advances
    score *= 1.0 + 0.5 * progress * (post / cap);

    // Reward tight fits more strongly later in the stream
    score -= 12.0 * progress * (1.0 - post / cap).powi(3);

    // Last-chance bin: strong reward, decaying with progress smoothness
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Penalize leaving residual that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 3.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap * (1.0 + progress);
        }
    }

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (post - mean_residual).abs();

    // New-bin candidate: mildly attractive early, penalized when open bins are tight fits
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        score = cap * (0.9 + 0.6 * progress) - 20.0 * scarcity;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: tiny unusable slivers are wasted capacity
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Harmonic classes of post_residual (mod 10): decile structure
    let class = post_residual % 10;
    score += match class {
        0 => -4.0,          // round residual, versatile for future items
        1..=4 => 2.5,       // awkward small classes
        5 => 0.0,           // half-capacity class, moderately reusable
        6..=9 => 1.0,       // large-ish residual, still usable
    };

    // Integer-division threshold on post_residual quarters
    let quarter = post_residual / 25;
    score += match quarter {
        0 => 5.0,   // < 25 residual: nearly dead bin
        1 => 0.0,
        2 => -1.0,
        _ => -2.0,  // roomy bin
    };

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // Lookahead (k=2): reward if the next item fits in the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 7.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0; // next item won't fit here; leftover likely wasted
        }
        // Harmonic coupling: next item size mod 10 vs post_residual mod 10
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    // New-bin candidate: penalize mildly so it only wins when all open bins are bad
    if is_new_bin {
        score += 14.0;
    }

    // Consolidation pressure: prefer tighter bins early, relax late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.04 * (1.0 - progress);

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are pure loss; residuals below a usable threshold
    // (e.g. < 10, the minimum plausible item) are heavily penalized.
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space for typical streams: severe penalty.
        score += 45.0 - (post_residual as f64);
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate handling: an empty bin (residual == capacity) gets a
    // mild baseline penalty so it is only chosen when existing bins fit badly.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (creates a perfect future fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item (minimizes fragmentation across the fleet).
    let diff = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize wasting space that could matter.
            score += 40.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is already below the mean (consolidate fullness).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 300.0 + 0.3 * open_bins_count as f64;
        // If this is the last item, a new bin is fine.
        if next_item_size == 0 && step_index + 1 == total_items {
            score -= 400.0;
        }
    }

    // Mild progression bias: later in the stream, tighten bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * progress * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 40 {
        // moderately useful space; small bonus for keeping it
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins attractive only when existing
    // bins are fragmented or nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize new bins generally, less so when open bins are fragmented
        let new_bin_penalty = 60.0 - 25.0 * fragmentation;
        // late in stream, prefer filling existing bins even more
        score += new_bin_penalty * (0.5 + 0.5 * (1.0 - progress));
        // if no open bin fits (fitting_bins_count==0 among open), new bin is required
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global state: many open bins with low mean residual -> prefer packing into
    // existing bins to consolidate.
    if open_bins_count > 4 {
        score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    // Mild preference for bins below mean residual (balancing residuals).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be picky (prefer near-perfect fits); later, just fill.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += (pr / cap).powi(2) * 30.0 * (0.5 + 0.5 * p2);
    score -= (pr / cap).powi(3) * 20.0 * (1.0 - p3);

    // Penalize dead space that nothing can use later.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.5 + 2.0 * p2);
        } else {
            score -= (pr - nxt) * 0.5;
        }
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 10.0;

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: discourage unless residuals are large/wasted.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + mean_residual * 0.1;
    }

    // Mild penalty for spreading across many bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space is worst when it falls
    // into a "useless" residue class (too small for typical items).
    let pr = post_residual;
    if pr > 0 {
        // Class A: residue 1..9 -> nearly dead space, heavy penalty.
        if pr < 10 {
            score += 40.0;
        }
        // Class B: 10..19 -> only tiny items fit; moderate penalty.
        else if pr < 20 {
            score += 15.0;
        }
        // Class C: exact harmonic subdivisions of capacity are reusable.
        let harmonics: [u32; 6] = [50, 33, 25, 20, 10, 34];
        for h in harmonics.iter() {
            if pr % h == 0 && pr >= *h {
                score -= 8.0;
                break;
            }
        }
    } else {
        // Perfect fill: strongest reward.
        score -= 60.0;
    }

    // Coupling with lookahead: post_residual exactly matches next item -> big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // Exact match is ideal.
        if next_item_size == pr {
            score -= 25.0;
        }
        // Post residual leaves a harmonic remainder for the item after next.
        if (pr - next_item_size) < 10 && (pr - next_item_size) > 0 {
            score += 6.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // This bin's leftover can't host the next item; slight penalty if leftover is small.
        if pr < 20 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer existing bins unless this bin is a poor fit.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if item leaves a large, harmonic residual.
        score = (bin_capacity - item_size) as f64;
        if (bin_capacity - item_size) >= 50 {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Tight fits are good: reward small post residual relative to capacity fraction.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Waste relative to mean residual: penalize creating outliers of dead space.
    if post_residual as f64 > mean_residual + 20.0 {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small but potentially usable gap: moderate penalty, scaled by
        // how "awkward" the gap is relative to typical item sizes.
        score += 12.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward tight fits (post_residual near 0 but not dead space).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading out,
    // favor filling existing bins; few open bins -> new bins are cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure term so that with many
        // open bins we only open a new bin when the fit elsewhere is bad.
        score += 25.0 + 8.0 * pressure;
    } else {
        score -= 3.0 * pressure;
    }

    // Prefer bins whose residual is close to the mean residual (keeps
    // bin states homogeneous, easier to pack future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if the next item would fit exactly into the post_residual,
    // this placement is excellent -> reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: subtract a large bonus so this bin wins.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize proximity mismatch scaled by lookahead gap.
            score += lookahead_gap * 0.35;
            // Slight extra penalty if post-residual is just below next item (dead space for lookahead).
            if (post_residual as i64) < (next_item_size as i64) {
                score += 8.0;
            }
        }
    }

    // Penalize tiny unusable dead space (waste).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Relative to mean residual: prefer bins whose post residual deviates favorably.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discourage opening a brand-new bin when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is huge, a fresh bin may be needed; soften the penalty.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Mild progression scaling: early on, be more conservative about fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size is nearly unusable.
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 3.0;
    }

    // Penalize large post_residual only mildly; a fresh empty bin should not
    // be opened when a decent fit exists.
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.35;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            // Next item would leave unusable sliver — slight penalty.
            score += 4.0;
        }
        // If next item is large and this bin would be nearly emptied, keep
        // this bin for the current item (good chaining).
        if next_item_size >= 60 && post_residual < next_item_size && post_residual < 15 {
            score -= 6.0;
        }
    } else {
        // Last item: prefer zero waste above all.
        score += 2.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.02 * crowding * (1.0 - progress);

    // Compare against mean residual: bins below mean are "fuller", favor them.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Early stream: mild preference for packing into existing bins to keep
    // bin count low; late stream: allow new bins for better future structure.
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate calibration: an empty bin has post_residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin fits well.
        score += 30.0
            + 20.0 * (fitting_bins_count as f64)
            - 10.0 * progress;
        // If the item is huge, a fresh bin is often the cleanest option.
        if item_size >= 70 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / capacity;
    let norm_item = item_size as f64 / capacity;
    let norm_mean = mean_residual / capacity;

    let mut score = post * (1.0 + 0.6 * progress * norm_post);

    // smooth coupling: tight fits rewarded more as stream progresses
    score -= 8.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);

    // penalize leaving residuals that can't hold the next item (smooth gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0) / capacity;
        score += 12.0 * gap * gap;
        let fits_next = (next_item_size as f64 / post.max(1.0)).min(1.0);
        score -= 4.0 * fits_next * (1.0 - norm_post);
    }

    // last-chance bonus: smooth exponential pressure when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 10.0 * scarcity * (1.0 - norm_item) * (1.0 + progress);

    // penalize divergence from mean residual (smooth dispersion term)
    score += 3.0 * (norm_post - norm_mean) * (norm_post - norm_mean) * capacity;

    // mild penalty for bin proliferation
    score += 0.15 * open_bins_count as f64 * norm_post;

    // quadratic dead-space penalty for very small residuals
    if norm_post < 0.1 {
        let d = (0.1 - norm_post) / 0.1;
        score += 6.0 * d * d;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo classes w.r.t. 10 and 12
    let m10 = post_residual % 10;
    let m12 = post_residual % 12;
    let m20 = post_residual % 20;

    // Residuals in "harmonic" classes (multiples of 10/20) are more reusable
    if m10 == 0 {
        score -= 8.0;
        if m20 == 0 { score -= 4.0; }
    } else if m10 <= 2 || m10 >= 8 {
        // near-harmonic: mildly penalize as near-dead space
        score += 3.0;
    } else {
        // awkward mid-class residual
        score += 6.0;
    }
    if m12 == 0 { score -= 3.0; }

    // Dead-space penalty: residual too small for the smallest plausible item
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let nxt_m10 = (post_residual - next_item_size) % 10;
            score -= 6.0 - 0.5 * nxt_m10 as f64;
        } else {
            // next item won't fit here: penalize leaving large unusable gaps
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: any residual is pure waste
        score += 5.0;
    }

    // Capacity fraction thresholds on bin_residual (integer division)
    let q = bin_residual / 25; // 0..4 quarters
    match q {
        0 => score += 2.0,                    // nearly full bin, fine to finish it
        1 => score -= 1.0,                    // 25-49 residual
        2 => score += 1.0,                    // mid-range
        _ => {}
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral-ish baseline, better than a bad fit,
    // worse than a decent fit into an existing bin.
    if bin_residual == bin_capacity {
        // baseline score for a fresh bin: mean residual of open bins guides it
        score = 45.0 + mean_residual * 0.3 - (open_bins_count as f64) * 0.2;
        // open a new bin eagerly when all open residuals are awkward
        if fitting_bins_count > 0 && mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // Slight stream-progression bias: early on, prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (1.0 - progress);

    // Prefer bins whose residual is close to mean (balance exploitation)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range
    // means gaps below ~10 are nearly worthless) get a heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits (waste below 5 is excellent).
    if post_residual < 5 {
        score -= 40.0;
    }

    // Perfect fill: zero residual is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the post-residual, reward keeping this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item almost fits (within 10), mild reward.
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(10) && post_residual < next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate (empty bin): neutral baseline; only attractive when
    // open bins are scarce or the current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64).sqrt() * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for bins below mean residual (keep residuals balanced).
    score += (post_residual as f64 - mean_residual) * 0.1;

    // Late in the stream, waste matters more; early on, keep bins flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item chain
        }
        // Penalize leaving residual slightly larger than next item (dead space trap)
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer below-mean residual (tighter bin)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let tight_exists = mean_residual < (item_size as f64 + 10.0);
        score += if tight_exists { 30.0 } else { 5.0 };
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items into fresh bins can help
        }
    }

    // Late-stream consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64 * 0.05;

    // Reward near-perfect fits strongly (dead space is the enemy)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 250.0;
    } else if post_residual < 20 {
        score -= 100.0;
    }

    // Lookahead (k=2): bonus if the next item can also land in the leftover space
    if next_item_size > 0 {
        if next_item_size <= post_residual && post_residual > 0 {
            score -= 180.0;
        } else {
            // penalize leaving a gap that is too small to be useful for typical items
            let gap = post_residual as f64;
            if gap > 0.0 && gap < 30.0 {
                score += 60.0 * (1.0 - gap / 30.0);
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 350.0;
    }

    // New-bin candidate: penalize opening a fresh bin, more so early in the stream
    if bin_residual == bin_capacity {
        score += 450.0 + 250.0 * (1.0 - progress);
    }

    // Fragmentation coupling: prefer bins whose residual diverges favorably from the mean
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Large items: prefer placing them into already-opened bins rather than fresh ones
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) penalty
    let mut score = pr + 0.6 * pr * pr / cap;

    // Smooth coupling of residual with stream progress: later in stream,
    // dead space is more costly (quadratic in progress)
    score += 8.0 * progress * progress * (pr / cap);

    // Reward tight fits (small post_residual relative to item size) more
    // as the stream progresses: cubic interaction term
    let tightness = 1.0 - (pr / cap);
    score -= 10.0 * progress * tightness * tightness * tightness * fit;

    // Penalize bins whose residual deviates from mean residual (dispersion
    // coupling, smooth quadratic)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: penalize leaving a residual that neither wastes space nor
    // matches the next item; smooth interaction with post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 0.25 * gap + 0.01 * gap * gap / cap;
        // Reward residual that exactly or nearly fits the next item
        score -= 3.0 * (1.0 - gap / cap).max(0.0) * (nxt / cap);
    }

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual as u32 == bin_capacity {
        score += 2.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (subtracts from score).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic classes: reward placing item so post_residual falls into a
    // "usable" residue class for typical small items (residues divisible
    // into common small item sizes are more likely reusable).
    let pr = post_residual;
    if pr > 0 {
        // Residue class via integer division on 10-unit granularity
        // (classic bin-packing item quantum), softened for 1..100 range.
        let class = pr / 10;
        let frac = (pr % 10) as f64;
        // Prefer residues that are exact multiples of 10 (high reuse odds)
        if frac == 0.0 {
            score -= 6.0;
        }
        // Small class index (tiny dead space) is good; large is bad
        score += 0.35 * (class as f64).powi(2) * 0.1;
        // Penalize awkward small remainders (dead space 1..9 that few items fit)
        if frac > 0.0 && pr < 10 {
            score += 12.0;
        }
    }

    // Lookahead: penalize if the next item cannot fit in the post-residual
    // space (this bin becomes dead after this placement).
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 4.0 + 0.15 * (next_item_size - post_residual) as f64;
    }
    // Reward if next item fits snugly after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline cost that
    // grows with how many bins are already open, so we only open new bins
    // when existing fits are poor.
    if bin_residual == bin_capacity {
        score = cap * 0.9
            + 3.0 * open_bins_count as f64
            + (mean_residual / cap.max(1.0)) * 10.0;
        // Opening a new bin is attractive for large items (they ruin bins)
        if item_size >= 60 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 15.0 * progress;
        }
    }

    // Mild preference for filling bins that are already mostly full
    // (best-fit coupling with mean residual).
    let fill_ratio = 1.0 - (bin_residual as f64 / cap);
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host the
    // smallest plausible item are pure waste. Penalize them quadratically.
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size) && post_residual > 0 {
        score += 40.0 + 0.5 * (post_residual as f64);
    }

    // Perfect or near-perfect fits are gold: reward heavily.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward residual closeness to item size (tight fit) proportionally.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin. Strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins fragment capacity; prefer consolidating.
    score += open_bins_count as f64 * 0.6;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when current bins are badly fragmented
    // or mean residual is high while this bin would be fresh.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = open_bins_count as f64 / 10.0;
        let freshness_bonus = mean_residual / bin_capacity as f64;
        score = 25.0 + fragmentation * 8.0 + freshness_bonus * 30.0 * (1.0 - progress) - 12.0;
        // Late in the stream, opening new bins is cheaper than hoarding.
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches next item (perfect 2-step match)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Reward: next item fits into the resulting residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize dead space that cannot host the next item
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits relative to current residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Penalize bins far below mean residual (fragmentation risk), reward near-mean
    let dev = post_residual as f64 - mean_residual;
    score += dev.abs() * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a new bin only when current fits are poor
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Late in the stream: consolidate, discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    } else {
        score -= progress * 5.0;
    }

    // Slight preference for fewer open bins (consolidation)
    score -= open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: heavily favor bins where the item leaves little waste.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that likely cannot be reused by future items.
    if post_residual > 0 && post_residual < item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be picky, penalize loose fits.
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Lookahead coupling: reward this bin if the next item can use the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Bonus for a complementary chain (next item nearly fills it too).
            let nxt_post = post_residual as i64 - next_item_size as i64;
            if nxt_post >= 0 && nxt_post < 15 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: leftover is dead weight; penalize big leftovers.
            let gap = (next_item_size as f64 - post_residual as f64).min(40.0);
            score += 0.15 * gap;
        }
    }

    // Global state: many open bins with slack -> prefer filling existing bins.
    let slack = mean_residual - (item_size as f64);
    if slack > 20.0 && open_bins_count > 2 {
        score -= 6.0;
    }
    // Encourage consolidation when bin count is high relative to progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count as f64 > 4.0 + 30.0 * progress {
        score -= 5.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so new bins are chosen only for genuinely bad fits.
        score += 55.0;
        // If the best existing fit would leave a large unusable gap, allow the new bin.
        if post_residual >= item_size {
            // Placing in an empty bin is structurally clean: mild reward.
            score -= 10.0;
        }
        // Early in the stream, fresh bins are cheap and flexible.
        if progress < 0.2 {
            score -= 15.0;
        }
        // If next item is large and this item is large, a fresh bin preserves pairing.
        if next_item_size >= 50 && item_size >= 50 {
            score -= 12.0;
        }
        // When only one bin fits, never open a new one.
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    } else {
        // Mild preference for fuller bins among open ones.
        score += 0.1 * (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Small stochastic-free tie-breaker on residual ordering.
    score += 0.001 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Late in stream: penalize residual more strongly (tight packing matters).
    score += 40.0 * progress * norm_pr * norm_pr;

    // Reward tight fits: quadratic bonus for small post_residual.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: penalize if next item fits poorly in resulting residual.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Penalize bins deviating from mean residual (smooth coupling).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Many open bins: mild penalty to discourage fragmentation growth.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fills and large residuals favored
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        // dead-space penalty grows for tiny residuals that are hard to reuse
        if pr < 10 {
            score += 25.0;
        }
        // modulo-10 harmonic class: residuals that are multiples of common item sizes
        // (10,20,25,50) are reusable; penalize awkward classes
        let class_bonus = if pr % 10 == 0 {
            12.0
        } else if pr % 25 == 0 {
            10.0
        } else if pr % 5 == 0 {
            5.0
        } else {
            0.0
        };
        score -= class_bonus;

        // integer-division threshold: post_residual bucketed by quarters of capacity
        let quarter = cap / 4.0;
        let pr_bucket = (pr as f64 / quarter).floor();
        score -= pr_bucket * 4.0; // larger residual => better bin to fill
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.5;
            // harmonic match: next item leaves another multiple-of-10 residual
            if (pr - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += (next_item_size - pr).min(40) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: spread usage, slight penalty for over-crowded choice
        score += (fitting_bins_count as f64 - 1.0).min(5.0) * 2.0;
    }

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / cap;
    if fill_ratio > 0.8 {
        score -= 15.0;
    } else if fill_ratio < 0.2 && bin_residual < bin_capacity {
        score += 10.0; // tiny item into a mostly-full bin creates dead space
    }

    // Mean residual alignment: prefer bins close to the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Progress-based new-bin policy: early in stream, allow opening bins more freely
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new empty bin candidate: baseline near capacity residual, discounted early
        score = cap - 20.0 * (1.0 - progress) + 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > cap * 0.5 {
            score -= 10.0; // big next item: fresh bin useful
        }
        if fitting_bins_count <= 1 {
            score -= 25.0; // no good alternative -> opening new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, huge reward
    } else if post_residual <= 10 {
        // Small dead space: barely usable, penalize superlinearly.
        score += (11.0 - post_residual as f64) * (11.0 - post_residual as f64) * 4.0;
    } else {
        // Usable residual: reward larger remaining space mildly (keep bins flexible).
        score -= (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open-bins pressure: many open bins -> prefer filling existing ones,
    // avoid opening new bins; few open bins -> new bin is cheaper.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize creating waste it can't use.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean
    // (it's an outlier with little space), prioritize closing it out.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    }

    // Slight preference for new empty bin early in the stream when many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0 - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: exact match leaves no dead space for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward when the next item fits in the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally.
        let waste = next_item_size - post_residual;
        score += 0.5 * waste as f64;
        // Extra penalty for tiny unusable leftovers.
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Prefer filling bins tighter than the current mean residual.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // perfect 2-step pairing (item + next item fill it exactly).
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0;
        }
    }

    // Late in the stream, consolidate harder into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize small dead space that no future item (>=10 typically) can use,
    // but only mildly when the stream is near its end.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(60.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        // More competing bins: slight penalty to concentrate packing.
        score += 2.0 * (fitting_bins_count.saturating_sub(1) as f64).min(10.0);
    }

    // Prefer bins with residual below mean (tighter bins first), keeping loose bins flexible.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Penalize opening new bins early when many bins are open but nearly empty.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open-bin count and mean fill.
        score += 60.0
            + 1.5 * (open_bins_count as f64)
            - 0.5 * (bin_capacity as f64 - mean_residual)
            - 20.0 * progress;
        // If nothing open can fit except this new bin, opening is cheap.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Late-stream bonus for consolidating into existing bins.
    score -= 10.0 * progress * (1.0 - (bin_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Normalized post residual in [0,1]
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * (1.0 + 0.8 * progress) - 1.7 * x * x * (1.0 - progress) + 1.2 * x.powi(3);
    let mut score = 3.0 * poly;

    // Reward tight fits (small post_residual), stronger late in the stream
    score -= (1.0 - x) * (1.0 + progress);

    // Lookahead: penalize leaving residual that cannot host the next item,
    // reward residual that can host it
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if pr >= next_item_size as f64 {
            score -= 0.6 * nx * (1.0 - x) * (1.0 + 0.5 * progress);
        } else {
            score += 0.8 * (x - nx).max(0.0) * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.5 + 2.0 * (1.0 - x);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Penalize deviation from mean residual (encourage balanced fills)
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: keep it neutral-ish, slightly penalized so it only wins
    // when all open bins fit poorly (large post_residual already dominates)
    if bin_residual == bin_capacity {
        score += 0.5 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Exact-fit and near-fit rewards (harmonic classes 0, small multiples).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, zero waste
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual < eighth {
        score -= 25.0;
    } else if post_residual < quarter {
        score -= 5.0;
    } else {
        // Large leftover: penalize proportionally to how unusable it is.
        score += 0.5 * (pr - quarter);
    }

    // Integer-division threshold classes on post_residual (harmonic buckets of 12).
    let class = post_residual / 12;
    score += match class {
        0 => -10.0,
        1 => 0.0,
        2 => 4.0,
        3 => 8.0,
        _ => 12.0,
    } as f64;

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 0.6 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here; penalize tight leftovers less since bin closes anyway.
            score -= 0.2 * pr;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer filling bins when many are open (consolidation pressure).
    score -= 0.5 * open_bins_count as f64 * (1.0 - pr / cap);

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 40.0 + 0.8 * pr };
        score += desperation;
    }

    // Mild stream progression: late in the stream, waste is costlier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space harshly (gaps too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin before opening a new one: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Open bins pressure: when many bins are open, favor consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.05;

    // Favor bins whose residual is close to the item (tight fit relative to mean residual)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Lookahead: penalize placements that leave residual just barely too small for the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size as f64 {
            score += 5.0;
        } else if post_residual >= next_item_size as f64 {
            score -= 3.0;
        }
    }

    // New bin candidate: make it moderately attractive only when no tight fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0) * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Bonus when the next item exactly fills the bin after current placement
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Penalize small unusable dead space (< 10, minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Reward tight fits relative to residual (waste ratio penalty)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count > 0 {
            let best_possible = post_residual as f64; // residual in fresh bin
            let mean_fit = (mean_residual - item_size as f64).abs();
            if mean_fit < best_possible {
                score += 25.0; // existing bins fit better on average
            }
        }
    }

    // Mild preference toward consolidating many open bins
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late in stream, avoid wasteful placements even more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for the smallest possible item.
    if post_residual < 10 {
        score -= 6.0; // tiny dead space is fine (bin effectively closed)
    } else if post_residual < item_size.min(10) {
        score += 8.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: prefer reusing open bins; only open a new bin
    // when the item would leave a large unusable gap in every open bin,
    // or when the next item would benefit from a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 40.0; // baseline penalty for opening a new bin
        // If next item is large and current residual after placement is small,
        // a fresh bin may serve the lookahead better.
        if next_item_size > 0 {
            if next_item_size as f64 > post_residual as f64 + 20.0 {
                new_bin_score -= 12.0 + 10.0 * progress;
            }
            // If next item exactly complements this item in a fresh bin, favor new bin.
            if item_size + next_item_size == bin_capacity {
                new_bin_score -= 25.0;
            }
        }
        // If open bins are fragmented (high mean residual spread vs this item),
        // opening a new bin is less costly.
        if mean_residual > 30.0 {
            new_bin_score -= 5.0;
        }
        // Late in the stream, avoid proliferation of bins.
        new_bin_score += 10.0 * (1.0 - progress);
        score += new_bin_score;
    }

    // Lookahead coupling: reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize blocking the next item only mildly if residual becomes dead space.
        if post_residual < 10 {
            score -= 2.0;
        } else {
            score += 4.0;
        }
    }

    // Mild preference for filling fuller bins among equals (low mean residual pressure).
    score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64) * (mean_residual / bin_capacity as f64);

    // Slight penalty when many bins are open, encouraging consolidation.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear polynomial shaping.
    // Small residuals are rewarded super-linearly (tight fits), large residuals penalized.
    let mut score = pr * (1.0 + 2.5 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: early on, tolerate residual spread
    // (favor filling fresh bins); late, strongly demand tight packing.
    let progress_coupling = pr * (0.6 * (1.0 - progress) * (1.0 - progress) + 1.2 * progress * progress * norm_pr);
    score += progress_coupling;

    // Dead-space penalty: residuals too small for typical items are quadratic dead weight.
    let dead_threshold = 20.0;
    if pr < dead_threshold {
        let d = (dead_threshold - pr) / dead_threshold;
        score += 15.0 * d * d;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // with smooth quadratic match term.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            let miss = (nxt - pr) / cap;
            score += 8.0 * miss * miss;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are badly fragmented (high mean residual relative to item) or late stream.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - item_size as f64 / cap).max(0.0);
        score += 18.0 + 10.0 * fragmentation * fragmentation - 8.0 * progress;
    } else {
        // Mild reward for using bins tighter than the current mean residual.
        score -= 3.0 * ((mean_residual - pr) / cap).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild quadratic penalty
    score += 0.05 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Harmonic class of post_residual modulo capacity fractions (10 = C/10 granularity)
    let post_class = post_residual % 10;
    // Residuals in classes 1..9 (small leftovers) are near-dead space; penalize,
    // but exact multiples of 10 (class 0) are "harmonic" slots reusable by small items.
    if post_residual > 0 {
        match post_class {
            0 => score -= 6.0,               // perfectly harmonic residual
            1..=3 => score += 8.0,           // worst dead-space class
            4..=6 => score += 3.0,
            _ => score += 1.0,
        }
    } else {
        // Perfect closure of a bin: reward strongly
        score -= 15.0;
    }

    // Integer-division threshold: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            // Reward proportional to how well the next item harmonizes with the residual
            let harmony = (post_residual - next_item_size) % 10;
            score -= 4.0 + 0.3 * (10 - harmony) as f64;
        } else {
            // Residual can't host the lookahead item: dead space likely
            score += 5.0 + 0.2 * next_item_size as f64;
        }
        // Lookahead pairs that exactly fill the bin after two placements
        if item_size + next_item_size == bin_residual {
            score -= 10.0;
        }
    } else {
        // Last item: closing bins is free value
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: it should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Mild default penalty so real bins usually win...
        score += 4.0;
        // ...but if the item leaves a large inharmonic residual in any bin,
        // opening fresh becomes attractive (large item, few fitting bins).
        if post_residual > bin_capacity / 2 && fitting_bins_count <= 2 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * progress;
        // Many open bins with low mean residual -> don't open more
        if open_bins_count > 4 && mean_residual < 20.0 {
            score += 10.0;
        }
    }

    // Mild pressure against accumulating too many open bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small gaps that only tiny items could use: moderate penalty.
        score += 20.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward very tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another.
    if bin_residual == bin_capacity {
        score += 8.0 * open_bins_count as f64;
        // Opening a new bin is more tolerable early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    } else {
        // Mild reward for using existing bins, scaled by how average they are.
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up -> bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; dead space is locked in -> penalty
            // proportional to how much space gets stranded.
            score += 0.4 * post_residual as f64;
        }
    }

    // Prefer bins whose residual is already below average (consolidate waste).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0 * (res - mean_residual).min(50.0) / 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits after this placement: reward closeness of the pair fit.
        let pair_slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - pair_slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally.
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare residual against the mean: favor bins with below-average residual
    // (consolidating fuller bins), penalize dumping into emptier-than-average bins.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // New-bin candidate: only attractive when current bin would leave large dead space
    // and the next item cannot use it.
    if bin_residual == bin_capacity {
        let dead = post_residual as f64;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0; // new bin still wastes space for next item
        } else {
            score -= 5.0 + 0.1 * dead;
        }
        // Early in the stream, opening new bins is cheap insurance.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize large dead space relative to typical item size
    if post_residual > 0 && post_residual < item_size {
        score += 8.0; // residual too small to be useful
    }

    // Last-chance bonus: if this is the only bin that can fit, prefer it strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 6.0; // leaves unusable sliver for the next item
        }
    }

    // New-bin candidate handling: only attractive when existing bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if mean_residual > 0.0 {
            1.0 - (item_size as f64 / mean_residual).min(1.0)
        } else {
            1.0
        };
        score += 20.0 + 15.0 * (1.0 - progress) - 18.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is close to item (best-fit flavor) over huge-mean drift
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    // Late in stream: consolidate, prefer fuller bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic coupling of post_residual with stream progress.
    // Late in the stream, dead space hurts more (progress bends the curve).
    let mut score = post * (1.0 + 1.5 * progress * norm_post);

    // Smooth cubic term: strongly penalize mid-range waste, mildly reward near-full fills.
    score += 8.0 * norm_post * (1.0 - norm_post) * (0.5 - norm_post) * cap * 0.1;

    // Tight-fit reward: item fills most of the bin -> subtract bonus.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: penalize opening a bin unless current bins are poorly usable.
    if bin_residual == bin_capacity {
        let waste_pressure = (mean_residual - post) / cap; // open bins hold slack we can't use
        score += 25.0 - 20.0 * progress - 10.0 * waste_pressure.max(0.0);
    }

    // Mild penalty for spreading across many open bins when mean residual is large.
    score += 0.5 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill classes are golden.
    let pr = post_residual;
    let class = match pr {
        0 => -40.0,                                  // perfect fill
        1..=5 => -12.0,                              // near-perfect sliver
        6..=15 => 6.0,                               // awkward dead zone
        16..=30 => 2.0,                              // medium-small class
        31..=50 => -3.0,                             // mid class, still usable
        _ => 0.0,                                    // large residual, flexible
    };
    score += class;

    // Integer-division thresholds: residual divisible by common item sizes
    // (10/20/25/50) means a future harmonic item can land exactly.
    if pr > 0 {
        if pr % 10 == 0 { score -= 5.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.5; }
        if pr % 50 == 0 { score -= 2.0; }
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= pr {
            // next item fits exactly or in the same harmonic class
            if pr % next_item_size == 0 { score -= 8.0; }
            else if next_item_size >= pr / 2 { score -= 4.0; }
            else { score -= 1.5; }
        } else {
            // next item won't fit here regardless; slight penalty for tiny leftovers
            if pr > 0 && pr < 10 { score += 4.0; }
        }
        // next item exactly fills this bin after current placement
        if next_item_size == pr && pr > 0 { score -= 15.0; }
        let _ = n;
    }

    // Last-chance bonus: only fitting bin, avoid wasting it on tiny items
    if fitting_bins_count == 1 {
        score -= 10.0;
        if item_size >= bin_residual / 2 { score -= 5.0; }
    }

    // Prefer tight bins when many bins are open (consolidation pressure)
    let tightness = 1.0 - (post_residual as f64 / cap_f);
    score -= tightness * (open_bins_count as f64).ln().max(1.0) * 3.0;

    // Early stream: keep bins flexible (favor larger residuals slightly)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / cap_f) * 4.0;

    // Deviation from mean residual: prefer bins near/below mean (balanced packing)
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate: only attractive when item is huge relative to typical
    // residual or nothing fits well; make empty bin moderately costly otherwise.
    if bin_residual == bin_capacity {
        score += 8.0;
        if item_size > 70 { score -= 10.0; }
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= cap_f {
            score -= 4.0; // room for a clean pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0; // moderately wasteful zone
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual <= 10 {
        score += 10.0; // dead space that even the next item cannot use
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: placing into a bin far below mean residual
    // (a large-gap bin) is desirable; near-empty new-bin candidate handled below.
    if (bin_residual as f64) > mean_residual + 15.0 {
        score -= 6.0;
    } else if (bin_residual as f64) < mean_residual - 15.0 {
        score += 4.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (large item, small residuals everywhere). Penalize default new-bin score
    // so it's chosen only when open bins would create dead space.
    if bin_residual == bin_capacity {
        // A fresh bin has full residual: it wins only if open bins are tight.
        score += 45.0 - 0.4 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a new bin anyway
        }
        if item_size >= 70 {
            score -= 20.0; // big items deserve a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect or near-perfect fills (post_residual small).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // exact chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            // penalize large leftover even if next item fits (dead space risk)
            score += 0.15 * slack;
        } else {
            // next item cannot fit in this bin's leftover: penalize proportionally
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let dev = mean_residual - post_residual as f64;
    score -= 0.8 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize the brand-new empty bin candidate unless the item is huge
    // or no open bin fits well (large post_residual in any open bin).
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fits = fitting_bins_count == 0;
        if !(big_item || poor_fits) {
            score += 55.0;
        } else {
            score += 10.0;
        }
    }

    // Early in the stream, be slightly more willing to consolidate (favor open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // Mild penalty when many bins are open: encourage filling existing ones.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is very valuable; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 5.0 * (miss / 100.0);
        }
    }

    // Time horizon: early in the stream, be more exploratory (favor new bins
    // less); late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // When many bins are open with large mean residual, prefer bins below
    // mean residual (consolidation), else prefer filling fuller bins.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // New-bin candidate: only attractive when item is large and no tight
    // alternative exists.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size > 60 {
            score -= 6.0;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild preference for bins that are already quite full.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * fit_norm * fit_norm) * (1.0 + 0.8 * progress * (1.0 - progress));

    // Penalize dead space relative to mean residual across open bins
    score += 0.35 * (pr - mean_residual).abs();

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - fit_norm).powi(3) * (10.0 + 20.0 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: mildly penalize opening new bins early, more late
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * progress * (open_bins_count as f64 / (total_items as f64).sqrt());
    }

    // Lookahead: penalize if post_residual cannot fit the next item, reward if it can
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (1.0 - pr / nxt);
        } else {
            score -= 4.0 * (nxt / pr);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition capacity into quarters.
    let quarter = bin_capacity / 4; // 25
    let post_class = post_residual / quarter; // 0..=4

    // Penalize dead space classes: tiny leftovers (< quarter) are nearly unusable
    // since items are >= 1 but often mid-sized; class 0 residual is the worst waste.
    match post_class {
        0 => score += 18.0,                                  // dead space
        1 => score += 4.0,                                   // awkward
        2 => score -= 2.0,                                   // useful half-ish
        3 => score -= 5.0,                                   // roomy, still fillable
        _ => {}                                              // untouched/new bin
    }

    // Exact-fit harmonic bonus: post_residual divisible by common small classes.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does post_residual fit the next item (k=2)?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward if next item also lands in a good class after placement.
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            } else if next_post < quarter {
                score += 3.0; // creates new dead space
            } else {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; penalize more if we are wasting a good bin.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep fresh bins neutral-ish but not preferred
    // unless the item is large and fits poorly anywhere else.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 12.0 - 10.0 * tightness; // large items slightly favor new bins
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Prefer filling bins that are already below mean residual (balancing).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight preference to keep open bin count low.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize gaps that cannot fit the smallest possible item (1..100 range).
    if post_residual > 0 && post_residual < 12 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits snugly into the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; mildly penalize leaving stranded space.
        score += 6.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full on average.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * mean_residual / 10.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits, leaving chain potential
            let chain_left = post_residual - next_item_size;
            score -= 150.0 - (chain_left as f64) * 0.5;
        } else {
            // next item won't fit here; penalize dead space proportional to gap
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.8;
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful fit)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        // baseline penalty; reduced if item is large relative to capacity
        score += 120.0 - (item_size as f64 * 0.8);
        // but if next item is large too, opening fresh bin is attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Slight preference for tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual so small leftovers dominate.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += tightness * 30.0;

    // Lookahead: if the next item fits exactly into the post residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 25.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't chain here: slight penalty proportional to wasted pairing potential.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates far above the mean (fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Early in the stream, be more willing to open/keep flexible bins; later, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * (1.0 - progress);

    // New empty bin candidate: neutral-to-slightly-high score; only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score = 70.0 + post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening.
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 10.0;

    // Reward high fill ratio, smoothly amplified as stream progresses.
    score -= fit * fit * (30.0 + 50.0 * progress);

    // Penalize dead space relative to mean residual, coupled non-linearly with progress.
    let dead = (pr as f64 - mean_residual) / cap;
    score += dead.abs() * dead * (15.0 + 25.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    } else {
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead coupling: smooth interaction of post residual with next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = norm_pr - nx;
        // Reward when post residual still fits the next item, penalize near-misses.
        score -= (gap.max(0.0)).exp().ln_1p() * 8.0;
        score += (-gap.max(0.0) * 10.0).exp() * (norm_pr * 6.0) * (1.0 - nx);
    }

    // Mild preference to consolidate into fewer bins as stream advances.
    score += (open_bins_count as f64) * (0.5 + 1.5 * progress);

    // New-bin candidate: make it attractive only when item is large or fit elsewhere is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (norm_pr - fit * 0.5).max(0.0);
        score += 25.0 - fit * 40.0 + poor_fit * 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Perfect fit class: post_residual is a multiple of small harmonic units (5,10,20,25)
    let u5 = post_residual % 5 == 0;
    let u10 = post_residual % 10 == 0;
    let u20 = post_residual % 20 == 0;
    let u25 = post_residual % 25 == 0;
    if post_residual == 0 {
        score -= 60.0; // exact fill, ideal
    } else {
        let mut harmony = 0.0;
        if u5 { harmony += 4.0; }
        if u10 { harmony += 6.0; }
        if u20 { harmony += 8.0; }
        if u25 { harmony += 8.0; }
        score -= harmony;

        // Dead-space penalty: residuals in awkward mid-range classes (e.g. 1..9, 11..19)
        let cls = (post_residual / 10) % 4; // harmonic class of the decade
        if cls == 1 || cls == 3 {
            score += 10.0; // awkward odd-decade residuals are hard to refill
        }
        if post_residual < 10 {
            score += 25.0; // tiny unusable sliver
        }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item's size class aligns with residual
            let diff = post_residual - next_item_size;
            if diff % 10 == 0 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - (diff as f64 / cap));
            }
        } else {
            score += 12.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only prefer opening fresh bin if residual here is very tight
    if bin_residual == bin_capacity {
        // neutral base for empty bin; penalize mildly so existing bins with decent harmony win
        score = 0.55 * cap;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Stream progression: late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - frac);

    // Slight preference toward bins below mean residual (balancing)
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 80.0;
    } else {
        // Larger leftovers that can still host typical items get a mild bonus.
        score -= 8.0;
    }

    // Reward bins whose residual exactly matches a plausible future need.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space relative to the lookahead item.
            score += 25.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; penalize the new-bin candidate.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open bins count.
        score += 40.0 + 30.0 * pressure;
        // Opening a new bin is acceptable if all existing fits leave tiny gaps.
        if fitting_bins_count >= 1 && post_residual == bin_capacity {
            // neutral; the per-bin dead-space scores decide.
        }
    } else {
        // Existing-bin placement gets a consolidation bonus scaled by pressure.
        score -= 20.0 * pressure;
    }

    // Prefer bins that are already well-filled (small residual relative to mean).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else if (bin_residual as f64) > mean_residual + 20.0 {
        score += 5.0;
    }

    // Late in the stream, tighten up: avoid leaving any residual at all.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual.min(20) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize dead space that cannot fit the next item (wasted residual).
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.5 * waste;
        // Extra penalty for tiny unusable slivers.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Reward leaving a residual larger than the mean (bin stays useful).
    if (post_residual as f64) > mean_residual {
        score -= 0.3 * ((post_residual as f64) - mean_residual);
    } else {
        score += 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer keeping tight fits (small post residual) in crowded regimes.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;

    // Mild penalty for opening a brand-new bin when other bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space for the next item: penalize proportionally.
            score += 0.10 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins below mean residual (consolidate waste into few bins).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Early in stream: slightly favor opening fresh bins for large items (future flexibility);
    // late in stream: strongly prefer packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive for big items early on, or when nothing fits well.
        let size_frac = item_size as f64 / bin_capacity as f64;
        score -= 8.0 * (1.0 - progress) * size_frac;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        if post_residual > 0 && post_residual < 20 {
            score += 15.0; // opening a bin that ends nearly empty is wasteful
        }
    } else {
        score -= 6.0 * progress; // as stream progresses, prefer reusing open bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: penalize large residuals quadratically (prefer tight fits now).
    // Late stream: penalize residuals more gently but with cubic decay toward 0.
    let norm_pr = pr / cap;
    let t = progress;
    let poly = (1.0 - t) * norm_pr * norm_pr * cap + t * norm_pr * norm_pr * norm_pr * cap;
    score += 0.6 * poly;

    // Reward filling bins tightly: bonus when post_residual is small, amplified late.
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + t);

    // Penalize exact-fit waste relative to item size (dead space coupling).
    let it = item_size as f64;
    score += 0.05 * (pr - (cap - it)) * (pr - (cap - it)) / (cap * cap) * 100.0 * (1.0 - t);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64) / pr.max(1.0));
    }

    // Mild penalty when bin residual deviates strongly from mean residual (balance bins).
    score += 0.3 * ((pr - mean_residual) * (pr - mean_residual)) / cap;

    // New-bin candidate: make empty bins slightly less attractive unless residuals are poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - t) + 0.1 * mean_residual;
    }

    // Slight preference to consolidate: fewer open bins favored.
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "quantum" of dead space we create.
    // Classes on capacity fractions (C=100 nominal, but use actual capacity).
    let quantum = (bin_capacity / 10).max(1); // 10-unit harmonic classes
    let class = (post_residual / quantum) as f64;

    // Reward (subtract) for landing in a "good" harmonic class:
    // post_residual near 0, or large enough to host typical future items.
    if post_residual == 0 {
        score -= 50.0; // perfect fit is always best
    } else if post_residual <= 5 {
        score -= 25.0; // near-perfect, dead space unusable anyway
    } else if post_residual >= 2 * quantum && post_residual <= bin_capacity / 2 {
        score -= 10.0; // still reusable for mid-size items
    } else if post_residual < quantum {
        score += 15.0; // awkward sliver: penalize
    }

    // Integer-division threshold coupling: does the lookahead item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead chains perfectly: strong reward, scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 + 0.3 * tight.min(30.0);
        } else {
            // lookahead cannot use this bin's remainder
            score += 8.0;
            // extra penalty if the dead space is just barely too small (worst case)
            if post_residual > 0 && next_item_size - post_residual <= 3 {
                score += 12.0;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // unless the fit is terrible (creates a sliver).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual > 0 && post_residual < quantum {
            score += 20.0; // undo reward if it wastes the last bin on a sliver
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins fit badly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progression:
        // early on, opening bins is cheap (future items can fill them);
        // late in the stream, avoid proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // If next item is large and current item is small, a fresh bin is attractive
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 10.0;
        }
        return score;
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // in the "consolidating" direction (tighter than average => keep big holes big).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Slight preference for bins with fewer open alternatives when fit is decent.
    if fitting_bins_count > 3 {
        score += 2.0;
    }

    // Harmonic residue check: post_residual mod quantum tells alignment quality.
    let rem = post_residual % quantum;
    if rem == 0 {
        score -= 3.0; // aligned remainder, composable with future quantized items
    } else {
        score += rem as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable sliver (min item is 10)
        } else if post_residual <= 20 {
            score += 18.0; // barely usable
        } else if post_residual <= 35 {
            score += 6.0;
        }
        // Perfect fit is heavily rewarded.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Open-bins pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over wasting it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: fresh bin only attractive when the
    // item is large or existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        let need_new = (item_size as f64 > mean_residual + 15.0)
            || (open_bins_count == 0)
            || (fragmentation > 30.0 && post_residual > 20.0);
        if need_new {
            score -= 35.0 + 20.0 * progress;
        } else {
            score += 45.0; // keep filling existing bins when reasonable
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is big and this bin cannot host it anyway, slight penalty
    // for burning a versatile large residual on a small item.
    if next_item_size > post_residual && post_residual > 40 && item_size < 30 {
        score += 8.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

