    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let poor_fit = (item_size as f64) / (bin_capacity as f64);
        // Base penalty so new bins are not opened frivolously.
        score += 30.0;
        // Reward opening a new bin when open bins are nearly full on average
        // or the item is large and would leave bad fragmentation.
        score -= crowded * 4.0 + poor_fit * 15.0;
    }

    // Fragmentation penalty: small residuals are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
