    // (use existing space) rather than spreading items across bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Mild penalty for bins far below mean residual (unbalanced usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fits)
    let mut score = post;

    // Non-linear polynomial coupling with stream progress:
    // early on, dead space is cheap; later, it becomes costly quadratically.
    let dead_penalty = norm_post * norm_post * cap * (0.5 + 2.0 * progress * progress);
    score += dead_penalty;

    // Smooth reward when post_residual matches the next item's potential fit
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (post - nxt) / cap;
        if fit_gap >= 0.0 {
            score -= (1.0 - fit_gap) * (1.0 - fit_gap) * 8.0 * (1.0 - 0.5 * progress);
        }
    }

    // Last-chance bonus: only one fitting bin — smooth cubic encouragement
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);
    }

    // Mild penalty for scattering across many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * norm_post;

    // Prefer bins below mean residual (consolidating fuller bins) — smooth coupling
    score += 0.3 * (mean_residual - post) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual can host
    // "common" future sizes are valuable; odd tiny residuals are dead space.
    let pr = post_residual;
    if pr > 0 {
        // class by divisibility — residuals divisible by 10 are reusable
        if pr % 10 == 0 {
            score -= 12.0 + (pr / 10) as f64 * 2.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        } else {
            // non-round residual: penalize more when it's tiny (dead space)
            if pr < 10 {
