    // Can the lookahead item fit in the post-residual? Strong reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 30.0 + next_item_size as f64 * 0.5;
            // exact pairing: item + next fills bin completely
            if next_item_size == pr {
                score -= 80.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += (next_item_size - pr) as f64 * 0.3;
        }
    } else {
        // last item: prefer tightest fill
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).abs();
        // big items: open a fresh bin is fine; small items: prefer existing bins
        if item_size >= 50 {
            score -= 10.0 + tightness * 40.0;
        } else {
            score += 15.0 + (50 - item_size.min(50)) as f64 * 0.5;
        }
        // many open bins with slack -> avoid new bin
        if mean_residual > item_size as f64 {
            score += 20.0;
        }
    }

    // Fraction-of-capacity coupling: residual near half capacity is flexible
    let half = bin_capacity as f64 / 2.0;
    let dev = (pr as f64 - half).abs();
    score -= (bin_capacity as f64 / 4.0 - dev).max(0.0) * 0.1;

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * if pr > 0 && pr % 10 == 0 { 1.0 } else { 0.3 };

    // Prefer bins tighter than the mean (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

