}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // 2-step lookahead: perfect chain (post_residual == next_item_size) is ideal
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 30.0; // perfect two-item fill
        } else {
            score += 0.3 * gap; // penalize leftover after next item
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item can't follow here; penalize proportionally to dead space
        score += 0.2 * post_residual as f64;
    }

    // Penalize leaving residuals below min item size (dead space), unless near-full
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for spreading across many open bins early on
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + tightness);

    // Penalize dead space: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    } else {
        // Last item: maximize fill
        score -= 20.0;
    }

    // Time horizon: early on, prefer consolidating into open bins;
    // later, slightly favor compacting残 residual mass
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (mean_residual / (bin_capacity as f64));

    // Prefer bins with below-mean residual (keeps large residuals available)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / (bin_capacity as f64);
        let pressure = if fitting_bins_count > 0 {
            1.0 / (1.0 + fitting_bins_count as f64)
        } else {
            1.0
        };
        // New bin costs a lot when open bins still have room; cheap when tight fits unavailable
        score += 45.0 * crowding - 20.0 * (1.0 - pressure);
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size && item_size < bin_capacity {
            score -= 10.0; // fresh bin helps the lookahead item
        }
    }

    // Mild penalty for proliferating bins when many are already open
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;
    score += 60.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - pr_norm;
    score -= 35.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 25.0 * (1.0 - pr / nxt.max(1.0)) * (0.5 + progress);
        } else {
            score -= 12.0 * (pr / (pr + nxt)) * (1.0 - progress);
        }
    } else {
        score += 10.0 * pr_norm * pr_norm;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins; reward consolidation
    if open_bins_count > 1 {
        let dev = (mean_residual - pr).abs();
        score += 0.15 * dev * (1.0 - progress);
    }

    // New-bin candidate: keep it slightly unattractive unless residual is large
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - item_norm) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: size modulo capacity quartiles
    let item_class = item_size % 4;
    let next_class = next_item_size % 4;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Harmonic pairing: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect harmonic completion
        } else if next_item_size <= post_residual {
            // next fits: reward proportionally to how well it fills leftover
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 15.0 * fill;
        } else {
            // next item cannot fit here: penalize dead space more strongly
            score += 5.0;
        }
        // same harmonic class lookahead bonus
        if next_class == item_class && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Penalize post_residual in awkward "dead zone" classes (small unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    // Harmonic threshold: residuals that are multiples of small common sizes are reusable
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when open bins are bad,
    // but more attractive when many bins are open and mean residual is fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap;
        score += 18.0 - 10.0 * fragmentation - 6.0 * progress;
        // large items prefer a fresh bin
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later (unusable gaps) get heavily penalized.
    let dead_threshold = 10.0_f64.max(item_size as f64 * 0.15);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins open or item is large
        // and would leave a bad gap elsewhere.
        score += open_bins_count as f64 * 6.0;
        score -= (item_size as f64 - 50.0) * 0.5;
        score -= progress * 10.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
            score += 5.0; // next item can't use this gap: mild penalty
        }
    }

    // Prefer bins with below-mean residual (consolidate emptier space).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits (low dead space).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let lookahead_waste = post_residual - next_item_size;
            score -= 100.0 * (1.0 - (lookahead_waste as f64 / bin_capacity as f64));
            if lookahead_waste < 10 {
                score -= 150.0;
            }
        } else {
            // Next item won't fit here; penalize leaving a large residual that
            // could have absorbed the next item had we packed differently.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins tighter than the mean residual (good fits relative to fleet).
    score -= 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins can fit, unless it's early
    // in the stream (hedging) or the fit here is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 0.4 * bin_capacity as f64;
        if open_bins_count > 0 && !poor_fit {
            score += 250.0 * (1.0 - progress);
        } else if open_bins_count > 0 {
            score += 50.0;
        }
    }

    // Mild penalty for spreading across many open bins (consolidation pressure).
    score += 2.0 * open_bins_count as f64;

    // Small tie-breaker: prefer larger item into tighter bin.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post_residual (tight fit) - already the starting point.

    // Penalize leaving awkward dead space: residuals too small for the smallest
    // plausible items (1..100 range) are wasted. Anything < 10 is nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Mid-range dead space (11..=20) is also hard to fill with unknown distribution.
    else if post_residual >= 11 && post_residual <= 20 {
        score += 8.0;
    }

    // Lookahead: reward if the next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate handling: an empty bin has huge post_residual, which already
    // scores badly. Add a mild adaptive penalty that shrinks late in the stream
    // (closing out the stream favors packing existing bins) and grows with open bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Reward using bins whose residual is above the mean (reduces spread,
        // consolidating free space into fewer bins).
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
        // Slight reward for filling bins tighter than average early on.
        score -= 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;

    // Base: prefer minimal post-residual (tight packing), scaled non-linearly.
    let mut score = post + 12.0 * (post / cap).powi(3) * cap;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - (post / cap);
    score -= 30.0 * tightness.powi(2) * (0.5 + progress);

    // Penalize dead space that can't fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 18.0 * (1.0 - post / nxt.max(1.0)) * (1.0 - 0.5 * progress);
        } else {
            score -= 6.0 * (nxt / cap) * (post / cap);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - post / cap).abs();
        score += 20.0 + 25.0 * (1.0 - progress) - 10.0 * fragmentation;
        // Prefer new bin late in stream if mean residual is small relative to item.
        score -= 8.0 * (mean_residual / fit).tanh() * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64 * (post / cap);

    // Smooth global coupling: quadratic in item size vs residual.
    score += 4.0 * ((fit / cap) * (bin_residual as f64 / cap) - (fit / cap).powi(2));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity in 5 equal bands.
    let band = post_residual * 5 / bin_capacity; // 0..=4
    score += match band {
        0 => -18.0, // near-perfect fill: dead space almost zero
        1 => -6.0,
        2 => 4.0,
        3 => 10.0,
        _ => 16.0, // large leftover: wasteful placement
    };

    // Integer-division residue class: post_residual divisible by small
    // harmonic divisors is "usable" by common item sizes.
    let mut usable = 0.0;
    for d in [10u32, 20, 25, 50] {
        if post_residual >= d && post_residual % d == 0 {
            usable += 4.0;
        }
    }
    score -= usable;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot ever fit, penalize dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (bin_capacity as f64 - slack as f64) * 0.25;
            if slack == 0 {
                score -= 12.0; // perfect two-item packing
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bin
    // unless post_residual would be tiny and useless.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        if waste > 0.6 {
            score += 14.0; // too much waste for a forced fit
        } else {
            score -= 9.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when current
    // placement is bad or few bins fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base penalty so open bins usually win
        score += 30.0;
        score -= pressure * 40.0;
        // late in stream with many open bins, prefer consolidating
        score -= (open_bins_count as f64) * 0.3 * (1.0 - progress);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // room for lookahead pairing
        }
    }

    // Prefer filling bins below mean residual (balance-driven consolidation).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Mild tie-break toward tighter fits via item fraction.
    score += (item_size as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let mean = mean_residual.max(0.0).min(cap);

    let is_new = bin_residual == bin_capacity;
    let new_post = bin_capacity.saturating_sub(item_size) as f64;

    let this_hosts_next = next > 0.0 && post >= next;
    let new_hosts_next = next > 0.0 && new_post >= next;
    let dead_for_next = next > 0.0 && post > 0.0 && post < next;

    // Best-fit base: smaller leftover space is better.
    let mut score = post / cap;

    // Exact closure is highly desirable, especially when many bins are open.
    if post == 0.0 {
        score -= 1.05 + 0.03 * open;
    }

    let open_pressure = 1.0 + 0.025 * open;

    // Strict dead-space avoidance: penalize gaps that cannot absorb the lookahead item.
    if dead_for_next {
        let lost = 1.0 - post / next;
        score += (0.45 + 0.55 * lost) * open_pressure;
    }

    // Penalize tiny positive residues, with a threshold damped by the current mean residual.
    let tiny = (0.03 * cap).min(mean.max(1.0));
    if post > 0.0 && post < tiny {
        score += 0.20 * (1.0 - post / tiny) * open_pressure;
    }

    // Reward placements that preserve usable room for the next item.
    if this_hosts_next {
        let tightness = next / post;
        score -= 0.08 + 0.18 * tightness;
    }

    // Last-chance reward for the only existing bin that can fit the item.
    if !is_new && fitting_bins_count == 1 {
        if dead_for_next && new_hosts_next {
            // Do not strongly force this bin if using it creates a dead gap
            // while a new bin could host the next item.
            score -= 0.05;
        } else {
            score -= 0.45 + 0.25 * (item / cap) + 0.15 * progress + 0.01 * open;
        }
    }

    if is_new {
        // Opening pressure grows with open-bin count, stream progress, and existing slack.
        let mut pressure = 0.20 + 0.06 * open + 0.25 * progress + 0.15 * (mean / cap);

        if fitting_bins_count == 0 {
            pressure += 0.0;
        } else if fitting_bins_count == 1 {
            pressure += if new_hosts_next { 0.30 } else { 1.70 };
        } else {
            pressure += if new_hosts_next {
                0.15 + 0.02 * fitting
            } else {
                0.30 + 0.03 * fitting
            };
        }

        score += pressure;

        if new_hosts_next {
            score -= 0.10 + 0.10 * (next / new_post);
        }
    } else {
        // Mild consolidation pressure toward already-open bins.
        score -= 0.005 * open;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step match: post_residual equals next_item_size exactly.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for perfect match, decaying with distance.
        let match_bonus = 60.0 / (1.0 + diff);
        score -= match_bonus;

        // Also reward near matches where next item fits with small slack.
        if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot fit: dead space penalty scaled by gap.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else if next_item_size == 0 {
        // Last item: prefer tightest fit, reward full utilization.
        score -= 20.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Penalize leaving large unusable dead space relative to mean residual.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead * dead;
    } else {
        // Perfect closure: strong reward.
        score -= 80.0;
    }

    // Compare against mean residual: filling a large-residual bin is cheap.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // great 2-step pairing (next item would fill half of it nicely).
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64 - item_size as i64).abs() <= 5 {
            score -= 90.0;
        }
    }

    // Mild preference for compacting the set of open bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 18.0;

    // Penalize dead space that is too small to be useful (below typical small item).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere else or the new bin enables a good pairing with the next item.
    if bin_residual == bin_capacity {
        score += 70.0;
        // Lookahead: if next item pairs perfectly with the residual, encourage new bin.
        if next_item_size > 0 && (next_item_size as u32).saturating_add(post_residual) <= bin_capacity {
            let pair = next_item_size as u32 + post_residual;
            if pair >= bin_capacity - 5 {
                score -= 95.0;
            } else {
                score -= (pair as f64 / cap) * 40.0;
            }
        }
        // Late in the stream, opening new bins is more acceptable (less waste risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 25.0;
    }

    // Lookahead synergy: placing item so residual matches next item is great.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size as u32 {
        score -= 6.0; // residual still usable by next item
    } else if next_item_size > 0 {
        score += 8.0; // residual too small for lookahead item
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating
    // into bins below mean residual (tighter bins), avoid spreading waste.
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * 15.0;
        if open_bins_count > 8 {
            score += 3.0 * (open_bins_count as f64).ln();
        }
    }

    // Mild preference for filling larger fraction of bin overall.
    score -= (item_size as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling: reward tight fits more strongly as stream progresses
    let tight = (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 60.0 * tight * (0.5 + progress);
    // penalize dead space quadratically
    score += 25.0 * norm_pr * norm_pr * (1.0 + progress);
    // last-chance bonus
    if fitting_bins_count == 1 { score -= 20.0 * (1.0 - norm_pr); }
    // lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).abs() as f64 / cap;
        score += 15.0 * gap * gap;
    }
    // mild penalty for spreading across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // "usable" residue classes via integer division thresholds.
    // Small, structured leftovers (0, <=10, <=20) are valuable; large
    // unstructured gaps are penalized.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic band bonus: leftover divisible into common item sizes
        // (mod arithmetic on typical size classes) is reusable.
        if post_residual % 10 == 0 {
            score -= 12.0; // clean class boundary (10/20/30...)
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        }

        // Small leftover is a near-perfect fit: reward quadratically.
        if post_residual <= 10 {
            score -= 40.0 + (10 - post_residual) as f64 * 3.0;
        } else if post_residual <= 20 {
            score -= 15.0;
        } else if post_residual > 50 {
            // Big gap: wasteful unless bin was nearly full anyway.
            score += (post_residual - 50) as f64 * 0.5;
        }

        // Dead-space penalty scaled by fraction of capacity wasted.
        score += (post / cap) * 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // Next item won't fit here: slight penalty for stranding space.
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; it wins only if all
        // existing placements leave terrible residuals (score > ~100).
        score = 90.0
            + (open_bins_count as f64).sqrt() * 5.0
            + (item_size as f64 / cap) * 30.0;
        if next_item_size > item_size {
            score -= 20.0; // big item coming: fresh bin useful
        }
        if step_index as f64 / total_items.max(1) as f64 > 0.9 {
            score += 15.0; // late stream: avoid new bins
        }
    } else {
        // Prefer fuller bins among open bins: reward tight fits.
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= tightness * 25.0;

        // Prefer bins whose residual is below the mean (compact them),
        // pushing toward closing bins.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }
    // General dead-space pressure: gap too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).min(bin_capacity as f64));
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
        // But opening a fresh bin is attractive if the item is large and fits poorly elsewhere.
        if item_size > bin_capacity / 2 && post_residual < item_size / 4 {
            score -= 10.0;
        }
    } else {
        // Slight preference for bins with above-average residual (keep extremes for later).
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: place here if next item exactly fills the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in post residual: strong bonus, scaled by tightness of fit.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.15 * slack;
    }
    // Next item would NOT fit: penalize leaving a residual that traps the next item
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 12.0 + 0.2 * (next_item_size - post_residual) as f64;
    }

    // Tight fit reward: small post residual relative to item size (best-fit flavor).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Penalize residuals that are small and hard to reuse (dead space zone 1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: bins far below mean are more "spent", prefer using them.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the fit here is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // If this bin cannot serve the next item well, new bin becomes attractive.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score -= 55.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Mild penalty for very many open bins (fragmentation control).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a superlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted space
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement (perfect pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Time horizon: early in the stream, be conservative with new bins
    // (long horizon means wasted space compounds); late in stream, allow
    // tighter packing preferences to dominate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.7 + 0.6 * progress;

    // Global state: many open bins with high mean residual -> prefer
    // filling existing bins to consolidate.
    if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
        score -= 15.0;
    }

    // New-bin candidate penalty: only open a new bin when the item is large
    // relative to residual and existing fits are poor. Empty-bin call has
    // post_residual == capacity - item_size; discourage unless item is big.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        // new bin attractive only for large items or when item leaves
        // a residual that likely fits the next item
        let mut new_bin_bonus = 0.0;
        if size_frac > 0.7 { new_bin_bonus -= 20.0; }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_bonus -= 8.0;
        }
        // penalize new bins mid-stream when consolidation is possible
        new_bin_bonus += open_bins_count as f64 * 2.0 * (1.0 - progress);
        score -= new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let tightness = 1.0 - norm_pr;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = progress * progress * (1.0 - progress) * (1.0 - progress) * 4.0;
    score -= poly * tightness * 30.0;
    // penalize large dead space more as stream progresses (smooth quadratic)
    score += norm_pr * norm_pr * (1.0 + progress) * 20.0;
    // reward near-perfect fits smoothly
    let perfect = 1.0 - (pr / cap) * 4.0;
    score -= perfect.max(0.0) * perfect.max(0.0) * 15.0;
    // last-chance bonus (smooth via fitting count)
    let last_chance = (fitting_bins_count == 1) as f64;
    score -= last_chance * (1.0 + progress) * 10.0;
    // lookahead: reward leaving space for next item (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= (1.0 - (gap / cap).min(1.0)) * 12.0;
        } else {
            score += (-gap / cap) * 8.0;
        }
    }
    // penalize spreading across many bins smoothly
    score += (open_bins_count as f64).ln1p() * (1.0 - progress) * 3.0;
    // slight reward for new bin when mean residual is low (smooth)
    score -= is_new_bin * ((cap - mean_residual) / cap).max(0.0) * 5.0;
    // new-bin penalty early to prefer filling open bins
    score += is_new_bin * (1.0 - progress) * 15.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small" residue classes (<= 10) are nearly perfect; reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let small_class = pr <= 10;
    let mid_class = pr > 10 && pr <= 25;
    let dead_class = pr > 25 && pr < item_size.min(next_item_size.max(1));

    if small_class {
        score -= 30.0; // near-perfect fit
    } else if mid_class {
        score -= 8.0;
    }

    // Dead space: leftover too small for the next item but large enough to waste.
    if next_item_size > 0 && dead_class {
        score += 12.0;
    }

    // Exact modulo-harmony: post_residual divisible into capacity nicely
    // (capacity % post_residual == 0 or post_residual divides item_size classes).
    if pr > 0 && (bin_capacity % pr == 0 || (pr <= 50 && 100 % pr == 0)) {
        score -= 6.0;
    }

    // Integer-division threshold: pair current item with next item by class.
    if next_item_size > 0 && next_item_size <= pr {
        // next item fits here: strong reward, scaled by tightness
        score -= (next_item_size as f64 / cap) * 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when
    // open bins exist with good residuals and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * progress;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight preference to keep large residuals for large future items.
    if next_item_size > 60 && post_residual > 60 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size are pure waste — penalize them hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Small but potentially usable gaps: mild penalty scaled by waste ratio.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward very tight fits (best-fit sharpening).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // a reasonable fit exists elsewhere.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.6;
        // Prefer bins with below-average residual (keep large gaps free).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // New-bin candidate: only attractive when current bin would leave a
    // terrible gap or the next item pairs well with a fresh bin.
    if bin_residual == bin_capacity {
        score = 45.0;
        if post_residual >= 10 && fitting_bins_count > 0 {
            score += 40.0; // opening new bins when fits exist is costly
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let pair_waste = (bin_capacity as f64) - (item_size as f64 + next_item_size as f64).min(bin_capacity as f64);
            score += pair_waste * 0.5;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward bins whose post residual exactly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 5.0;
    }

    // Reward below-mean residuals (tight packing relative to fleet).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins unless the fit is bad.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.15 * (bin_residual as f64 - post_residual as f64);
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * 30.0 * (0.5 + progress);

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < item_size.min(40) {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Perfect-fit lookahead: if next item exactly fills post residual, huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // If next item fits into post residual, mild reward for chain packing.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot use the leftover, penalize wasted capacity proportional
    // to leftover size relative to mean residual state.
    else if next_item_size > 0 && post_residual > 0 {
        score += (post_residual as f64) * 0.15;
    }

    // Penalize opening new bins when many bins already exist with slack
    // (mean_residual high) — encourage consolidation.
    if bin_residual == bin_capacity {
        let slack_pressure = mean_residual / (bin_capacity as f64);
        score += 18.0 + 20.0 * slack_pressure + 0.5 * open_bins_count as f64;
        // But late in the stream, a fresh bin for a big item may be cleaner.
        if item_size > 70 && progress > 0.7 {
            score -= 15.0;
        }
    }

    // Mild penalty for leaving residuals that match common awkward sizes (e.g. 51..59).
    if post_residual > 50 && post_residual < 60 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: residual normalized, cubic shaping
    let r = pr / cap; // in [0,1]
    score += 6.0 * r * r * (1.0 - r) * cap * 0.1;

    // Penalize residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = (nx - pr) / cap;
            score += 18.0 * gap * gap * cap + 5.0 * gap;
        } else {
            // reward residual that fits next item, smoothly
            let fit = (pr - nx) / cap;
            score -= 4.0 * (1.0 - (fit * 2.0).min(1.0)) * (1.0 - fit);
        }
    }

    // Tight fit reward: small post residual relative to item size
    let tight = pr / (item_size as f64 + 1.0);
    score -= 8.0 / (1.0 + tight * tight);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Stream progress coupling: later in stream, be more conservative about waste
    score += 10.0 * progress * r * r;
    score -= 3.0 * progress * (1.0 - r);

    // Crowd penalty: many open bins with high mean residual -> prefer filling existing
    let mean_r = mean_residual / cap;
    score += 2.0 * mean_r * (1.0 - r) - 2.0 * mean_r * r;

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) should be rewarded.
    let post = post_residual;
    if post > 0 {
        // Reward leftovers that are multiples of 10 (likely reusable by future items)
        if post % 10 == 0 {
            score -= 8.0;
        }
        if post % 5 == 0 && post % 10 != 0 {
            score -= 3.0;
        }
        // Penalize dead space: leftover too small for the smallest item (1..=100 range,
        // but tiny slivers under ~15 are often unusable)
        if post < 15 {
            score += 25.0;
        } else if post < 25 {
            score += 8.0;
        }
        // Harmonic class via integer division: leftovers in [50, 100) can host
        // half-capacity items; leftovers in [25, 50) a quarter, etc.
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if post >= half {
            score -= 10.0;
        } else if post >= quarter {
            score -= 4.0;
        }
    } else {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is excellent.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            score -= 6.0;
        } else {
            // next item won't fit here; mildly penalize leaving a stranded residual
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or existing bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let frac = item_size as f64 / bin_capacity as f64;
        // Base penalty for wasting an existing bin's residual
        score += 30.0;
        // Large items (harmonic class >= 3/4 capacity) justify a fresh bin
        if frac >= 0.75 {
            score -= 35.0;
        } else if frac >= 0.5 {
            score -= 10.0;
        }
        // If mean residual across open bins is small, a new bin is reasonable
        if mean_residual < frac * bin_capacity as f64 {
            score -= 12.0;
        }
        // Late in the stream, avoid proliferating bins
        score += 5.0 * (1.0 - progress);
        let _ = open_bins_count;
    }

    // Tie-break with mean residual: prefer filling bins below the mean residual
    // (i.e., tighter bins) to consolidate waste.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (1..=12) are nearly unusable for future items.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual as f64) * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or item won't leave useful space.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
        score += 30.0 - crowd * 2.0;
        if fitting_bins_count > 0 {
            score += 15.0; // discourage opening new bin when alternatives exist
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0; // open new bin if next item likely can't fit anywhere
        }
    }

    // Lookahead: reward leaving space that still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Mild open-bin pressure to avoid bin proliferation.
    score += open_bins_count as f64 * 0.5;

    // Progress scaling: pack tighter early, allow slack late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual is good, but too small (<10) is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // 2-step lookahead: strongly reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64); // next item fits, reward tightness
        } else {
            // next item won't fit here; penalize large leftover less if residual near mean
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare residual against mean residual: prefer bins that keep residuals balanced,
    // but favor tighter-than-average bins slightly.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless current bins are nearly full / bad fits.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 10.0; // fresh bin still useful for exact next-item match
        }
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: nonlinear reward for small post_residual
    let pr = post_residual as f64;
    score -= 60.0 * (1.0 - pr / bin_capacity as f64).powi(6);

    // Penalize dead space that cannot fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 35.0 * (ni / 100.0);
        } else {
            // penalize leaving residual just barely too small for next item
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 20.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Discard new-bin preference unless fit is poor
    if bin_residual == bin_capacity {
        // New bin: baseline; attractive only if this bin's fit is bad
        let tight = 1.0 - pr / bin_capacity as f64;
        if tight > 0.5 && fitting_bins_count > 1 {
            score += 200.0; // keep using open bins when fit is decent
        } else {
            score -= 30.0; // poor fit elsewhere -> open new bin
        }
    }

    // Global state coupling: prefer bins below mean residual (balance load)
    let res = bin_residual as f64;
    score += 0.15 * (res - mean_residual);

    // Time horizon: early on, be conservative (favor tight fills);
    // late in stream, favor closing out bins
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * t * (1.0 - pr / bin_capacity as f64);

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: tight-fit reward decays smoothly with progress.
    let fit_norm = pr / cap; // 0 = perfect fit
    let fit_term = fit_norm * fit_norm * (1.0 - fit_norm);
    score -= 25.0 * fit_term * (1.0 + 2.0 * progress);

    // Smooth penalty for large dead space, amplified later in the stream.
    let dead = (fit_norm - 0.5).max(0.0);
    score += 60.0 * dead * dead * (0.5 + progress);

    // Last-chance bin: strong smooth reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * (1.0 - fit_norm) * (1.0 - fit_norm);
    }

    // Lookahead: reward if next item fits into the resulting residual, smoothly weighted.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        // Penalize residuals that waste space for the known next item.
        score += 8.0 * (1.0 - pr / (next_item_size as f64 + pr));
    }

    // Prefer filling existing bins over opening new ones; pressure grows with open count and progress.
    let is_new_bin = bin_residual as f64 == cap && post_residual == bin_residual;
    if is_new_bin {
        let pressure = (open_bins_count as f64 / (1.0 + mean_residual / cap)).max(1.0);
        score += 30.0 + 10.0 * pressure.ln().max(0.0) * (0.5 + progress);
    } else {
        score -= 5.0 * (1.0 - (bin_residual as f64 / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: prefer residuals in
    // "reusable" classes (small, or matching common item sizes).
    let pr = post_residual as i64;
    let nis = next_item_size as i64;

    // Exact-fit reward: zero dead space is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residuals below the minimum item size are wasted.
    if pr > 0 && pr < 10 {
        score += 45.0;
    }

    // Modulo-class analysis on post_residual (capacity 100 harmonic classes).
    let m10 = pr % 10;
    if pr > 0 {
        // Residuals divisible by 10 pair well with the 10..80 item grid.
        if m10 == 0 {
            score -= 8.0;
        } else if m10 == 5 {
            score -= 3.0;
        } else {
            score += (m10 as f64) * 0.7;
        }
    }

    // Lookahead: reward residuals that the next item fits snugly.
    if nis > 0 {
        if nis == pr {
            score -= 40.0; // perfect chain fit
        } else if nis <= pr {
            let slack = (pr - nis) as f64;
            if slack < 10.0 {
                score -= 18.0; // tight fit leaves little waste
            } else {
                score -= 6.0 / (1.0 + slack / 20.0);
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += ((nis - pr).min(80) as f64) * 0.25;
        }
    }

    // Tightness term: filling a bin deeply is good.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * fill * 15.0;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // the item is large and no open bin fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Default penalty so existing bins win unless they are bad.
        score += 30.0;
        // Large items (integer division threshold at half capacity)
        // justify opening a fresh bin.
        if item_size >= bin_capacity / 2 {
            score -= 35.0;
        }
        // If many bins are open but none fit well, a new bin avoids
        // fragmenting further.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins with big residuals.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that create lopsided residual pools.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild pressure against accumulating many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space is worthless
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit is highly rewarded
    }

    // Bonus if the leftover gap can exactly fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 30.0;
        } else if gap_after_next < 10 {
            score += 15.0; // next item would leave dead space here
        }
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or mean residual is too small for the item.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.4;
        if mean_residual < item_size as f64 {
            score -= 55.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Mild stream-progression term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect 2-step chain: this placement leaves exactly
    // enough room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Leftover after serving the next item too: mild bonus proportional
            // to how much slack remains usable.
            let slack = post_residual - next_item_size;
            score -= 8.0 + slack as f64 * 0.25;
        } else {
            // Next item cannot fit here: penalize dead space more sharply when
            // the gap is small (wasted space that nothing can use).
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.9;
        }
    }

    // Reward tight fits relative to current bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Penalize bins that deviate from the mean residual (prefer balanced
    // filling, avoid stranding one near-empty bin).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless the current placement
    // would leave a large, unusable residual. Cost of a fresh bin grows with
    // how many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if next_item_size > 0 {
            ((next_item_size as f64 - post_residual as f64).abs()) * 0.5
        } else {
            0.0
        };
        score += 55.0 + open_bins_count as f64 * 1.5 - poor_fit_penalty;
    }

    // Slight late-stream conservatism: prefer consolidating as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative to capacity used.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: residuals below the smallest item are worthless.
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score += 4.0; // small awkward leftover
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement blocks the next item from this bin.
            score += 8.0;
        }
    }

    // Global state coupling: many open bins with slack -> prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let openness = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score -= 6.0 * openness * (mean_residual / bin_capacity as f64);

    // New-bin candidate: make it unattractive unless it's a great fit / late stream.
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress);
        // Allow new bin when item is huge and nothing else fits well.
        if item_size > 70 && fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    // Mild time-horizon bias: late in the stream, squeeze harder into open bins.
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate
    // residual slightly more since fragmentation matters less.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr) * (1.0 - 0.3 * progress);

    // Smooth cubic interaction: post_residual vs mean residual deviation.
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev * (1.0 + dev.abs());

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // (smoothly scaled by how well the item fills the bin).
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let tightness = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 6.0 * fits_next * tightness * tightness;
        // Penalize leaving residual that no future item likely fits:
        score += 4.0 * norm_pr * (1.0 - fits_next) * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins (encourage consolidation).
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are "clean"
    // because items come in multiples of 10 in classic streams; reward them.
    let clean = post_residual % 10 == 0;
    if clean {
        score -= 8.0;
    } else {
        score += (10 - post_residual % 10) as f64 * 0.6;
    }

    // Harmonic class of item_size relative to capacity quarters.
    let quarter = bin_capacity / 4;
    if item_size % quarter == 0 {
        score -= 3.0; // item aligns with capacity grid
    }

    // Integer-division thresholds on post_residual: small dead space is bad.
    let dead_class = post_residual / 10; // 0..10
    if dead_class <= 2 && post_residual > 0 {
        score += (3 - dead_class) as f64 * 5.0; // tiny unusable slivers penalized
    }

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does next item fit harmonically in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward if next item leaves a clean residual too (chained packing)
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 6.0;
            }
            // Reward if next item exactly fills
            if next_post == 0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; slight penalty for wasting capacity
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only prefer it when this bin's fit is poor.
    if bin_residual == bin_capacity {
        // Base new-bin score near mean residual of open bins.
        score = mean_residual * 0.8 + 10.0;
        if post_residual == 0 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Stream progression: late in stream, be greedier about filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, favor tight bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.3;
    }

    // Prefer bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space much more strongly than large leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins,
    // but allow new bins when existing ones would leave tiny gaps.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // unless it creates a tiny dead gap.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual > 0 && post_residual < 10 {
            score += 60.0; // re-apply dead-space penalty
        }
    }

    // New-bin candidate: only attractive if all open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, avoid opening bins with small expected leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        } else {
            score -= gap as f64 * 0.3;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space that even the next item cannot use
    }

    // Prefer bins whose residual is already below average (filling fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with superlinear dead-space penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: exact match between post_residual and next item is ideal
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64));

        // Perfect chain: item fills bin, next item exactly fills... prefer this strongly
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item fits in the residual left behind -> good two-item packing
        if next_item_size <= post_residual {
            score -= 12.0 + 0.2 * next_item_size as f64;
        } else {
            // Next item won't fit here: residual risks becoming dead space
            score += 8.0 + 0.15 * (post_residual as f64);
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Relative to mean residual: placing into a bin with above-average residual is good
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Avoid fragmenting when many bins are open; encourage consolidation
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when current item leaves huge unusable gap
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score = 55.0 + 20.0 * bad_fit - 0.1 * post_residual as f64;
    }

    score
}
